window.SLI18N && window.SLI18N.register({
  en: {"vault.nav_home": "Home", "vault.nav_rewards": "Rewards", "vault.chip": "offline · air-gapped · sovereign", "vault.h1_a": "The safe that", "vault.h1_grad": "never talks to the network", "vault.hero_desc": "<strong>Vault</strong> is the universal offline safe for Engine-class apps. It stores private keys and login signatures with <strong>zero internet permission</strong>, seals them inside the phone's secure silicon, signs with your fingerprint, and moves keys to new hardware through light alone — a QR code. Not \"we promise not to connect.\" <strong>It cannot connect.</strong>", "vault.btn_ceremony": "▶ Try the signing ceremony", "vault.btn_migration": "⟳ Key migration", "vault.btn_audit": "↗ Audit the crypto layer", "vault.stat_internet": "INTERNET permissions in manifest", "vault.stat_tee": "hardware-sealed keys", "vault.stat_wallet": "wallet custody &amp; handover", "vault.stat_qr": "the only exit for a key", "vault.tag_demo": "RECREATED FROM THE DEMO FILM", "vault.title_demo": "Hold the safe in your hands", "vault.sub_demo": "On the left, the real Vault app: the SPARK wallet view — a balance that is nothing but the sum of signed transactions, with handover always one bottom-bar tap away. In the middle, the vault status page listing every app key it guards — press <b>Sign</b> and watch the biometric ceremony. On the right, what the phone itself reports about its own isolation.", "vault.wallet_title": "SPARK Wallet", "vault.wallet_sub": "Vault custody · signed tx chain", "vault.wallet_balsub": "balance = Σ signed transactions", "vault.wallet_handover": "⇄ Wallet handover", "vault.wallet_keys": "Keys: 3", "vault.vs_title": "Guarded keys", "vault.vs_fingerprint": "fingerprint", "vault.vs_algorithm": "algorithm", "vault.vs_sealed": "sealed", "vault.vs_sealed_val": "Keystore TEE · AES-256-GCM", "vault.vs_lastreq": "last request", "vault.vs_waiting": "waiting…", "vault.vs_sign": "Sign Engine request", "vault.vs_migrate": "⟳ Migrate to new device", "vault.bio_touch": "Touch the sensor", "vault.bio_title": "BiometricPrompt", "vault.bio_desc": "The key never leaves the TEE — it signs inside secure hardware.", "vault.console_head": "adb shell — air-gap self-check", "vault.sim_caption": "<b>Every event above is local.</b> The console has nothing to report from the network — because there is none.", "vault.tag_guards": "WHAT IT GUARDS", "vault.title_guards_a": "One job: be the", "vault.title_guards_grad": "safe of every sovereign app", "vault.sub_guards": "Vault is app-agnostic by design. Anything shaped like Engine — an app that wants online life with offline keys — can delegate its identity to the safe.", "vault.card1_t": "App private keys", "vault.card1_d": "ECDSA P-256 identities generated by apps like Engine, sealed the moment they arrive.", "vault.card2_t": "Login &amp; wallet signatures", "vault.card2_d": "Challenge-response login codes and SPARK wallet transactions — signed inside the safe, never stored online. Every balance change is a signed transaction on an append-only chain.", "vault.card3_t": "Device migration bindings", "vault.card3_d": "Signed re-bind records that move your identity to fresh hardware without a cloud backup.", "vault.card4_t": "Fingerprint directory", "vault.card4_d": "A local registry of every guarded key, its fingerprint and seal state — visible at a glance.", "vault.card5_t": "Nothing else", "vault.card5_d": "No browsing, no sync, no ads, no telemetry. A safe with a screen, not a smartphone app.", "vault.card6_t": "Biometric-only unlock", "vault.card6_d": "Every unseal passes BiometricPrompt with a ±120s freshness window — clock-based replay protection.", "vault.tag_ceremony": "HOW AN ONLINE APP SIGNS OFFLINE", "vault.title_ceremony_a": "The key signs.", "vault.title_ceremony_grad": "The key never leaves.", "vault.pl1": "Engine needs a signature", "vault.pl2": "IPC request + challenge", "vault.pl3": "BiometricPrompt", "vault.pl4": "TEE unseals &amp; signs", "vault.pl5": "signed callback", "vault.pl6": "Engine verifies sig + Δt&lt;120s", "vault.co_tag": "WHY THE ±120s WINDOW MATTERS", "vault.co_text": "The callback signature covers <b>sessionId ‖ status ‖ timestamp</b>. Even a stolen callback cannot be replayed minutes later — the clock is part of the proof. The relay never sees the key; Engine never holds the key; <b>only the TEE ever does.</b>", "vault.tag_migration": "NEW PHONE, SAME IDENTITY", "vault.title_mig_a": "Moving house through", "vault.title_mig_grad": "a beam of light", "vault.sub_migration": "Private keys are the one thing you must never trust to a cloud. When your hardware changes, Vault walks your identity across devices screen-to-screen — step through it below.", "vault.migprev": "Prev", "vault.mignext": "Next", "vault.flag_t": "FLAG_SECURE", "vault.flag_d": "The QR screen blacks out screenshots and screen recordings. Shoulder-surfing is the only attack left.", "vault.payload_t": "Encrypted payload", "vault.payload_d": "The bind URI carries an encrypted session payload — the raw private key never appears in any URI.", "vault.burn_t": "Burn after binding", "vault.burn_d": "Engine calls convertBoundToPublicKeyOnly() — its private-key copy is wiped the moment Vault takes over.", "vault.title_compare": "Where do keys sleep tonight?", "vault.th_storage": "Storage model", "vault.th_network": "Network reach", "vault.th_extraction": "Extraction risk", "vault.th_migration": "Migration path", "vault.tr_ext_t": "Browser extension wallet", "vault.tr_ext_reach": "always online", "vault.tr_ext_risk": "high — memory &amp; disk readable", "vault.tr_ext_mig": "seed phrase on paper", "vault.tr_hot_t": "Hot server / custodial", "vault.tr_hot_reach": "24/7 attack surface", "vault.tr_hot_risk": "systemic — one breach, all keys", "vault.tr_hot_mig": "trust the operator", "vault.tr_cloud_t": "Cloud key backup", "vault.tr_cloud_reach": "synced by design", "vault.tr_cloud_risk": "account compromise = key compromise", "vault.tr_cloud_mig": "re-download", "vault.tr_vault_reach": "no INTERNET permission", "vault.tr_vault_risk": "TEE silicon + biometric gate", "vault.tr_vault_mig": "QR light channel, signed re-bind", "vault.co2_tag": "PHYSICS, NOT PROMISES", "vault.co2_text": "Every other row in that table depends on someone behaving well. Vault's isolation is declared in the Android manifest and enforced by the OS — <b>a packet cannot be sent, so a promise is never needed.</b>", "vault.foot_desc": "An independent interpretation of the eneatlnc-cell Loop. The E2EE protocol stack is open for audit; every claim traces back to code and whitepapers.", "vault.foot_layers": "Layers", "vault.foot_engine": "sovereign social", "vault.foot_vault": "offline custody", "vault.foot_havix": "L0 · parallel identity", "vault.foot_spark": "the fuel", "vault.foot_rewards": "referral policy", "vault.foot_loop": "The Web4 Loop", "vault.foot_repos": "Repositories", "vault.foot_bottom": "Keys offline · SBT governance · $SPARK fuel · AI chartered", "vault.log_settle_pre": "metered batch co-signed inside TEE → tx #", "vault.log_settle_suf": " appended to chain · balance = Σ signed txs", "vault.log_handover": "handover certificate signed · full balance migrates to the new device as a genesis tx", "vault.log_bio_dismiss": "biometric prompt dismissed", "vault.log_ipc_pre": "IPC request received · challenge=0x", "vault.log_ipc_suf": " · waiting for biometrics", "vault.sig_result": "✓ signed · ECDSA P-256 · TEE", "vault.log_bio_ok": "BiometricPrompt ✓ → key unsealed in TEE → signed inside secure world → re-sealed", "vault.log_callback": "callback verified: sig(sessionId‖status‖ts) ✓ · Δt &lt; 120s ✓", "vault.mig1_title": "New device generates a fresh keypair", "vault.mig1_desc": "The new phone creates its own ECDSA P-256 identity inside Engine. Nothing is imported over the air — ever.", "vault.mig2_title": "Old Vault exports a migration binding", "vault.mig2_desc": "The old Vault seals an authorization onto a QR frame. FLAG_SECURE keeps screenshots black; the key itself never leaves the TEE.", "vault.mig3_title": "New Vault scans — optical channel only", "vault.mig3_desc": "ML Kit reads the frame through the camera. The only network involved is light.", "vault.mig4_title": "Identity re-bound to the new key", "vault.mig4_desc": "A signed re-binding callback migrates your DID to the new device's public key. Contacts verify the new fingerprint automatically.", "vault.mig5_title": "SPARK custody hands over too", "vault.mig5_desc": "The old Vault signs a handover certificate that terminates its chain with the full balance; the new Vault verifies it and continues the ledger with a genesis transaction — no balance ever exists un-signed.", "vault.mig6_title": "Old copy burned, zero residue", "vault.mig6_desc": "The old Vault wipes the sealed key with zero-overwrite. Migration complete — no key ever touched the internet.", "vault.log_boot1": "AndroidManifest: uses-permission INTERNET → <b>not found</b> ✓", "vault.log_boot2": "network stack: unreachable · sockets: none · telemetry: none", "vault.log_boot3": "Keystore TEE alive · keys sealed (AES-256-GCM) · biometrics armed", "vault.log_boot4": "SPARK wallet chain armed · HWM anti-replay · handover ready", "whitepaper.nav_home": "Home", "whitepaper.nav_rewards": "Rewards", "whitepaper.kicker": "// PROJECT WHITEPAPER", "whitepaper.chip": "VERSION 1.0 · DRAFT", "whitepaper.h1": "SPARK <span class=\"grad\">&amp; the Web4 Sovereignty Loop</span>", "whitepaper.hero_desc": "Four organs — <strong>Vault</strong>, <strong>Engine</strong>, <strong>Aether</strong>, <strong>Havix</strong> — form one closed loop, and <strong>SPARK</strong> is the fuel that makes it turn. The E2EE protocol stack is open for audit; this document describes the architecture as built, the token economics as designed, and the dual-track launch: a whitelisted presale followed by a public LBP-based IDO.", "whitepaper.meta_1": "AUGUST 2026", "whitepaper.meta_2": "4 REPOSITORIES · AGPL + APACHE", "whitepaper.meta_3": "PRESALE WHITELIST OPEN", "whitepaper.meta_4": "SUPPLY 1,000T SPARK", "whitepaper.stat_dao": "DAO reserve — governance-gated", "whitepaper.stat_tge": "liquid at TGE (incl. 10% LP)", "whitepaper.stat_cap": "presale cap per wallet", "whitepaper.stat_kb": "SPARK per message kilobyte", "whitepaper.abstract": "<b>Abstract.</b> Web3 gave users wallets but kept their social lives on servers. The Web4 prototype loop closes that gap with <mark class=\"key\">physical isolation</mark>: an online social app (<strong>Engine</strong>) that holds no keys, an offline safe (<strong>Vault</strong>) that holds keys and never connects, an SBT-governed parliament (<strong>Aether</strong>) that banks the fuel reserve, and a parallel-identity network (<strong>Havix</strong>) — master-DID derived, running a credit-and-value dual economy — that charters AI under a living constitution. <strong>$SPARK</strong> is the single issued asset that meters expression in the app, endows the DAO reserve, and flows between them — fuel for the loop, never a vote. This whitepaper documents the architecture as it exists in the public repositories, then specifies the token: utility, allocation (10% presale / 20% IDO / 10% DEX liquidity / 50% DAO reserve / 10% community incentives), the two-phase launch, the unlock schedule, and the safeguards that keep the launch fair and the reserve sovereign.", "whitepaper.toc1": "The Sovereignty Loop", "whitepaper.toc2": "Architecture: Isolation &amp; Identity", "whitepaper.toc3": "The Four Organs", "whitepaper.toc4": "SPARK Token Economics", "whitepaper.toc4b": "The Dual-Track Launch", "whitepaper.toc5": "Governance of the Reserve", "whitepaper.toc6": "Roadmap to TGE", "whitepaper.toc7": "Risks &amp; Disclaimers", "whitepaper.ch1": "The Sovereignty Loop", "whitepaper.ch1_p1": "This is <b>one project, not a portfolio of products</b>. Each repository is an organ; the organs share one bloodstream — SPARK. A user chats in Engine; every message burns fuel; fuel is banked in the Aether reserve; the reserve is kept liquid by chartered AI on Havix; Havix's network effects keep Engine alive; and Engine's demand gives SPARK its physical backing. Cut any organ and the loop stops turning.", "whitepaper.th_organ": "Organ", "whitepaper.th_metaphor": "Metaphor", "whitepaper.th_function": "Function in the loop", "whitepaper.th_status": "Real status", "whitepaper.rv_mt": "the Safe", "whitepaper.rv_fn": "Offline custody of every private key; signs by proxy; migrates keys by QR only", "whitepaper.rv_st": "v3.70.0 shipped", "whitepaper.re_mt": "the App", "whitepaper.re_fn": "Sovereign social messenger; pure-memory, E2E-encrypted; spends SPARK by the kilobyte", "whitepaper.re_st": "v3.64.7 shipped", "whitepaper.rs_mt": "the Fuel", "whitepaper.rs_fn": "Meters expression; endows the reserve; bridges reserve and markets", "whitepaper.rs_st": "presale + IDO", "whitepaper.ra_mt": "the Parliament", "whitepaper.ra_fn": "SBT-governed DAO: three chambers, soulbound ranks, multisig treasury", "whitepaper.ra_st": "v3.6 · BSC · audit closed · mainnet pending", "whitepaper.rh_mt": "the Identity Root", "whitepaper.rh_fn": "Master-DID derived parallel identities: 4-context derivation, credit-and-value dual track, AI charter plane", "whitepaper.rh_st": "M10 closed beta", "whitepaper.rig_mt": "the Brain", "whitepaper.rig_fn": "Node-level AI that reasons with its own identity", "whitepaper.rig_st": "future stage", "whitepaper.ch1_meta": "The metaphors are the architecture: the <mark class=\"key\">Safe never touches the network</mark>, the <mark class=\"key\">Parliament rules by soulbound SBT</mark>, the <mark class=\"key\">Brain is licensed, not trusted</mark>. Everything below is traceable to public code<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>.", "whitepaper.ch2": "Architecture: Isolation &amp; Identity", "whitepaper.h21": "Physical isolation as a security model", "whitepaper.ch2_p1": "The loop's root security decision is <b>separation by physics, not by policy</b>. Engine runs online but holds zero private keys; Vault holds the keys and is built with <mark class=\"key\">no network permission at all</mark> — its Android manifest declares no INTERNET permission, making exfiltration a physical rather than logical problem<sup><a href=\"#cite-3\">[3]</a></sup>. Signing requests travel from Engine to Vault over signature-protected IPC; key material travels between devices only as encrypted QR frames — camera-to-camera, air-gap enforced<sup><a href=\"#cite-3\">[3]</a></sup>.", "whitepaper.ch2_p2": "The trust is auditable: Engine's <span class=\"mono\">core/</span> modules (protocol, crypto, IPC) are <b>byte-identical</b> to Vault's, so both apps verify against the same public source<sup><a href=\"#cite-1\">[1]</a></sup>. Messages are end-to-end encrypted with ECDH key agreement and AES-256-GCM; the relay sees envelopes, never plaintext<sup><a href=\"#cite-1\">[1]</a></sup>.", "whitepaper.h22": "One identity, four unlinkable contexts", "whitepaper.ch2_p3": "Havix derives four context-specific sub-identities from a single master key using HKDF — public, market, tunnel and wiki contexts<sup><a href=\"#cite-6\">[6]</a></sup>. The derivation is cryptographically unlinkable: your market persona cannot be correlated with your private correspondence. This is what lets one person be simultaneously <mark class=\"key\">a citizen in the Parliament, a trader in the market, and a private person in chat</mark> — without three accounts and without a platform holding the mapping.", "whitepaper.h23": "Three planes, one loop", "whitepaper.ch2_li1": "<b>Application plane (online):</b> Engine — user-facing, keyless, pure-memory. Messages exist in RAM; the attack surface for seizure is roughly zero.", "whitepaper.ch2_li2": "<b>Custody plane (offline):</b> Vault — keystores sealed behind biometrics, export only via QR.", "whitepaper.ch2_li3": "<b>Coordination plane (off-chain P2P):</b> Havix — identity derivation, reputation/credit ledgers, arbitration, and the charter that licenses AI<sup><a href=\"#cite-6\">[6]</a></sup>.", "whitepaper.ch2_li4": "<b>Settlement plane (on-chain):</b> Aether on BNB Smart Chain — governance, treasury and timelocked execution, governed by soulbound SBT rank rather than transferable token supply<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch2_p4": "Havix's own roadmap formalizes this as a three-layer stack — network bedrock (L0), cognitive execution (L1, Germ), on-chain governance (L2, Aether) — with the 4-context DID enforcing the cryptographic separation between layers<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch3": "The Four Organs", "whitepaper.h31": "Vault — the Safe", "whitepaper.note31": "v3.70.0 · shipped", "whitepaper.ch3_p1": "A generic offline keystore, not an Engine accessory: it can custody keys for any compliant app. Mechanism: no network permission; keystores sealed in the TEE; biometric-gated signing (StrongBox-backed where available); SPARK wallet custody — the balance lives as an append-only chain of transactions co-signed inside the secure world, and a wallet handover migrates the full balance to a new device as a genesis transaction; QR-only migration to new hardware, with the private key never entering a network stack<sup><a href=\"#cite-3\">[3]</a></sup>. Since v3.40 Engine reaches Vault over a signature-protected Binder IPC direct channel — the legacy cross-app jump dialogs are gone<sup><a href=\"#cite-3\">[3]</a></sup>.", "whitepaper.ch3_p2": "The market entry point of the whole loop: a sovereign social messenger with pure-memory architecture, group messaging, a 60-emoji expression economy and DID profiles<sup><a href=\"#cite-1\">[1]</a></sup>. Its economic engine is already specified in the repository: <mark class=\"key\">one kilobyte costs ten SPARK</mark> — every message is metered by its UTF-8 size, rounded up, with a floor of ten SPARK per message; a daily fuel subsidy of 1,000 SPARK (idempotent per calendar day, ruled by the authoritative ledger, gated by a bound Vault identity); heavy users top up from a wallet<sup><a href=\"#cite-2\">[2]</a></sup>. The wallet balance is not a stored number: it is the derivation of an append-only chain of transactions co-signed by the Vault-held wallet key — every change of balance, without exception, is a signed transaction<sup><a href=\"#cite-2\">[2]</a></sup>. Client-side pre-deduction is implemented; a standalone spark-ledger service settles balances server-side<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.h33": "Aether — the Parliament", "whitepaper.note33": "v3.6 · BSC · audit closed · mainnet pending", "whitepaper.ch3_p3": "An SBT-governed DAO kernel on BNB Smart Chain. Weight is earned, not bought: AetherRing mints 14 non-transferable soulbound ranks; three chambers (Council, Parliament, Elders) plus a citizen referendum check one another through a 7-stage proposal lifecycle with an elder veto; the treasury is a 3/5 Safe multisig executing timelocked calls<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>. The deliberate design tension: <mark class=\"key\">governance is soulbound (SBT) while the fuel is a real, issued asset</mark> — whales can buy $SPARK, but $SPARK buys messages, not votes. One contract stands apart: AetherDonation is an <b>external philanthropy channel</b> (USDC tips for public goods) and is independent of the loop's economics.", "whitepaper.h34": "Havix — the Identity Root", "whitepaper.note34": "validated · standby", "whitepaper.ch3_p4": "The coordination network beneath the loop: eight modules (identity, message-types, credit, vouch, wiki, arbitration, market, s-node runtime), 1,174 passing tests (MVP 980 + validation experiment 194, M10 audit baseline), and a two-round audit program — M9 closed all 15 findings, while the M10 deep audit surfaced 52 more (5 P0 + 15 P1 + 32 P2) with P0/P1 remediated before closed beta<sup><a href=\"#cite-6\">[6]</a></sup>. Its charter plane is what puts AI on a legal footing rather than a magical one: routine operations execute automatically with receipts; <mark class=\"key\">red-line operations are physically routed to a human, on-chain vote</mark>. The charter store and interceptor are scheduled as the M11 workstream<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.h35": "Germ — the Brain, later", "whitepaper.ch3_p5": "Germ is the node-level AI layer: AI that reasons with its own 4-context identities on the Havix network. It is intentionally deferred — <mark class=\"key\">Engine is today's market entry</mark>; the Brain arrives when the loop has users worth caring for. In this whitepaper Germ appears only where the economics must reserve room for it (reserve AI, §5).", "whitepaper.ch4": "SPARK Token Economics", "whitepaper.h41": "Utility: fuel with physics behind it", "whitepaper.ch4_p1": "SPARK is a <b>metering asset</b>. In Engine, every kilobyte costs 10 SPARK — metered by message size, rounded up, minimum 10 per message — the meter is in the protocol, not the terms of service<sup><a href=\"#cite-2\">[2]</a></sup>. Budgets derive from a real 100&nbsp;Mbps relay baseline: text envelopes up to 40&nbsp;KB, media up to 48&nbsp;KB, a 128&nbsp;KB hard frame ceiling, groups capped at 200<sup><a href=\"#cite-1\">[1]</a></sup>. Because every expressive byte costs fuel, spam has a marginal cost and speech stays free.", "whitepaper.ch4_li1": "<b>Acquire:</b> daily fuel subsidy (1,000 SPARK per calendar day, idempotent, gated by a bound Vault identity<sup><a href=\"#cite-2\">[2]</a></sup>), wallet top-up<sup><a href=\"#cite-2\">[2]</a></sup>, or market purchase after TGE.", "whitepaper.ch4_li2": "<b>Spend:</b> messaging fuel; group and media budgets; SDK app usage.", "whitepaper.ch4_li3": "<b>Hold:</b> the DAO treasury holds SPARK as its long-term reserve — demand from real usage accrues to every holder symmetrically.", "whitepaper.ch4_note": "◇ Design parameters (vesting lengths, LP lock, fee routing, allowance decay) are recommended defaults of this draft; each is confirmed or amended by governance before the presale opens. On-chain metering rates (1 KB = 10 SPARK, minimum 10 per message; 1,000 daily fuel subsidy per calendar day) are fixed in the Engine specification<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.h42": "Two phases of the same asset — metering ledger, then fixed supply", "whitepaper.ch4_p2": "SPARK ships in two deliberate stages, and the sequence is the design. <b>Phase A — metering ledger (live today):</b> inside shipped Engine software, SPARK exists as an off-chain hash-chained ledger. Each device mints <b>1,000 per calendar day</b> through a Vault-countersigned fuel subsidy — anti-sybil defenses are already in production: a TEE/DRM device anchor, relay-side daily deduplication of unlinkable device hashes, and an amount whitelist enforced at the signing gate. Phase A balances are <mark class=\"key\">not transferable, not tradable, not convertible</mark> — today they are quota, not securities.", "whitepaper.ch4_p3": "<b>Phase B — TGE mapping (planned):</b> the fixed <b>1,000T supply</b> takes effect at TGE. Initial supply combines the presale, IDO, liquidity and reserve tranches of §4.3 with a snapshot-based mapping of Phase A balances into the community-incentive tranche — specific conversion parameters are draft defaults ◇ confirmed by governance before the presale opens. After TGE, SPARK circulates freely, <b>including open USDC and other stablecoin pairs</b>. The conversion channel is deliberately unbuilt today: device anchoring, daily dedup and amount whitelisting must exist <i>before</i> there is a vault to defend, so that the day convertibility opens, these defenses graduate from quota hygiene to vault gates.", "whitepaper.h43": "Supply &amp; allocation", "whitepaper.ch4_p4": "Total supply is fixed at <b>1,000T SPARK (1,000,000,000,000,000 — one thousand trillion)</b>. Allocation follows the 10 / 20 / 10 / 50 / 10 split: presale, IDO, DEX liquidity, DAO reserve, community incentives. There is <mark class=\"key\">no team tranche, no insider allocation, no marketing tranche</mark> — the team's upside is the 50% reserve it shares with the DAO, unlocked only through public governance and capped by charter at ≤5% of the reserve per year.", "whitepaper.fig1": "Figure 1 — SPARK allocation at TGE (refined: 10 slices, 5 tranches)", "whitepaper.fig1_sub": "Total supply 1,000T (1,000,000,000,000,000). Presale splits 2.5% at TGE + 7.5% vesting; IDO splits 5% at TGE + 15% vesting (both tranches: 25% at TGE, then 9-month linear); reserve sub-splits are charter-bounded draft defaults ◇ with release capped at ≤5%/yr — the reserve itself has no calendar unlock.", "whitepaper.th_tranche": "Tranche", "whitepaper.th_share": "Share", "whitepaper.th_amount": "Amount", "whitepaper.th_unlock": "Unlock", "vault.foot_home": "Home", "whitepaper.ch4b": "The Dual-Track Launch", "whitepaper.h44": "Phase 1 — Presale (10%)", "whitepaper.h45": "Phase 2 — IDO (20%)", "whitepaper.h46": "Liquidity &amp; DEX (10%)", "whitepaper.h47": "Unlock schedule", "whitepaper.h48": "Safeguards &amp; compliance", "whitepaper.h32": "Engine — the App", "whitepaper.note32": "v3.64.7 · shipped", "whitepaper.ch5": "Governance of the Reserve", "whitepaper.ch6": "Roadmap to TGE", "whitepaper.ch7": "Risks &amp; Disclaimers", "whitepaper.fig2": "Figure 2 — Circulating supply after TGE", "whitepaper.m1": "presale — whitelist · $500 cap", "whitepaper.m2": "IDO — LBP · 3–7 days", "whitepaper.m3": "liquidity — seeded at TGE", "whitepaper.m4": "community incentives — referral &amp; activation", "whitepaper.m5": "DAO reserve — governance-gated · ≤5%/yr", "whitepaper.tl_now_t": "Loop in the wild", "whitepaper.tltge_t": "Token generation event", "whitepaper.tl01_t": "Whitelist &amp; parameters final", "whitepaper.tl02_t": "Presale window", "whitepaper.tl03_t": "IDO on the LBP", "whitepaper.tl9_t": "Float completes · DAO takes the reserve", "whitepaper.tll1_t": "Germ, later", "whitepaper.src": "Sources", "whitepaper.src6": "eneatlnc-cell, Havix repository — parallel-identity network: 8 modules, 1,174 tests (M10 audit baseline), 15 audit findings closed.", "whitepaper.src1": "eneatlnc-cell, Engine 3.0 — public audit edition of the E2EE protocol stack (core-crypto, core-protocol, core-ipc; AGPL-3.0).", "whitepaper.src2": "Engine, SparkEconomy engineering record (internal) — 1 KB = 10 SPARK (minimum 10 per message), 1,000 daily fuel subsidy per calendar day, signed-transaction SPARK wallet (v3.37+), wallet top-up, spark-ledger service plan.", "whitepaper.src3": "eneatlnc-cell, Engine 3.0 — core-ipc: the Engine↔Vault signing contract behind the offline keystore (no network permission, biometric signing, QR migration).", "whitepaper.src4": "eneatlnc-cell, Aether repository — SBT-governed DAO kernel: AetherRing, Governance, Election, Safe treasury.", "whitepaper.src5": "Aether, docs/TECHNICAL_WHITEPAPER.md — three chambers, 7-stage lifecycle, elder veto, chamber/citizen balance.", "whitepaper.src7": "Havix, NEXT-STEPS.md — L0/L1/L2 three-layer stack, M11 charter store and red-line interceptor plan.", "whitepaper.foot_copy": "© <span class=\"yr\">2026</span> SparkLoop · Whitepaper v1.0 draft", "whitepaper.foot_cta": "Join the presale whitelist", "whitepaper.tr_presale_amt": "100T", "whitepaper.tr_presale_t": "Presale — whitelist", "whitepaper.tr_tge_amt": "25T", "whitepaper.tr_tge_t": "└ TGE unlock", "whitepaper.tr_tge_un": "Liquid at TGE", "whitepaper.tr_9m_amt": "75T", "whitepaper.tr_9m_t": "└ 9-month vest", "whitepaper.tr_9m_un": "Linear, months 1–9", "whitepaper.tr_a_un": "25% at TGE ◇, then 9-month linear ◇", "whitepaper.tr_b_un": "25% at TGE ◇, then 9-month linear ◇", "whitepaper.tr_ido_amt": "200T", "whitepaper.tr_ido_t": "IDO — public LBP round", "whitepaper.tr_tge2_amt": "50T", "whitepaper.tr_tge2_t": "└ TGE unlock", "whitepaper.tr_9m2_amt": "150T", "whitepaper.tr_9m2_t": "└ 9-month vest", "whitepaper.tr_dex_amt": "100T", "whitepaper.tr_dex_t": "DEX liquidity", "whitepaper.tr_dex_un": "Seeded into the pool at TGE · LP locked 12 months ◇", "whitepaper.tr_dao_amt": "500T", "whitepaper.tr_dao_t": "DAO reserve", "whitepaper.tr_dao_un": "No calendar — released only by Aether proposal · charter cap ≤5%/yr", "whitepaper.tr_comm_amt": "100T", "whitepaper.tr_comm_t": "Community incentives", "whitepaper.tr_comm_un": "Referral bonuses + activation grants · settles per program", "whitepaper.tr_fuel_amt": "150T", "whitepaper.tr_fuel_t": "└ Engine fuel subsidies", "whitepaper.tr_fuel_un": "Charter default ◇ — subsidy epochs", "whitepaper.tr_relay_amt": "100T", "whitepaper.tr_relay_t": "└ Relay &amp; infrastructure", "whitepaper.tr_relay_un": "Charter default ◇ — relays, s-nodes", "whitepaper.tr_eco_amt": "150T", "whitepaper.tr_eco_t": "└ Ecosystem grants", "whitepaper.tr_eco_un": "Charter default ◇ — apps, relays, tooling", "whitepaper.tr_ai_amt": "100T", "whitepaper.tr_ai_t": "└ AI liquidity &amp; endowment", "whitepaper.tr_ai_un": "Charter default ◇ — AI bounds", "whitepaper.ch4b_p1": "The core of the launch is <b>presale + IDO in parallel, at different tempos</b>: the presale targets the core community; the IDO faces the public. <mark class=\"key\">The presale builds the base; the IDO opens the market.</mark>", "whitepaper.ch4b_li1": "<b>Audience:</b> early core contributors and active community members only. Wallet addresses are collected into a whitelist in advance; start time is announced to the list first.", "whitepaper.ch4b_li2": "<b>Anti-whale:</b> a hard <mark class=\"key\">$500 per-wallet cap</mark>.", "whitepaper.ch4b_li3": "<b>Terms:</b> pay with USDT or BNB at a fixed low price; 25% unlocks at TGE, the remainder vests linearly over 9 months ◇.", "whitepaper.ch4b_li4": "<b>Execution:</b> when the window opens, whitelisted wallets connect on the official site and subscribe inside the cap.", "whitepaper.ch4b2_li1": "<b>Platform:</b> an LBP launchpad of the Fjord Foundry class — the price starts high and decays until demand catches it, which <mark class=\"key\">removes the sniping edge</mark>; no whitelist, no first-block advantage.", "whitepaper.ch4b2_li2": "<b>Parameters:</b> token address triple-checked before funding the pool (irreversible); payment in USDT or BNB; a 3–7 day window; per-wallet minimum and maximum caps; starting price above the presale price.", "whitepaper.ch4b2_li3": "<b>Distribution:</b> 25% of each wallet's allocation is claimable at TGE, the remainder vests linearly over 9 months ◇; proceeds flow directly to the project multisig.", "whitepaper.ch4b2_li4": "<b>Accounting:</b> after the window closes, the subscription list and amounts are reconciled and published before distribution.", "whitepaper.ch4b3_note": "Addresses are published on the Spark page at the moment of deployment. Before that moment, any address claiming to be SPARK is fraudulent.", "whitepaper.ch4b3_p1": "At TGE the liquidity tranche seeds the DEX pool, paired against BNB. SPARK is recommended to be issued as a BEP-20 token on BNB Chain ◇ — matching the USDT/BNB payment rails of both rounds — with the Aether treasury and governance deployed on the same BNB Smart Chain<sup><a href=\"#cite-4\">[4]</a></sup>, so reserve operations settle natively with no cross-chain bridge<sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch4b4_p1": "The structural promise is a <mark class=\"key\">hard float ceiling</mark>: the calendar can never unlock more than 40% (presale + IDO + LP); the 10% incentive tranche pays out only against verified referrals and activations; and the 50% reserve moves only through a public, vetoable proposal, with the charter capping releases at <b>≤5% of the reserve per year</b>. Early buyers know exactly what the maximum float is.", "whitepaper.ch5_p1": "The 50% reserve is not a treasury wallet — it is a <b>constitutional object</b>. Custody sits in a 3/5 Safe multisig; every movement requires a proposal through Aether's 7-stage lifecycle, survives the elder veto window, and executes through the timelock<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>. Weight in that process is soulbound and earned — 14 AetherRing ranks that cannot be bought or transferred<sup><a href=\"#cite-4\">[4]</a></sup>.", "whitepaper.ch5_p2": "Reserve uses are bounded by charter: user-subsidy epochs for Engine fuel, relay and infrastructure funding, ecosystem grants, and — once Germ exists — liquidity management by chartered AI inside hard limits, with red lines routing back to human votes<sup><a href=\"#cite-6\">[6]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>. The charter also fixes a <mark class=\"key\">release-rate ceiling of ≤5% of the reserve per year</mark> — a computable promise, not a discretionary one: even a fully captured treasury cannot drain the reserve faster than one-twentieth per year. The balance design is deliberate: <mark class=\"key\">chambers and citizens each hold roughly half the voting weight</mark>, so neither the institution nor the crowd can spend the reserve alone<sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch7_disc": "<b>Disclaimer.</b> This whitepaper describes an open-source software project and its fuel asset. It is not investment advice, not an offer to sell securities, and not a promise of returns. Parameters marked ◇ are draft defaults subject to change before launch. There is no trust-me marketing in this loop: read the repositories.", "whitepaper.ch7_li1": "<b>Execution risk:</b> Aether mainnet deployment, the M11 charter store, and the spark-ledger service are unfinished components the TGE sequence depends on<sup><a href=\"#cite-2\">[2]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch7_li2": "<b>Cross-chain risk:</b> mitigated by design — SPARK and the Aether governance/treasury deploy on the same BNB Smart Chain ◇, so reserve operations settle natively without any bridge dependency.", "whitepaper.ch7_li3": "<b>Market risk:</b> an LBP discovers price honestly — which means it can discover it downward. Fixed low presale pricing compensates early trust but does not guarantee returns.", "whitepaper.ch7_li4": "<b>Regulatory risk:</b> token launches face divergent regulation; restrictions may apply by jurisdiction; counsel review is a precondition, not a formality.", "whitepaper.ch7_li5": "<b>Smart-contract risk:</b> audits reduce but never eliminate risk; only interact with addresses published on the official site.", "whitepaper.fig2_sub": "Liquid float: 17.5% at TGE (2.5% presale + 5% IDO + 10% LP), rising by 2.5% per month as both tranches vest and reaching its 40% calendar ceiling at month 9. The 10% incentive tranche settles per program; the remaining 50% moves only by governance, charter-capped at ≤5%/yr.", "whitepaper.tl_now_d": "Engine v3.64.7 and Vault v3.70.0 shipped — Binder IPC direct channel and the signed-transaction SPARK wallet live, releases hardened with R8 obfuscation on both apps, and the daily fuel subsidy deduplicated by an unlinkable device-day hash at the relay; Havix in closed beta after a 15-finding audit closure; Aether v3.6 on BSC (audit remediation closed), awaiting mainnet deployment<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>. Presale whitelist open.", "whitepaper.tl01_d": "Wallet addresses collected; presale price, IDO bounds, vesting and LP-lock parameters confirmed; contracts audited and addresses published.", "whitepaper.tl02_d": "Whitelisted wallets subscribe with USDT/BNB inside the $500 cap at the fixed low price.", "whitepaper.tl03_d": "3–7 day public round; price discovers itself; reconciliation published at close.", "whitepaper.tl9_d": "Presale and IDO vesting complete — the calendar float reaches its 40% ceiling; Aether mainnet governance assumes the reserve mandate in full, releases capped by charter at ≤5%/yr.", "whitepaper.tltge_d": "Presale 25% + IDO 25% initial distribution land in wallets; the 10% liquidity tranche seeds the DEX pool; spark-ledger goes live for Engine settlement<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.tll1_d": "Node-level AI joins the network under the charter — the Brain arrives to tend a loop that already beats<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch4b5_li1": "<b>Security:</b> token, presale and LBP contracts must carry audits from a recognized firm before any funds are accepted; reports are published alongside the addresses.", "whitepaper.ch4b5_li2": "<b>Transparency:</b> presale and IDO contract addresses and rules are announced before each window opens; the subscription reconciliation is published before TGE distribution.", "whitepaper.ch4b5_li3": "<b>Anti-bot:</b> LBP price decay defeats sniping; per-wallet caps ($500 presale; min/max IDO) cap concentration; dynamic slippage bounds may be applied on the presale contract ◇.", "whitepaper.ch4b5_li4": "<b>Legal:</b> the launch is being reviewed by counsel for the jurisdictions involved; participation may be restricted where required. Nothing here is an offer of securities."},
  zh: {"vault.nav_home": "首页", "vault.nav_rewards": "奖励", "vault.chip": "离线 · 物理隔离 · 主权", "vault.h1_a": "一款保险箱，它", "vault.h1_grad": "绝不与网络对话", "vault.hero_desc": "<strong>Vault</strong> 是面向 Engine 类应用的通用离线保险箱。它以 <strong>零联网权限</strong> 存储私钥与登录签名，将它们封存在手机的安全芯片内，用你的指纹签名，并仅通过光线——一帧二维码——将密钥迁移到新硬件。不是“我们保证不联网”，而是 <strong>它根本无法联网</strong>。", "vault.btn_ceremony": "▶ 试试签名仪式", "vault.btn_migration": "⟳ 密钥迁移", "vault.btn_audit": "↗ 审计加密层", "vault.stat_internet": "清单中的 INTERNET 权限", "vault.stat_tee": "硬件封存的密钥", "vault.stat_wallet": "钱包托管与交接", "vault.stat_qr": "密钥唯一的出口", "vault.tag_demo": "由演示影片重制", "vault.title_demo": "把保险箱握在手中", "vault.sub_demo": "左侧是真实的 Vault 应用：SPARK 钱包视图——余额不过是签名交易之和，交接永远只隔一次底部栏的点击。中间是保险箱状态页，列出它所守护的每一个应用密钥——点击 <b>签名</b>，观看生物识别仪式。右侧是手机对其自身隔离状态的如实报告。", "vault.wallet_title": "SPARK 钱包", "vault.wallet_sub": "Vault 托管 · 签名交易链", "vault.wallet_balsub": "余额 = Σ 签名交易", "vault.wallet_handover": "⇄ 钱包交接", "vault.wallet_keys": "密钥：3 把", "vault.vs_title": "受守护的密钥", "vault.vs_fingerprint": "指纹", "vault.vs_algorithm": "算法", "vault.vs_sealed": "已封存", "vault.vs_sealed_val": "Keystore TEE · AES-256-GCM", "vault.vs_lastreq": "最近一次请求", "vault.vs_waiting": "等待中……", "vault.vs_sign": "签署 Engine 请求", "vault.vs_migrate": "⟳ 迁移到新设备", "vault.bio_touch": "触摸传感器", "vault.bio_title": "BiometricPrompt", "vault.bio_desc": "密钥从不离开 TEE——它只在安全硬件内部签名。", "vault.console_head": "adb shell — 物理隔离自检", "vault.sim_caption": "<b>以上每个事件都是本地的。</b>控制台在网络上无事可报——因为根本不存在网络。", "vault.tag_guards": "它守护什么", "vault.title_guards_a": "唯一的职责：成为", "vault.title_guards_grad": "每一个主权应用的保险箱", "vault.sub_guards": "Vault 在设计上与应用无关。任何形如 Engine 的东西——想要在线生活与离线密钥并存的应用——都可以把它的身份托付给这座保险箱。", "vault.card1_t": "应用私钥", "vault.card1_d": "由 Engine 之类的应用生成的 ECDSA P-256 身份，一到即被封存。", "vault.card2_t": "登录与钱包签名", "vault.card2_d": "挑战-响应式登录码与 SPARK 钱包交易——在保险箱内签名，绝不在线存储。每一次余额变动都是在只追加链上的一笔签名交易。", "vault.card3_t": "设备迁移绑定", "vault.card3_d": "带签名重绑记录，无需云端备份即可把你的身份迁往全新硬件。", "vault.card4_t": "指纹目录", "vault.card4_d": "每个受守护密钥的本地登记簿：指纹与封存状态，一览无余。", "vault.card5_t": "仅此而已", "vault.card5_d": "没有浏览、没有同步、没有广告、没有遥测。它是一台带屏幕的保险箱，而不是智能手机应用。", "vault.card6_t": "仅凭生物识别的解锁", "vault.card6_d": "每次解锁都通过 BiometricPrompt，并带 ±120 秒新鲜窗口——基于时钟的重放防护。", "vault.tag_ceremony": "在线应用如何离线签名", "vault.title_ceremony_a": "密钥签名。", "vault.title_ceremony_grad": "密钥从不离开。", "vault.pl1": "Engine 需要一个签名", "vault.pl2": "IPC 请求 + 质询", "vault.pl3": "BiometricPrompt", "vault.pl4": "TEE 解封并签名", "vault.pl5": "已签名回调", "vault.pl6": "Engine 验证签名 + Δt&lt;120s", "vault.co_tag": "为什么 ±120 秒窗口如此重要", "vault.co_text": "回调签名覆盖 <b>sessionId ‖ status ‖ timestamp</b>。即使回调被窃取，也无法在几分钟后重放——时钟本身就是证明的一部分。中继永远看不到密钥；Engine 永远不持有密钥；<b>只有 TEE 曾经持有。</b>", "vault.tag_migration": "新手机，相同身份", "vault.title_mig_a": "通过一束光", "vault.title_mig_grad": "搬家", "vault.sub_migration": "私钥是唯一你绝不能托付给云端的东西。当硬件更换时，Vault 会让你的身份在设备之间屏幕对屏幕地行走——下面逐步演示。", "vault.migprev": "上一步", "vault.mignext": "下一步", "vault.flag_t": "FLAG_SECURE", "vault.flag_d": "二维码屏幕让截图与录屏全黑。剩下的唯一攻击方式只有偷窥。", "vault.payload_t": "加密负载", "vault.payload_d": "绑定 URI 携带加密的会话负载——原始私钥绝不出现于任何 URI 中。", "vault.burn_t": "绑定后烧毁", "vault.burn_d": "Engine 调用 convertBoundToPublicKeyOnly()——Vault 接管的那一刻，它的私钥副本即被抹除。", "vault.title_compare": "今晚密钥睡在哪里？", "vault.th_storage": "存储模型", "vault.th_network": "网络可达性", "vault.th_extraction": "提取风险", "vault.th_migration": "迁移路径", "vault.tr_ext_t": "浏览器扩展钱包", "vault.tr_ext_reach": "始终在线", "vault.tr_ext_risk": "高——内存与磁盘均可读", "vault.tr_ext_mig": "纸上的助记词", "vault.tr_hot_t": "热服务器 / 托管", "vault.tr_hot_reach": "全天候攻击面", "vault.tr_hot_risk": "系统性——一次攻破，全部密钥泄露", "vault.tr_hot_mig": "信任运营方", "vault.tr_cloud_t": "云端密钥备份", "vault.tr_cloud_reach": "本质即同步", "vault.tr_cloud_risk": "账号失守 = 密钥失守", "vault.tr_cloud_mig": "重新下载", "vault.tr_vault_reach": "无 INTERNET 权限", "vault.tr_vault_risk": "TEE 芯片 + 生物识别门禁", "vault.tr_vault_mig": "二维码光通道，带签名重绑", "vault.co2_tag": "物理定律，而非承诺", "vault.co2_text": "表中每一行都依赖于某人行为良好。Vault 的隔离是在 Android 清单中声明的、由操作系统强制执行的——<b>数据包根本无法发出，因此无需任何承诺。</b>", "vault.foot_desc": "对 eneatlnc-cell Loop 的独立解读。E2EE 协议栈开放审计；每一项主张都可追溯到代码与白皮书。", "vault.foot_layers": "层级", "vault.foot_engine": "主权社交", "vault.foot_vault": "离线托管", "vault.foot_havix": "L0 · 平行身份", "vault.foot_spark": "燃料", "vault.foot_rewards": "推荐政策", "vault.foot_loop": "Web4 回路", "vault.foot_repos": "代码仓库", "vault.foot_bottom": "密钥离线 · SBT 治理 · $SPARK 燃料 · AI 特许", "vault.log_settle_pre": "计量批次已于 TEE 内联签 → 交易 #", "vault.log_settle_suf": " 已入链 · 余额 = Σ 签名交易", "vault.log_handover": "交接证书已签名 · 全额余额以创世交易迁移至新设备", "vault.log_bio_dismiss": "生物识别提示已关闭", "vault.log_ipc_pre": "已收到 IPC 签名请求 · challenge=0x", "vault.log_ipc_suf": " · 等待生物识别", "vault.sig_result": "✓ 已签名 · ECDSA P-256 · TEE", "vault.log_bio_ok": "生物识别 ✓ → 密钥在 TEE 内解封 → 于安全世界内完成签名 → 重新封存", "vault.log_callback": "回调验签：sig(sessionId‖status‖ts) ✓ · Δt &lt; 120s ✓", "vault.mig1_title": "新设备生成全新密钥对", "vault.mig1_desc": "新手机在 Engine 内生成自己的 ECDSA P-256 身份。任何东西都不会经空中通道导入——永远。", "vault.mig2_title": "旧 Vault 导出迁移绑定", "vault.mig2_desc": "旧 Vault 将授权封入二维码帧。FLAG_SECURE 让截图全黑；密钥本体从不离开 TEE。", "vault.mig3_title": "新 Vault 扫码——仅光学通道", "vault.mig3_desc": "ML Kit 通过相机读取帧。这里涉及其中的唯一网络就是光。", "vault.mig4_title": "身份重新绑定到新密钥", "vault.mig4_desc": "带签名的重绑回调将你的 DID 迁移到新设备的公钥。联系人会自动验证新指纹。", "vault.mig5_title": "SPARK 托管同步交接", "vault.mig5_desc": "旧 Vault 签署交接证书，以全额余额终结原链；新 Vault 验证后以创世交易承接账本——任何余额都不存在未签名的形态。", "vault.mig6_title": "旧副本烧毁，零残留", "vault.mig6_desc": "旧 Vault 以零覆写方式擦除封存密钥。迁移完成——没有任何密钥碰过互联网。", "vault.log_boot1": "AndroidManifest：uses-permission INTERNET → <b>未声明</b> ✓", "vault.log_boot2": "网络栈：不可达 · sockets：无 · 遥测：无", "vault.log_boot3": "Keystore TEE 在线 · 密钥已封存（AES-256-GCM）· 生物识别就绪", "vault.log_boot4": "SPARK 钱包链已就绪 · HWM 防重放 · 交接待命", "whitepaper.nav_home": "首页", "whitepaper.nav_rewards": "奖励", "whitepaper.kicker": "// 项目白皮书", "whitepaper.chip": "版本 1.0 · 草案", "whitepaper.h1": "SPARK <span class=\"grad\">&amp; Web4 主权回路</span>", "whitepaper.hero_desc": "四个器官——<strong>Vault</strong>、<strong>Engine</strong>、<strong>Aether</strong>、<strong>Havix</strong>——构成一个闭环，<strong>SPARK</strong> 是驱动它转动的燃料。E2EE 协议栈开放审计；本文档描述已建成的架构、所设计的代币经济，以及双轨制启动：白名单预售之后是公开的基于 LBP 的 IDO。", "whitepaper.meta_1": "2026 年 8 月", "whitepaper.meta_2": "4 个代码仓库 · AGPL + APACHE", "whitepaper.meta_3": "预售白名单已开放", "whitepaper.meta_4": "供应量 1,000T SPARK", "whitepaper.stat_dao": "DAO 储备——治理门控", "whitepaper.stat_tge": "TGE 即可流通（含 10% 流动性）", "whitepaper.stat_cap": "每个钱包的预售上限", "whitepaper.stat_kb": "每条消息每 KB 消耗的 SPARK", "whitepaper.abstract": "<b>摘要。</b>Web3 给了用户钱包，却把他们的社交生活留在了服务器上。Web4 原型回路以 <mark class=\"key\">物理隔离</mark> 弥合这一鸿沟：一个不持有任何密钥的在线社交应用（<strong>Engine</strong>）、一个持有密钥但绝不联网的离线保险箱（<strong>Vault</strong>）、一个以 SBT 治理并储存燃料储备的议会（<strong>Aether</strong>），以及一个平行身份网络（<strong>Havix</strong>）——基于主 DID 派生、运行信用与价值双重经济——在活的章程之下特许 AI。<strong>$SPARK</strong> 是唯一发行资产：计量应用内的表达、为 DAO 储备注入，并在其间流动——它是回路的燃料，绝不是投票。本文档记录公开仓库中实际的架构，然后规定代币：效用、分配（10% 预售 / 20% IDO / 10% DEX 流动性 / 50% DAO 储备 / 10% 社区激励）、两阶段启动、解锁安排，以及保障启动公平、储备主权的各项措施。", "whitepaper.toc1": "主权回路", "whitepaper.toc2": "架构：隔离与身份", "whitepaper.toc3": "四大器官", "whitepaper.toc4": "SPARK 代币经济", "whitepaper.toc4b": "双轨制启动", "whitepaper.toc5": "储备的治理", "whitepaper.toc6": "通往 TGE 的路线图", "whitepaper.toc7": "风险与免责声明", "whitepaper.ch1": "主权回路", "whitepaper.ch1_p1": "这是<b>一个项目，而非一堆产品的组合</b>。每个仓库是一个器官；器官共享同一套血液循环——SPARK。用户在 Engine 中聊天；每一条消息都在燃烧燃料；燃料储蓄于 Aether 储备；储备由 Havix 上的特许 AI 保持流动；Havix 的网络效应让 Engine 保持活力；而 Engine 的需求赋予了 SPARK 物质支撑。切断任何一个器官，回路就会停止转动。", "whitepaper.th_organ": "器官", "whitepaper.th_metaphor": "隐喻", "whitepaper.th_function": "回路中的功能", "whitepaper.th_status": "真实状态", "whitepaper.rv_mt": "保险箱", "whitepaper.rv_fn": "离线保管每一把私钥；代理签名；仅通过二维码迁移密钥", "whitepaper.rv_st": "v3.70.0 已发布", "whitepaper.re_mt": "应用", "whitepaper.re_fn": "主权社交即时通讯；纯内存、端到端加密；按 KB 消耗 SPARK", "whitepaper.re_st": "v3.64.7 已发布", "whitepaper.rs_mt": "燃料", "whitepaper.rs_fn": "计量表达；为储备注入；连接储备与市场", "whitepaper.rs_st": "预售 + IDO", "whitepaper.ra_mt": "议会", "whitepaper.ra_fn": "SBT 治理的 DAO：三个议院、灵魂绑定等级、多重签名金库", "whitepaper.ra_st": "v3.6 · BSC · 审计关闭 · 主网待定", "whitepaper.rh_mt": "身份根", "whitepaper.rh_fn": "主 DID 派生的平行身份：4 上下文派生、信用与价值双轨、AI 章程层面", "whitepaper.rh_st": "M10 封闭测试版", "whitepaper.rig_mt": "大脑", "whitepaper.rig_fn": "以自身身份进行推理的节点级 AI", "whitepaper.rig_st": "未来阶段", "whitepaper.ch1_meta": "这些隐喻就是架构本身：<mark class=\"key\">保险箱从不碰触网络</mark>、<mark class=\"key\">议会以灵魂绑定的 SBT 治理</mark>、<mark class=\"key\">大脑是被特许而非被信任</mark>。下文所述一切都可追溯到公开代码<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>。", "whitepaper.ch2": "架构：隔离与身份", "whitepaper.h21": "以物理隔离作为安全模型", "whitepaper.ch2_p1": "回路最根本的安全决策是<b>以物理而非政策来分离</b>。Engine 在线运行却不持有任何私钥；Vault 持有密钥，并且在构建时<b>完全没有任何网络权限</b>——它的 Android 清单不声明任何 INTERNET 权限，使得数据外泄成为物理问题而非逻辑问题<sup><a href=\"#cite-3\">[3]</a></sup>。签名请求经由受签名保护的系统间通信（IPC）从 Engine 传输到 Vault；密钥材料只以加密的二维码帧在设备间传输——相机对相机、物理隔离强制<sup><a href=\"#cite-3\">[3]</a></sup>。", "whitepaper.ch2_p2": "信任是可审计的：Engine 的 <span class=\"mono\">core/</span> 模块（协议、加密、IPC）与 Vault 的<b>逐字节相同</b>，因此两个应用都对照同一份公开源码校验<sup><a href=\"#cite-1\">[1]</a></sup>。消息通过 ECDH 密钥协商与 AES-256-GCM 进行端到端加密；中继看到的是信封，绝非明文<sup><a href=\"#cite-1\">[1]</a></sup>。", "whitepaper.h22": "一个身份，四个不可关联的上下文", "whitepaper.ch2_p3": "Havix 使用 HKDF 从单个主密钥派生四个特定上下文的子身份——公开、市场、隧道与百科上下文<sup><a href=\"#cite-6\">[6]</a></sup>。该派生在密码学上不可关联：你的市场身份无法与你的私人通信产生关联。这正是让一个人可以同时是 <mark class=\"key\">议会中的公民、市场上的交易者，以及聊天中的私人个体</mark>——无需三个账号，也无需平台掌握映射表。", "whitepaper.h23": "三个层面，一条回路", "whitepaper.ch2_li1": "<b>应用层（在线）：</b>Engine——面向用户、无密钥、纯内存。消息只存在于 RAM 中；被查封的攻击面几乎为零。", "whitepaper.ch2_li2": "<b>托管层（离线）：</b>Vault——密钥库封存于生物识别之后，只能通过二维码导出。", "whitepaper.ch2_li3": "<b>协调层（链下 P2P）：</b>Havix——身份派生、声誉/信用账本、仲裁，以及特许 AI 的章程<sup><a href=\"#cite-6\">[6]</a></sup>。", "whitepaper.ch2_li4": "<b>结算层（链上）：</b>BNB 智能链上的 Aether——治理、金库与时锁执行，由灵魂绑定的 SBT 等级而非可转让的代币供应来治理<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>。", "whitepaper.ch2_p4": "Havix 自己的路线图将之形式化为三层栈——网络基岩（L0）、认知执行（L1，Germ）、链上治理（L2，Aether）——以 4 上下文 DID 强制各层之间的密码学分离<sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.ch3": "四大器官", "whitepaper.h31": "Vault——保险箱", "whitepaper.note31": "v3.70.0 · 已发布", "whitepaper.ch3_p1": "一个通用的离线密钥库，而非 Engine 的附属品：它可以为任何合规应用保管密钥。机制：无网络权限；密钥库封存于 TEE；生物识别门控签名（可用时由 StrongBox 支撑）；SPARK 钱包托管——余额以安全世界内共同签名的只追加交易链形式存在，钱包交接将全额余额作为创世交易迁移到新设备；只能通过二维码迁移到新硬件，私钥绝不进入网络栈<sup><a href=\"#cite-3\">[3]</a></sup>。自 v3.40 起，Engine 通过受签名保护的 Binder IPC 直连通道访问 Vault——旧的跨应用跳转对话框已移除<sup><a href=\"#cite-3\">[3]</a></sup>。", "whitepaper.ch3_p2": "整个回路的市场切入点：一个采用纯内存架构、具备群组消息、60 种表情表达经济与 DID 档案的主权社交即时通讯<sup><a href=\"#cite-1\">[1]</a></sup>。其经济引擎已在仓库中明确规定：<mark class=\"key\">每 1 KB 消耗 10 SPARK</mark>——每条消息按其 UTF-8 大小计量并向上取整，每条消息至少 10 SPARK；每日燃料补贴 1,000 SPARK（按自然日幂等，由权威账本裁定，须通过绑定的 Vault 身份门槛）；重度用户从钱包充值<sup><a href=\"#cite-2\">[2]</a></sup>。钱包余额并非存储的数字：它是由 Vault 持有的钱包密钥共同签名的只追加交易链派生的——每一次余额变动，无一例外，都是一笔签名交易<sup><a href=\"#cite-2\">[2]</a></sup>。客户端预扣已实现；独立的 spark-ledger 服务在服务端结算余额<sup><a href=\"#cite-2\">[2]</a></sup>。", "whitepaper.h33": "Aether——议会", "whitepaper.note33": "v3.6 · BSC · 审计关闭 · 主网待定", "whitepaper.ch3_p3": "一个在 BNB 智能链上由 SBT 治理的 DAO 内核。权重是挣来的而非买来的：AetherRing 铸造 14 个不可转让的灵魂绑定等级；三个议院（议事会、议会、长老会）加上公民公投，通过一个带长老否决权的 7 阶段提案生命周期相互制衡；金库是执行时锁调用的 3/5 Safe 多重签名<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>。设计上刻意的张力：<mark class=\"key\">治理是灵魂绑定的（SBT），而燃料是真实发行的资产</mark>——大户可以购买 $SPARK，但 $SPARK 购买的是消息，不是选票。有一个合约与众不同：AetherDonation 是一个<b>外部慈善通道</b>（为公共产品提供 USDC 打赏），与回路的经济无关。", "whitepaper.h34": "Havix——身份根", "whitepaper.note34": "已验证 · 待命", "whitepaper.ch3_p4": "回路底层的协调网络：八个模块（身份、消息类型、信用、担保、百科、仲裁、市场、s-node 运行时），1,174 个通过的测试（MVP 980 + 验证实验 194，M10 审计基线），以及两轮审计项目——M9 关闭了全部 15 项发现，而 M10 深度审计又浮现 52 项（5 个 P0 + 15 个 P1 + 32 个 P2），P0/P1 在封闭测试前已修复<sup><a href=\"#cite-6\">[6]</a></sup>。它的章程层面正是把 AI 置于法律而非魔法的立足点上：常规操作自动执行并附带凭证；<mark class=\"key\">红线操作被物理地路由到由人进行的链上投票</mark>。章程存储与拦截器已排入 M11 工作流<sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.h35": "Germ——大脑，稍后", "whitepaper.ch3_p5": "Germ 是节点级 AI 层：在 Havix 网络上以自身 4 上下文身份进行推理的 AI。它被有意地延后——<mark class=\"key\">Engine 才是今天的市场入口</mark>；当回路有了值得呵护的用户时，大脑才会到来。本白皮书中，Germ 只在经济必须为其预留空间之处出现（储备 AI，§5）。", "whitepaper.ch4": "SPARK 代币经济", "whitepaper.h41": "效用：有物理支撑的燃料", "whitepaper.ch4_p1": "SPARK 是一种<b>计量资产</b>。在 Engine 中，每 1 KB 消耗 10 SPARK——按消息大小计量、向上取整、每条至少 10——计费表在协议中，而不是在服务条款里<sup><a href=\"#cite-2\">[2]</a></sup>。预算源自真实的 100&nbsp;Mbps 中继基线：文本信封最多 40&nbsp;KB，媒体最多 48&nbsp;KB，128&nbsp;KB 的硬上限帧，群组上限 200 人<sup><a href=\"#cite-1\">[1]</a></sup>。因为每一个表达字节都要消耗燃料，垃圾信息有了边际成本，而发言依然免费。", "whitepaper.ch4_li1": "<b>获取：</b>每日燃料补贴（每个自然日 1,000 SPARK，幂等，须通过绑定的 Vault 身份门槛<sup><a href=\"#cite-2\">[2]</a></sup>）、钱包充值<sup><a href=\"#cite-2\">[2]</a></sup>，或在 TGE 后从市场购买。", "whitepaper.ch4_li2": "<b>消耗：</b>消息燃料；群组与媒体预算；SDK 应用的使用。", "whitepaper.ch4_li3": "<b>持有：</b>DAO 金库以 SPARK 作为其长期储备——真实使用所带来的需求对称地累积到每一位持有者。", "whitepaper.ch4_note": "◇ 设计参数（归属期长度、流动性锁定、费用路由、补贴衰减）是本草案的建议默认值；每一项都会在预售开始前由治理确认或修订。链上计量费率（1 KB = 10 SPARK，每条至少 10；每个自然日 1,000 燃料补贴）在 Engine 规范中已固定<sup><a href=\"#cite-2\">[2]</a></sup>。", "whitepaper.h42": "同一资产的两种阶段——计量账本，然后是固定供应", "whitepaper.ch4_p2": "SPARK 以两个刻意的阶段发布，而顺序本身就是设计。<b>阶段 A——计量账本（现已运行）：</b>在已发布的 Engine 软件内部，SPARK 以一种链下哈希连接的账本存在。每台设备通过 Vault 联签的燃料补贴每天铸造 <b>1,000</b>——反女巫防御已投入生产：TEE/DRM 设备锚、中继侧对不可关联设备哈希的每日去重，以及在签名门槛强制执行的金额白名单。阶段 A 的余额<mark class=\"key\">不可转让、不可交易、不可兑换</mark>——它们今天是配额，而非证券。", "whitepaper.ch4_p3": "<b>阶段 B——TGE 映射（计划中）：</b>固定的 <b>1,000T 供应量</b>在 TGE 生效。初始供应将 §4.3 的预售、IDO、流动性、储备各份额与基于快照的阶段 A 余额映射（纳入社区激励份额）相结合——具体转换参数是草案默认值 ◇，在预售开始前由治理确认。TGE 之后，SPARK 自由流通，<b>包括开放的 USDC 及其他稳定币交易对</b>。转换通道目前刻意不构建：设备锚定、每日去重与金额白名单必须<i>先于</i>待守护的金库存在，这样当可兑换性到来那天，这些防御从配额卫生升级为金库大门。", "whitepaper.h43": "供应与分配", "whitepaper.ch4_p4": "总供应量固定为 <b>1,000T SPARK（1,000,000,000,000,000——一千兆）</b>。分配遵循 10 / 20 / 10 / 50 / 10 拆分：预售、IDO、DEX 流动性、DAO 储备、社区激励。这里<mark class=\"key\">没有团队份额、没有内部人员分配、没有营销份额</mark>——团队的上涨空间在于它与 DAO 共享的 50% 储备，只能通过公开治理解锁，并以每年 ≤5% 的储备上限由章程约束。", "whitepaper.fig1": "图 1 — TGE 时的 SPARK 分配（已细化：10 个切片，5 个份额）", "whitepaper.fig1_sub": "总供应量 1,000T（1,000,000,000,000,000）。预售在 TGE 拆分 2.5% + 7.5% 归属；IDO 拆分 5% 于 TGE + 15% 归属（两个份额均为：TGE 时 25%，随后 9 个月线性）；储备子拆分是受章程约束的草案默认值 ◇，释放上限 ≤5%/年——储备本身没有日历解锁。", "whitepaper.th_tranche": "份额", "whitepaper.th_share": "占比", "whitepaper.th_amount": "数量", "whitepaper.th_unlock": "解锁安排", "vault.foot_home": "首页", "whitepaper.ch4b": "双轨启动", "whitepaper.h44": "阶段 1——预售（10%）", "whitepaper.h45": "阶段 2——IDO（20%）", "whitepaper.h46": "流动性与 DEX（10%）", "whitepaper.h47": "解锁安排", "whitepaper.h48": "保障与合规", "whitepaper.h32": "Engine——应用", "whitepaper.note32": "v3.64.7 · 已发布", "whitepaper.ch5": "储备治理", "whitepaper.ch6": "通往 TGE 的路线图", "whitepaper.ch7": "风险与免责声明", "whitepaper.fig2": "图 2 — TGE 后的流通供应", "whitepaper.m1": "预售——白名单 · 每人 $500 上限", "whitepaper.m2": "IDO——LBP · 3–7 天", "whitepaper.m3": "流动性——在 TGE 注入", "whitepaper.m4": "社区激励——推荐与激活", "whitepaper.m5": "DAO 储备——由治理闸控 · ≤5%/年", "whitepaper.tl_now_t": "回路投入实际使用", "whitepaper.tltge_t": "代币生成事件", "whitepaper.tl01_t": "白名单与参数敲定", "whitepaper.tl02_t": "预售窗口期", "whitepaper.tl03_t": "在 LBP 上进行的 IDO", "whitepaper.tl9_t": "流通量达到上限 · DAO 接管储备", "whitepaper.tll1_t": "Germ，稍后", "whitepaper.src": "资料来源", "whitepaper.src6": "eneatlnc-cell，Havix 仓库——平行身份网络：8 个模块，1,174 项测试（M10 审计基线），15 项审计发现已关闭。", "whitepaper.src1": "eneatlnc-cell，Engine 3.0——E2EE 协议栈的公开审计版（core-crypto、core-protocol、core-ipc；AGPL-3.0）。", "whitepaper.src2": "Engine，SparkEconomy 工程记录（内部）——1 KB = 10 SPARK（每条至少 10）、每个自然日 1,000 的每日燃料补贴、签名交易 SPARK 钱包（v3.37+）、钱包充值、spark-ledger 服务计划。", "whitepaper.src3": "eneatlnc-cell，Engine 3.0——core-ipc：离线密钥库背后的 Engine↔Vault 签名契约（无网络权限、生物识别签名、二维码迁移）。", "whitepaper.src4": "eneatlnc-cell，Aether 仓库——SBT 治理的 DAO 内核：AetherRing、Governance、Election、Safe 金库。", "whitepaper.src5": "Aether，docs/TECHNICAL_WHITEPAPER.md——三个议院、7 阶段生命周期、长老否决、议院/公民权重的平衡。", "whitepaper.src7": "Havix，NEXT-STEPS.md——L0/L1/L2 三层栈、M11 章程存储与红线拦截器计划。", "whitepaper.foot_copy": "© <span class=\"yr\">2026</span> SparkLoop · 白皮书 v1.0 草案", "whitepaper.foot_cta": "加入预售白名单", "whitepaper.tr_presale_amt": "100T", "whitepaper.tr_presale_t": "预售——白名单", "whitepaper.tr_tge_amt": "25T", "whitepaper.tr_tge_t": "└ TGE 解锁", "whitepaper.tr_tge_un": "TGE 时流通", "whitepaper.tr_9m_amt": "75T", "whitepaper.tr_9m_t": "└ 9 个月归属", "whitepaper.tr_9m_un": "线性，第 1–9 个月", "whitepaper.tr_a_un": "TGE 时 25% ◇，随后 9 个月线性 ◇", "whitepaper.tr_b_un": "TGE 时 25% ◇，随后 9 个月线性 ◇", "whitepaper.tr_ido_amt": "200T", "whitepaper.tr_ido_t": "IDO——公开 LBP 轮次", "whitepaper.tr_tge2_amt": "50T", "whitepaper.tr_tge2_t": "└ TGE 解锁", "whitepaper.tr_9m2_amt": "150T", "whitepaper.tr_9m2_t": "└ 9 个月归属", "whitepaper.tr_dex_amt": "100T", "whitepaper.tr_dex_t": "DEX 流动性", "whitepaper.tr_dex_un": "在 TGE 注入资金池 · LP 锁定 12 个月 ◇", "whitepaper.tr_dao_amt": "500T", "whitepaper.tr_dao_t": "DAO 储备", "whitepaper.tr_dao_un": "无日历解锁——仅由 Aether 提案释放 · 章程上限 ≤5%/年", "whitepaper.tr_comm_amt": "100T", "whitepaper.tr_comm_t": "社区激励", "whitepaper.tr_comm_un": "推荐奖励 + 激活奖金 · 按项目结算", "whitepaper.tr_fuel_amt": "150T", "whitepaper.tr_fuel_t": "└ Engine 燃料补贴", "whitepaper.tr_fuel_un": "章程默认 ◇——补贴周期", "whitepaper.tr_relay_amt": "100T", "whitepaper.tr_relay_t": "└ 中继与基础设施", "whitepaper.tr_relay_un": "章程默认 ◇——中继、s-node", "whitepaper.tr_eco_amt": "150T", "whitepaper.tr_eco_t": "└ 生态系统资助", "whitepaper.tr_eco_un": "章程默认 ◇——应用、中继、工具", "whitepaper.tr_ai_amt": "100T", "whitepaper.tr_ai_t": "└ AI 流动性与捐赠基金", "whitepaper.tr_ai_un": "章程默认 ◇——AI 界限", "whitepaper.ch4b_p1": "启动的核心是<b>预售与 IDO 并行、节奏不同</b>：预售面向核心社区；IDO 面向公众。<mark class=\"key\">预售建立基本盘；IDO 打开市场。</mark>", "whitepaper.ch4b_li1": "<b>受众：</b>仅限早期核心贡献者与活跃社区成员。钱包地址提前收集为白名单；开始时间最先通知名单。", "whitepaper.ch4b_li2": "<b>反大额：</b>硬性的 <mark class=\"key\">每人 $500 上限</mark>。", "whitepaper.ch4b_li3": "<b>条款：</b>以固定的低价用 USDT 或 BNB 支付；25% 在 TGE 解锁，其余在 9 个月内线性归属 ◇。", "whitepaper.ch4b_li4": "<b>执行：</b>窗口开启时，白名单钱包在官网连接并在上限内认购。", "whitepaper.ch4b2_li1": "<b>平台：</b>Fjord Foundry 级别的 LBP 发射台——价格从高位起并随需求追赶而衰减，这<mark class=\"key\">消除了狙击优势</mark>；无白名单、无首发区块优势。", "whitepaper.ch4b2_li2": "<b>参数：</b>注入资金池前三重核验代币地址（不可逆）；以 USDT 或 BNB 支付；3–7 天的窗口期；每个钱包的最低与最高上限；起始价高于预售价。", "whitepaper.ch4b2_li3": "<b>分配：</b>每钱包配额的 25% 在 TGE 可申领，其余在 9 个月内线性归属 ◇；所得直接流入项目多重签名。", "whitepaper.ch4b2_li4": "<b>对账：</b>窗口关闭后，认购名单与金额先与账目核对并公布，然后再行分配。", "whitepaper.ch4b3_note": "地址在部署的瞬间于 Spark 页面公布。在此之前，任何自称 SPARK 的地址均为欺诈。", "whitepaper.ch4b3_p1": "在 TGE，流动性份额注入 DEX 资金池，与 BNB 配对。SPARK 建议作为 BNB 链上的 BEP-20 代币发行 ◇——与两轮的 USDT/BNB 支付轨道一致——同时 Aether 金库与治理部署在同一条 BNB 智能链上<sup><a href=\"#cite-4\">[4]</a></sup>，因此储备操作无需跨链桥即可原生结算<sup><a href=\"#cite-5\">[5]</a></sup>。", "whitepaper.ch4b4_p1": "结构性承诺是<mark class=\"key\">硬性的流通上限</mark>：日历解锁永远不会超过 40%（预售 + IDO + LP）；10% 的激励份额只针对已验证的推荐与激活发放；50% 的储备只能通过公开、可否决的提案流动，章程将释放上限设为<b>每年储备的 ≤5%</b>。早期买家清楚知道最大流通量是多少。", "whitepaper.ch5_p1": "50% 的储备不是一个金库钱包——它是一个<b>宪法性对象</b>。托管置于 3/5 的 Safe 多重签名中；每一次流动都需要经过 Aether 的 7 阶段生命周期的提案、挺过长老否决窗口，并经时锁执行<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>。这一过程中的权重是灵魂绑定且靠挣得的——14 个既不能购买也不能转让的 AetherRing 等级<sup><a href=\"#cite-4\">[4]</a></sup>。", "whitepaper.ch5_p2": "储备用途由章程界定：面向 Engine 燃料的用户补贴周期、中继与基础设施资金、生态系统资助，以及——一旦 Germ 存在——由特许 AI 在硬性限制内进行流动性管理并设置红线回溯至人类投票<sup><a href=\"#cite-6\">[6]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>。章程还确立了<mark class=\"key\">每年储备 ≤5% 的释放率上限</mark>——这是可计算的承诺，而非酌情决定：即使金库被完全掌控，也无法以超过每年二十分之一的速度耗尽储备。平衡设计是刻意的：<mark class=\"key\">议院与公民各持约一半的投票权重</mark>，因此机构与人群都无法单独动用储备<sup><a href=\"#cite-5\">[5]</a></sup>。", "whitepaper.ch7_disc": "<b>免责声明。</b>本白皮书描述一个开源软件项目及其燃料资产。它不是投资建议、不是出售证券的要约、也不是回报承诺。标注 ◇ 的参数是草案默认值，可能在发布前变更。这条回路里没有「相信我」式营销：请阅读仓库。", "whitepaper.ch7_li1": "<b>执行风险：</b>Aether 主网部署、M11 章程存储与 spark-ledger 服务是 TGE 流程所依赖的未完成组件<sup><a href=\"#cite-2\">[2]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.ch7_li2": "<b>跨链风险：</b>已在设计上缓解——SPARK 与 Aether 治理/金库部署在同一条 BNB 智能链 ◇，因此储备操作无需任何桥依赖即可原生结算。", "whitepaper.ch7_li3": "<b>市场风险：</b>LBP 诚实地发现价格——这意味着它也可能向下发现价格。固定的低价预售定价补偿了早期信任，但并不保证回报。", "whitepaper.ch7_li4": "<b>监管风险：</b>代币发行面临不尽相同的监管；不同司法辖区可能施加限制；法律顾问审查是一项前置条件，而非走形式。", "whitepaper.ch7_li5": "<b>智能合约风险：</b>审计能降低但永远无法消除风险；只与官网公布地址进行交互。", "whitepaper.fig2_sub": "流通量：TGE 时为 17.5%（2.5% 预售 + 5% IDO + 10% LP），随两个份额归属每月上升 2.5%，并在此后第 9 个月达到其 40% 的日历上限。10% 的激励份额按项目结算；其余 50% 仅通过治理流动，章程上限为 ≤5%/年。", "whitepaper.tl_now_d": "Engine v3.64.7 与 Vault v3.70.0 已交付——Binder IPC 直连通道与签名交易 SPARK 钱包上线，两个应用均已用 R8 混淆加固，每日燃料补贴在中继处以不可关联的设备-日哈希去重；Havix 在关闭 15 项审计发现后进入封闭测试；BSC 上的 Aether v3.6（审计修复已关闭）正待主网部署<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>。预售白名单已开放。", "whitepaper.tl01_d": "钱包地址已收集；预售价格、IDO 边界、归属与 LP 锁定参数已确认；合约已审计且地址已公布。", "whitepaper.tl02_d": "白名单钱包以固定的低价、在 $500 上限内用 USDT/BNB 认购。", "whitepaper.tl03_d": "3–7 天的公开轮次；价格自行发现；收盘时公布对账结果。", "whitepaper.tl9_d": "预售与 IDO 归属完成——日历流通量达到其 40% 上限；Aether 主网治理全面接管储备职权，释放以章程上限 ≤5%/年约束。", "whitepaper.tltge_d": "预售 25% + IDO 25% 的初始分配进入钱包；10% 的流动性份额注入 DEX 资金池；spark-ledger 上线用于 Engine 结算<sup><a href=\"#cite-2\">[2]</a></sup>。", "whitepaper.tll1_d": "节点级 AI 在章程下加入网络——大脑到来，照料一条已然跳动的回路<sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.ch4b5_li1": "<b>安全：</b>代币、预售与 LBP 合约在接收任何资金前必须通过公认机构的审计；报告与地址一同公布。", "whitepaper.ch4b5_li2": "<b>透明：</b>预售与 IDO 的合约地址和规则在每段窗口开启前公布；认购对账结果在 TGE 分配前发布。", "whitepaper.ch4b5_li3": "<b>反机器人：</b>LBP 的价格衰减击败狙击；每钱包上限（预售 $500；IDO 最小/最大）限制集中度；预售合约上可能应用动态滑点边界 ◇。", "whitepaper.ch4b5_li4": "<b>法律：</b>本次启动正由法律顾问就相关司法辖区进行审核；必要时参与可能受限。此处任何内容都不是证券要约。"},
  zht: {"vault.nav_home": "首頁", "vault.nav_rewards": "獎勵", "vault.chip": "離線 · 物理隔離 · 主權", "vault.h1_a": "一款保險箱，它", "vault.h1_grad": "絕不與網路對話", "vault.hero_desc": "<strong>Vault</strong> 是面向 Engine 類應用的通用離線保險箱。它以 <strong>零聯網權限</strong> 儲存私鑰與登入簽名，將它們封存在手機的安全晶片內，用你的指紋簽名，並僅透過光線——一幀 QR Code——將金鑰遷移到新硬體。不是「我們保證不連網」，而是 <strong>它根本無法連網</strong>。", "vault.btn_ceremony": "▶ 試試簽名儀式", "vault.btn_migration": "⟳ 金鑰遷移", "vault.btn_audit": "↗ 審計加密層", "vault.stat_internet": "清單中的 INTERNET 權限", "vault.stat_tee": "硬體封存的金鑰", "vault.stat_wallet": "錢包託管與交接", "vault.stat_qr": "金鑰唯一的出口", "vault.tag_demo": "由示範影片重製", "vault.title_demo": "把保險箱握在手中", "vault.sub_demo": "左側是真實的 Vault 應用：SPARK 錢包視圖——餘額不過是簽名交易的總和，交接永遠只隔一次底部欄的點擊。中間是保險箱狀態頁，列出它所守護的每一個應用金鑰——點擊 <b>簽名</b>，觀看生物識別儀式。右側是手機對其自身隔離狀態的如實報告。", "vault.wallet_title": "SPARK 錢包", "vault.wallet_sub": "Vault 託管 · 簽名交易鏈", "vault.wallet_balsub": "餘額 = Σ 簽名交易", "vault.wallet_handover": "⇄ 錢包交接", "vault.wallet_keys": "金鑰：3 把", "vault.vs_title": "受守護的金鑰", "vault.vs_fingerprint": "指紋", "vault.vs_algorithm": "演算法", "vault.vs_sealed": "已封存", "vault.vs_sealed_val": "Keystore TEE · AES-256-GCM", "vault.vs_lastreq": "最近一次請求", "vault.vs_waiting": "等待中……", "vault.vs_sign": "簽署 Engine 請求", "vault.vs_migrate": "⟳ 遷移到新設備", "vault.bio_touch": "觸碰感應器", "vault.bio_title": "BiometricPrompt", "vault.bio_desc": "金鑰從不離開 TEE——它只在安全硬體內部簽名。", "vault.console_head": "adb shell — 物理隔離自檢", "vault.sim_caption": "<b>以上每個事件都是本地的。</b>主控台在網路上無事可報——因為根本不存在網路。", "vault.tag_guards": "它守護什麼", "vault.title_guards_a": "唯一的職責：成為", "vault.title_guards_grad": "每一個主權應用的保險箱", "vault.sub_guards": "Vault 在設計上與應用無關。任何形如 Engine 的東西——想要線上生活與離線金鑰並存的應用——都可以把它的身分託付給這座保險箱。", "vault.card1_t": "應用私鑰", "vault.card1_d": "由 Engine 之類的應用生成的 ECDSA P-256 身分，一到即被封存。", "vault.card2_t": "登入與錢包簽名", "vault.card2_d": "挑戰-回應式登入碼與 SPARK 錢包交易——在保險箱內簽名，絕不線上儲存。每一次餘額變動都是附加式鏈上的簽名交易。", "vault.card3_t": "設備遷移綁定", "vault.card3_d": "帶簽名重綁記錄，無需雲端備份即可把你的身分遷往全新硬體。", "vault.card4_t": "指紋目錄", "vault.card4_d": "每個受守護金鑰的本地登記簿：指紋與封存狀態，一目了然。", "vault.card5_t": "僅此而已", "vault.card5_d": "沒有瀏覽、沒有同步、沒有廣告、沒有遙測。它是一台帶螢幕的保險箱，而不是智慧型手機應用。", "vault.card6_t": "僅憑生物識別的解鎖", "vault.card6_d": "每次解鎖都通過 BiometricPrompt，並帶 ±120 秒新鮮窗口——基於時鐘的重放防護。", "vault.tag_ceremony": "線上應用如何離線簽名", "vault.title_ceremony_a": "金鑰簽名。", "vault.title_ceremony_grad": "金鑰從不離開。", "vault.pl1": "Engine 需要一個簽名", "vault.pl2": "IPC 請求 + 質詢", "vault.pl3": "BiometricPrompt", "vault.pl4": "TEE 解封並簽名", "vault.pl5": "已簽名回呼", "vault.pl6": "Engine 驗證簽名 + Δt&lt;120s", "vault.co_tag": "為什麼 ±120 秒窗口如此重要", "vault.co_text": "回呼簽名覆蓋 <b>sessionId ‖ status ‖ timestamp</b>。即使回呼被竊取，也無法在幾分鐘後重放——時鐘本身就是證明的一部分。中繼永遠看不到金鑰；Engine 永遠不持有金鑰；<b>只有 TEE 曾經持有。</b>", "vault.tag_migration": "新手機，相同身分", "vault.title_mig_a": "透過一束光", "vault.title_mig_grad": "搬家", "vault.sub_migration": "私鑰是唯一你絕不能託付給雲端的東西。當硬體更換時，Vault 會讓你的身分在設備之間螢幕對螢幕地行走——下面逐步示範。", "vault.migprev": "上一步", "vault.mignext": "下一步", "vault.flag_t": "FLAG_SECURE", "vault.flag_d": "QR Code 螢幕讓截圖與錄影全黑。剩下的唯一攻擊方式只有偷窺。", "vault.payload_t": "加密負載", "vault.payload_d": "綁定 URI 攜帶加密的工作階段負載——原始私鑰絕不出現於任何 URI 中。", "vault.burn_t": "綁定後燒毀", "vault.burn_d": "Engine 呼叫 convertBoundToPublicKeyOnly()——Vault 接管的那一刻，它的私鑰副本即被抹除。", "vault.title_compare": "今晚金鑰睡在哪裡？", "vault.th_storage": "儲存模型", "vault.th_network": "網路可達性", "vault.th_extraction": "提取風險", "vault.th_migration": "遷移路徑", "vault.tr_ext_t": "瀏覽器擴充錢包", "vault.tr_ext_reach": "始終在線", "vault.tr_ext_risk": "高——記憶體與磁碟均可讀", "vault.tr_ext_mig": "紙上的助記詞", "vault.tr_hot_t": "熱伺服器 / 託管", "vault.tr_hot_reach": "全天候攻擊面", "vault.tr_hot_risk": "系統性——一次攻破，全部金鑰外洩", "vault.tr_hot_mig": "信任營運方", "vault.tr_cloud_t": "雲端金鑰備份", "vault.tr_cloud_reach": "本質即同步", "vault.tr_cloud_risk": "帳號失守 = 金鑰失守", "vault.tr_cloud_mig": "重新下載", "vault.tr_vault_reach": "無 INTERNET 權限", "vault.tr_vault_risk": "TEE 晶片 + 生物識別門禁", "vault.tr_vault_mig": "QR Code 光通道，帶簽名重綁", "vault.co2_tag": "物理定律，而非承諾", "vault.co2_text": "表中每一行都依賴於某人行為良好。Vault 的隔離是在 Android 清單中宣告的、由作業系統強制執行的——<b>封包根本無法發出，因此無需任何承諾。</b>", "vault.foot_desc": "對 eneatlnc-cell Loop 的獨立解讀。E2EE 協定棧開放稽核；每一項主張都可追溯到程式碼與白皮書。", "vault.foot_layers": "層級", "vault.foot_engine": "主權社交", "vault.foot_vault": "離線託管", "vault.foot_havix": "L0 · 平行身分", "vault.foot_spark": "燃料", "vault.foot_rewards": "推薦政策", "vault.foot_loop": "Web4 迴路", "vault.foot_repos": "程式碼倉庫", "vault.foot_bottom": "金鑰離線 · SBT 治理 · $SPARK 燃料 · AI 特許", "vault.log_settle_pre": "計量批次已於 TEE 內聯簽 → 交易 #", "vault.log_settle_suf": " 已入鏈 · 餘額 = Σ 簽名交易", "vault.log_handover": "交接證書已簽名 · 全額餘額以創世交易遷移至新設備", "vault.log_bio_dismiss": "生物識別提示已關閉", "vault.log_ipc_pre": "已收到 IPC 簽名請求 · challenge=0x", "vault.log_ipc_suf": " · 等待生物識別", "vault.sig_result": "✓ 已簽名 · ECDSA P-256 · TEE", "vault.log_bio_ok": "生物識別 ✓ → 金鑰在 TEE 內解封 → 於安全世界內完成簽名 → 重新封存", "vault.log_callback": "回呼驗簽：sig(sessionId‖status‖ts) ✓ · Δt &lt; 120s ✓", "vault.mig1_title": "新設備生成全新金鑰對", "vault.mig1_desc": "新手機在 Engine 內生成自己的 ECDSA P-256 身分。任何東西都不會經空中通道匯入——永遠。", "vault.mig2_title": "舊 Vault 匯出遷移綁定", "vault.mig2_desc": "舊 Vault 將授權封入 QR Code 幀。FLAG_SECURE 讓截圖全黑；金鑰本體從不離開 TEE。", "vault.mig3_title": "新 Vault 掃碼——僅光學通道", "vault.mig3_desc": "ML Kit 透過相機讀取幀。這裡涉及的唯一網路就是光。", "vault.mig4_title": "身分重新綁定到新金鑰", "vault.mig4_desc": "帶簽名的重綁回呼將你的 DID 遷移到新設備的公鑰。聯絡人會自動驗證新指紋。", "vault.mig5_title": "SPARK 託管同步交接", "vault.mig5_desc": "舊 Vault 簽署交接證書，以全額餘額終結原鏈；新 Vault 驗證後以創世交易承接帳本——任何餘額都不存在未簽名的型態。", "vault.mig6_title": "舊副本燒毀，零殘留", "vault.mig6_desc": "舊 Vault 以零覆寫方式擦除封存金鑰。遷移完成——沒有任何金鑰碰過網際網路。", "vault.log_boot1": "AndroidManifest：uses-permission INTERNET → <b>未宣告</b> ✓", "vault.log_boot2": "網路棧：不可達 · sockets：無 · 遙測：無", "vault.log_boot3": "Keystore TEE 在線 · 金鑰已封存（AES-256-GCM）· 生物識別就緒", "vault.log_boot4": "SPARK 錢包鏈已就緒 · HWM 防重放 · 交接待命", "whitepaper.nav_home": "首頁", "whitepaper.nav_rewards": "獎勵", "whitepaper.kicker": "// 專案白皮書", "whitepaper.chip": "版本 1.0 · 草案", "whitepaper.h1": "SPARK <span class=\"grad\">&amp; Web4 主權迴路</span>", "whitepaper.hero_desc": "四個器官——<strong>Vault</strong>、<strong>Engine</strong>、<strong>Aether</strong>、<strong>Havix</strong>——構成一個閉環，<strong>SPARK</strong> 是驅動它轉動的燃料。E2EE 協定棧開放稽核；本文件描述已建成的架構、所設計的代幣經濟，以及雙軌制啟動：白名單預售之後是公開的基於 LBP 的 IDO。", "whitepaper.meta_1": "2026 年 8 月", "whitepaper.meta_2": "4 個程式碼倉庫 · AGPL + APACHE", "whitepaper.meta_3": "預售白名單已開放", "whitepaper.meta_4": "供應量 1,000T SPARK", "whitepaper.stat_dao": "DAO 儲備——治理門控", "whitepaper.stat_tge": "TGE 即可流通（含 10% 流動性）", "whitepaper.stat_cap": "每個錢包的預售上限", "whitepaper.stat_kb": "每則訊息每 KB 消耗的 SPARK", "whitepaper.abstract": "<b>摘要。</b>Web3 給了使用者錢包，卻把他們的社交生活留在伺服器上。Web4 原型迴路以 <mark class=\"key\">物理隔離</mark> 彌合這一鴻溝：一個不持有任何金鑰的線上社交應用（<strong>Engine</strong>）、一個持有金鑰但絕不連網的離線保險箱（<strong>Vault</strong>）、一個以 SBT 治理並儲存燃料儲備的議會（<strong>Aether</strong>），以及一個平行身分網路（<strong>Havix</strong>）——基於主 DID 派生、運行信用與價值雙重經濟——在活的章程之下特許 AI。<strong>$SPARK</strong> 是唯一發行資產：計量應用內的表達、為 DAO 儲備注資，並在其間流動——它是迴路的燃料，絕不是投票。本文件記錄公開倉庫中實際的架構，然後規定代幣：效用、分配（10% 預售 / 20% IDO / 10% DEX 流動性 / 50% DAO 儲備 / 10% 社區激勵）、兩階段啟動、解鎖安排，以及保障啟動公平、儲備主權的各項措施。", "whitepaper.toc1": "主權迴路", "whitepaper.toc2": "架構：隔離與身分", "whitepaper.toc3": "四大器官", "whitepaper.toc4": "SPARK 代幣經濟", "whitepaper.toc4b": "雙軌制啟動", "whitepaper.toc5": "儲備的治理", "whitepaper.toc6": "通往 TGE 的路線圖", "whitepaper.toc7": "風險與免責聲明", "whitepaper.ch1": "主權迴路", "whitepaper.ch1_p1": "這是<b>一個專案，而非一堆產品的組合</b>。每個倉庫是一個器官；器官共享同一套血液循環——SPARK。使用者在 Engine 中聊天；每一則訊息都在燃燒燃料；燃料儲蓄於 Aether 儲備；儲備由 Havix 上的特許 AI 保持流動；Havix 的網路效應讓 Engine 保持活力；而 Engine 的需求賦予了 SPARK 物質支撐。切斷任何一個器官，迴路就會停止轉動。", "whitepaper.th_organ": "器官", "whitepaper.th_metaphor": "隱喻", "whitepaper.th_function": "迴路中的功能", "whitepaper.th_status": "真實狀態", "whitepaper.rv_mt": "保險箱", "whitepaper.rv_fn": "離線保管每一把私鑰；代理簽名；僅透過 QR Code 遷移金鑰", "whitepaper.rv_st": "v3.70.0 已發布", "whitepaper.re_mt": "應用", "whitepaper.re_fn": "主權社交即時通訊；純記憶體、端到端加密；按 KB 消耗 SPARK", "whitepaper.re_st": "v3.64.7 已發布", "whitepaper.rs_mt": "燃料", "whitepaper.rs_fn": "計量表達；為儲備注資；連結儲備與市場", "whitepaper.rs_st": "預售 + IDO", "whitepaper.ra_mt": "議會", "whitepaper.ra_fn": "SBT 治理的 DAO：三個議院、靈魂綁定等級、多重簽名金庫", "whitepaper.ra_st": "v3.6 · BSC · 稽核關閉 · 主網待定", "whitepaper.rh_mt": "身分根", "whitepaper.rh_fn": "主 DID 派生的平行身分：4 上下文派生、信用與價值雙軌、AI 章程層面", "whitepaper.rh_st": "M10 封閉測試版", "whitepaper.rig_mt": "大腦", "whitepaper.rig_fn": "以自身身分進行推理的節點級 AI", "whitepaper.rig_st": "未來階段", "whitepaper.ch1_meta": "這些隱喻就是架構本身：<mark class=\"key\">保險箱從不碰觸網路</mark>、<mark class=\"key\">議會以靈魂綁定的 SBT 治理</mark>、<mark class=\"key\">大腦是被特許而非被信任</mark>。下文所述一切都可追溯到公開程式碼<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>。", "whitepaper.ch2": "架構：隔離與身分", "whitepaper.h21": "以物理隔離作為安全模型", "whitepaper.ch2_p1": "迴路最根本的安全決策是<b>以物理而非政策來分離</b>。Engine 線上執行卻不持有任何私鑰；Vault 持有金鑰，並且在建置時<b>完全沒有任何網路權限</b>——它的 Android 清單不宣告任何 INTERNET 權限，使得資料外洩成為物理問題而非邏輯問題<sup><a href=\"#cite-3\">[3]</a></sup>。簽名請求經由受簽名保護的系統間通訊（IPC）從 Engine 傳輸到 Vault；金鑰材料只以加密的 QR Code 幀在裝置間傳輸——相機對相機、物理隔離強制<sup><a href=\"#cite-3\">[3]</a></sup>。", "whitepaper.ch2_p2": "信任是可稽核的：Engine 的 <span class=\"mono\">core/</span> 模組（協定、加密、IPC）與 Vault 的<b>逐位元組相同</b>，因此兩個應用都對照同一份公開原始碼驗證<sup><a href=\"#cite-1\">[1]</a></sup>。訊息透過 ECDH 金鑰協商與 AES-256-GCM 進行端到端加密；中繼看到的是信封，絕非明文<sup><a href=\"#cite-1\">[1]</a></sup>。", "whitepaper.h22": "一個身分，四個不可關聯的上下文", "whitepaper.ch2_p3": "Havix 使用 HKDF 從單一主金鑰派生四個特定上下文的子身分——公開、市場、隧道與百科上下文<sup><a href=\"#cite-6\">[6]</a></sup>。該派生在密碼學上不可關聯：你的市場身分無法與你的私人通訊產生關聯。這正是讓一個人可以同時是 <mark class=\"key\">議會中的公民、市場上的交易者，以及聊天中的私人個體</mark>——無需三個帳號，也無需平台掌握對映表。", "whitepaper.h23": "三個層面，一條迴路", "whitepaper.ch2_li1": "<b>應用層（線上）：</b>Engine——面向使用者、無金鑰、純記憶體。訊息只存在於 RAM 中；被查封的攻擊面幾乎為零。", "whitepaper.ch2_li2": "<b>託管層（離線）：</b>Vault——金鑰庫封存於生物識別之後，只能透過 QR Code 匯出。", "whitepaper.ch2_li3": "<b>協調層（鏈下 P2P）：</b>Havix——身分派生、聲譽/信用帳本、仲裁，以及特許 AI 的章程<sup><a href=\"#cite-6\">[6]</a></sup>。", "whitepaper.ch2_li4": "<b>結算層（鏈上）：</b>BNB 智慧鏈上的 Aether——治理、金庫與時鎖執行，由靈魂綁定的 SBT 等級而非可轉讓的代幣供應來治理<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>。", "whitepaper.ch2_p4": "Havix 自己的路線圖將之形式化為三層棧——網路基岩（L0）、認知執行（L1，Germ）、鏈上治理（L2，Aether）——以 4 上下文 DID 強制各層之間的密碼學分離<sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.ch3": "四大器官", "whitepaper.h31": "Vault——保險箱", "whitepaper.note31": "v3.70.0 · 已發布", "whitepaper.ch3_p1": "一個通用的離線金鑰庫，而非 Engine 的附屬品：它可以為任何合規應用保管金鑰。機制：無網路權限；金鑰庫封存於 TEE；生物識別門控簽名（可用時由 StrongBox 支撐）；SPARK 錢包託管——餘額以安全世界內共同簽名的只新增交易鏈形式存在，錢包交接將全額餘額作為創世交易遷移到新設備；只能透過 QR Code 遷移到新硬體，私鑰絕不進入網路棧<sup><a href=\"#cite-3\">[3]</a></sup>。自 v3.40 起，Engine 透過受簽名保護的 Binder IPC 直連通道存取 Vault——舊的跨應用跳轉對話方塊已移除<sup><a href=\"#cite-3\">[3]</a></sup>。", "whitepaper.ch3_p2": "整個迴路的市場切入點：一個採用純記憶體架構、具備群組訊息、60 種表情表達經濟與 DID 檔案的主權社交即時通訊<sup><a href=\"#cite-1\">[1]</a></sup>。其經濟引擎已在倉庫中明確規定：<mark class=\"key\">每 1 KB 消耗 10 SPARK</mark>——每則訊息按其 UTF-8 大小計量並向上取整，每則訊息至少 10 SPARK；每日燃料補貼 1,000 SPARK（按自然日冪等，由權威帳本裁定，須通過綁定的 Vault 身分門檻）；重度使用者從錢包儲值<sup><a href=\"#cite-2\">[2]</a></sup>。錢包餘額並非儲存的數字：它是由 Vault 持有的錢包金鑰共同簽名的只新增交易鏈派生——每一次餘額變動，無一例外，都是一筆簽名交易<sup><a href=\"#cite-2\">[2]</a></sup>。用戶端預扣已實作；獨立的 spark-ledger 服務在伺服器端結算餘額<sup><a href=\"#cite-2\">[2]</a></sup>。", "whitepaper.h33": "Aether——議會", "whitepaper.note33": "v3.6 · BSC · 稽核關閉 · 主網待定", "whitepaper.ch3_p3": "一個在 BNB 智慧鏈上由 SBT 治理的 DAO 核心。權重是掙來的而非買來的：AetherRing 鑄造 14 個不可轉讓的靈魂綁定等級；三個議院（議事會、議會、長老會）加上公民公投，透過一個帶長老否決權的 7 階段提案生命週期相互制衡；金庫是執行時鎖呼叫的 3/5 Safe 多重簽名<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>。刻意設計的張力：<mark class=\"key\">治理是靈魂綁定的（SBT），而燃料是真實發行的資產</mark>——大戶可以購買 $SPARK，但 $SPARK 購買的是訊息，不是選票。有一個合約與眾不同：AetherDonation 是一個<b>外部慈善通道</b>（為公共產品提供 USDC 小費），與迴路的經濟無關。", "whitepaper.h34": "Havix——身分根", "whitepaper.note34": "已驗證 · 待命", "whitepaper.ch3_p4": "迴路底層的協調網路：八個模組（身分、訊息類型、信用、擔保、百科、仲裁、市場、s-node 執行階段），1,174 個通過的測試（MVP 980 + 驗證實驗 194，M10 稽核基線），以及兩輪稽核專案——M9 關閉了全部 15 項發現，而 M10 深度稽核又浮現 52 項（5 個 P0 + 15 個 P1 + 32 個 P2），P0/P1 在封閉測試前已修復<sup><a href=\"#cite-6\">[6]</a></sup>。它的章程層面正是把 AI 置於法律而非魔法的立足點上：例行操作自動執行並附帶憑證；<mark class=\"key\">紅線操作被物理地路由到由人進行的鏈上投票</mark>。章程儲存與攔截器已排入 M11 工作流<sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.h35": "Germ——大腦，稍後", "whitepaper.ch3_p5": "Germ 是節點級 AI 層：在 Havix 網路上以自身 4 上下文身分進行推理的 AI。它被有意地延後——<mark class=\"key\">Engine 才是今天的市場入口</mark>；當迴路有了值得呵護的使用者時，大腦才會到來。本白皮書中，Germ 只在經濟必須為其預留空間之處出現（儲備 AI，§5）。", "whitepaper.ch4": "SPARK 代幣經濟", "whitepaper.h41": "效用：有物理支撐的燃料", "whitepaper.ch4_p1": "SPARK 是一種<b>計量資產</b>。在 Engine 中，每 1 KB 消耗 10 SPARK——按訊息大小計量、向上取整、每則至少 10——計費表在協定中，而不是在服務條款裡<sup><a href=\"#cite-2\">[2]</a></sup>。預算源自真實的 100&nbsp;Mbps 中繼基線：文字信封最多 40&nbsp;KB，媒體最多 48&nbsp;KB，128&nbsp;KB 的硬上限幀，群組上限 200 人<sup><a href=\"#cite-1\">[1]</a></sup>。因為每一個表達位元組都要消耗燃料，垃圾訊息有了邊際成本，而發言依然免費。", "whitepaper.ch4_li1": "<b>取得：</b>每日燃料補貼（每個自然日 1,000 SPARK，冪等，須通過綁定的 Vault 身分門檻<sup><a href=\"#cite-2\">[2]</a></sup>）、錢包儲值<sup><a href=\"#cite-2\">[2]</a></sup>，或在 TGE 後從市場購買。", "whitepaper.ch4_li2": "<b>消耗：</b>訊息燃料；群組與媒體預算；SDK 應用的使用。", "whitepaper.ch4_li3": "<b>持有：</b>DAO 金庫以 SPARK 作為其長期儲備——真實使用所帶來的需求對稱地累積到每一位持有者。", "whitepaper.ch4_note": "◇ 設計參數（歸屬期長度、流動性鎖定、費用路由、補貼衰減）是本草案的建議預設值；每一項都會在預售開始前由治理確認或修訂。鏈上計量費率（1 KB = 10 SPARK，每則至少 10；每個自然日 1,000 燃料補貼）在 Engine 規範中已固定<sup><a href=\"#cite-2\">[2]</a></sup>。", "whitepaper.h42": "同一資產的兩種階段——計量帳本，然後是固定供應", "whitepaper.ch4_p2": "SPARK 以兩個刻意的階段發布，而順序本身就是設計。<b>階段 A——計量帳本（現已執行）：</b>在已發布的 Engine 軟體內部，SPARK 以一種鏈下雜湊連結的帳本存在。每台設備透過 Vault 聯簽的燃料補貼每天铸造 <b>1,000</b>——反女巫防禦已投入生產：TEE/DRM 設備錨、中繼側對不可關聯設備雜湊的每日去重，以及在簽名門檻強制執行的金額白名單。階段 A 的餘額<mark class=\"key\">不可轉讓、不可交易、不可兌換</mark>——它們今天是配額，而非證券。", "whitepaper.ch4_p3": "<b>階段 B——TGE 對映（計畫中）：</b>固定的 <b>1,000T 供應量</b>在 TGE 生效。初始供應將 §4.3 的預售、IDO、流動性、儲備各份額與基於快照的階段 A 餘額對映（納入社區激勵份額）相結合——具體轉換參數是草案預設值 ◇，在預售開始前由治理確認。TGE 之後，SPARK 自由流通，<b>包括開放的 USDC 及其他穩定幣交易對</b>。轉換通道目前刻意不建置：設備錨定、每日去重與金額白名單必須<i>先於</i>待守護的金庫存在，這樣當可兌換性到來那天，這些防禦從配額衛生升級為金庫大門。", "whitepaper.h43": "供應與分配", "whitepaper.ch4_p4": "總供應量固定為 <b>1,000T SPARK（1,000,000,000,000,000——一千兆）</b>。分配遵循 10 / 20 / 10 / 50 / 10 拆分：預售、IDO、DEX 流動性、DAO 儲備、社區激勵。這裡<mark class=\"key\">沒有團隊份額、沒有內部人員分配、沒有行銷份額</mark>——團隊的成長空間在於它與 DAO 共享的 50% 儲備，只能透過公開治理解鎖，並以每年 ≤5% 的儲備上限由章程約束。", "whitepaper.fig1": "圖 1 — TGE 時的 SPARK 分配（已細化：10 個切片，5 個份額）", "whitepaper.fig1_sub": "總供應量 1,000T（1,000,000,000,000,000）。預售在 TGE 拆分 2.5% + 7.5% 歸屬；IDO 拆分 5% 於 TGE + 15% 歸屬（兩個份額均為：TGE 時 25%，隨後 9 個月線性）；儲備子拆分是受章程約束的草案預設值 ◇，釋放上限 ≤5%/年——儲備本身沒有日曆解鎖。", "whitepaper.th_tranche": "份額", "whitepaper.th_share": "佔比", "whitepaper.th_amount": "數量", "whitepaper.th_unlock": "解鎖安排", "vault.foot_home": "首頁", "whitepaper.ch4b": "雙軌啟動", "whitepaper.h44": "階段 1——預售（10%）", "whitepaper.h45": "階段 2——IDO（20%）", "whitepaper.h46": "流動性與 DEX（10%）", "whitepaper.h47": "解鎖安排", "whitepaper.h48": "保障與合規", "whitepaper.h32": "Engine——應用", "whitepaper.note32": "v3.64.7 · 已發布", "whitepaper.ch5": "儲備治理", "whitepaper.ch6": "通往 TGE 的路線圖", "whitepaper.ch7": "風險與免責聲明", "whitepaper.fig2": "圖 2 — TGE 後的流通供應", "whitepaper.m1": "預售——白名單 · 每人 $500 上限", "whitepaper.m2": "IDO——LBP · 3–7 天", "whitepaper.m3": "流動性——在 TGE 注入", "whitepaper.m4": "社區激勵——推薦與啟用", "whitepaper.m5": "DAO 儲備——由治理閘控 · ≤5%/年", "whitepaper.tl_now_t": "迴路投入實際使用", "whitepaper.tltge_t": "代幣生成事件", "whitepaper.tl01_t": "白名單與參數定案", "whitepaper.tl02_t": "預售窗口期", "whitepaper.tl03_t": "在 LBP 上進行的 IDO", "whitepaper.tl9_t": "流通量達到上限 · DAO 接管儲備", "whitepaper.tll1_t": "Germ，稍後", "whitepaper.src": "資料來源", "whitepaper.src6": "eneatlnc-cell，Havix 倉庫——平行身分網路：8 個模組，1,174 項測試（M10 稽核基線），15 項稽核發現已關閉。", "whitepaper.src1": "eneatlnc-cell，Engine 3.0——E2EE 協定棧的公開稽核版（core-crypto、core-protocol、core-ipc；AGPL-3.0）。", "whitepaper.src2": "Engine，SparkEconomy 工程記錄（內部）——1 KB = 10 SPARK（每則至少 10）、每個自然日 1,000 的每日燃料補貼、簽名交易 SPARK 錢包（v3.37+）、錢包儲值、spark-ledger 服務計畫。", "whitepaper.src3": "eneatlnc-cell，Engine 3.0——core-ipc：離線金鑰庫背後的 Engine↔Vault 簽名契約（無網路權限、生物識別簽名、QR Code 遷移）。", "whitepaper.src4": "eneatlnc-cell，Aether 倉庫——SBT 治理的 DAO 核心：AetherRing、Governance、Election、Safe 金庫。", "whitepaper.src5": "Aether，docs/TECHNICAL_WHITEPAPER.md——三個議院、7 階段生命週期、長老否決、議院/公民權重的平衡。", "whitepaper.src7": "Havix，NEXT-STEPS.md——L0/L1/L2 三層棧、M11 章程儲存與紅線攔截器計畫。", "whitepaper.foot_copy": "© <span class=\"yr\">2026</span> SparkLoop · 白皮書 v1.0 草案", "whitepaper.foot_cta": "加入預售白名單", "whitepaper.tr_presale_amt": "100T", "whitepaper.tr_presale_t": "預售——白名單", "whitepaper.tr_tge_amt": "25T", "whitepaper.tr_tge_t": "└ TGE 解鎖", "whitepaper.tr_tge_un": "TGE 時流通", "whitepaper.tr_9m_amt": "75T", "whitepaper.tr_9m_t": "└ 9 個月歸屬", "whitepaper.tr_9m_un": "線性，第 1–9 個月", "whitepaper.tr_a_un": "TGE 時 25% ◇，隨後 9 個月線性 ◇", "whitepaper.tr_b_un": "TGE 時 25% ◇，隨後 9 個月線性 ◇", "whitepaper.tr_ido_amt": "200T", "whitepaper.tr_ido_t": "IDO——公開 LBP 輪次", "whitepaper.tr_tge2_amt": "50T", "whitepaper.tr_tge2_t": "└ TGE 解鎖", "whitepaper.tr_9m2_amt": "150T", "whitepaper.tr_9m2_t": "└ 9 個月歸屬", "whitepaper.tr_dex_amt": "100T", "whitepaper.tr_dex_t": "DEX 流動性", "whitepaper.tr_dex_un": "在 TGE 注入資金池 · LP 鎖定 12 個月 ◇", "whitepaper.tr_dao_amt": "500T", "whitepaper.tr_dao_t": "DAO 儲備", "whitepaper.tr_dao_un": "無日曆解鎖——僅由 Aether 提案釋放 · 章程上限 ≤5%/年", "whitepaper.tr_comm_amt": "100T", "whitepaper.tr_comm_t": "社區激勵", "whitepaper.tr_comm_un": "推薦獎勵 + 啟用獎金 · 按專案結算", "whitepaper.tr_fuel_amt": "150T", "whitepaper.tr_fuel_t": "└ Engine 燃料補貼", "whitepaper.tr_fuel_un": "章程預設 ◇——補貼週期", "whitepaper.tr_relay_amt": "100T", "whitepaper.tr_relay_t": "└ 中繼與基礎設施", "whitepaper.tr_relay_un": "章程預設 ◇——中繼、s-node", "whitepaper.tr_eco_amt": "150T", "whitepaper.tr_eco_t": "└ 生態系統資助", "whitepaper.tr_eco_un": "章程預設 ◇——應用、中繼、工具", "whitepaper.tr_ai_amt": "100T", "whitepaper.tr_ai_t": "└ AI 流動性與捐贈基金", "whitepaper.tr_ai_un": "章程預設 ◇——AI 界限", "whitepaper.ch4b_p1": "啟動的核心是<b>預售與 IDO 並行、節奏不同</b>：預售面向核心社群；IDO 面向公眾。<mark class=\"key\">預售建立基本盤；IDO 打開市場。</mark>", "whitepaper.ch4b_li1": "<b>受眾：</b>僅限早期核心貢獻者與活躍社群成員。錢包地址提前收集為白名單；開始時間最先通知名單。", "whitepaper.ch4b_li2": "<b>反大額：</b>硬性的 <mark class=\"key\">每人 $500 上限</mark>。", "whitepaper.ch4b_li3": "<b>條款：</b>以固定的低價用 USDT 或 BNB 支付；25% 在 TGE 解鎖，其餘在 9 個月內線性歸屬 ◇。", "whitepaper.ch4b_li4": "<b>執行：</b>窗口開啟時，白名單錢包在官網連線並在上限內認購。", "whitepaper.ch4b2_li1": "<b>平台：</b>Fjord Foundry 級別的 LBP 發射台——價格從高位起並隨需求追上而衰減，這<mark class=\"key\">消除了狙擊優勢</mark>；無白名單、無首發區塊優勢。", "whitepaper.ch4b2_li2": "<b>參數：</b>注入資金池前三重核驗代幣地址（不可逆）；以 USDT 或 BNB 支付；3–7 天的窗口期；每個錢包的最低與最高上限；起始價高於預售價。", "whitepaper.ch4b2_li3": "<b>分配：</b>每錢包配額的 25% 在 TGE 可申領，其餘在 9 個月內線性歸屬 ◇；所得直接流入專案多重簽名。", "whitepaper.ch4b2_li4": "<b>對帳：</b>窗口關閉後，認購名單與金額先與帳目核對並公布，然後再行分配。", "whitepaper.ch4b3_note": "地址在部署的瞬間於 Spark 頁面公布。在此之前，任何自稱 SPARK 的地址均為詐欺。", "whitepaper.ch4b3_p1": "在 TGE，流動性份額注入 DEX 資金池，與 BNB 配對。SPARK 建議作為 BNB 鏈上的 BEP-20 代幣發行 ◇——與兩輪的 USDT/BNB 支付軌道一致——同時 Aether 金庫與治理部署在同一條 BNB 智慧鏈上<sup><a href=\"#cite-4\">[4]</a></sup>，因此儲備操作無需跨鏈橋即可原生結算<sup><a href=\"#cite-5\">[5]</a></sup>。", "whitepaper.ch4b4_p1": "結構性承諾是<mark class=\"key\">硬性的流通上限</mark>：日曆解鎖永遠不會超過 40%（預售 + IDO + LP）；10% 的激勵份額只針對已驗證的推薦與啟用發放；50% 的儲備只能透過公開、可否決的提案流動，章程將釋放上限設為<b>每年儲備的 ≤5%</b>。早期買家清楚知道最大流通量是多少。", "whitepaper.ch5_p1": "50% 的儲備不是一個金庫錢包——它是一個<b>憲法性對象</b>。託管置於 3/5 的 Safe 多重簽名中；每一次流動都需要經過 Aether 的 7 階段生命週期的提案、挺過長老否決窗口，並經時鎖執行<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>。這一過程中的權重是靈魂綁定且靠掙得的——14 個既不能購買也不能轉讓的 AetherRing 等級<sup><a href=\"#cite-4\">[4]</a></sup>。", "whitepaper.ch5_p2": "儲備用途由章程界定：面向 Engine 燃料的使用者補貼週期、中繼與基礎設施資金、生態系統資助，以及——一旦 Germ 存在——由特許 AI 在硬性限制內進行流動性管理並設定紅線回溯至人類投票<sup><a href=\"#cite-6\">[6]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>。章程還確立了<mark class=\"key\">每年儲備 ≤5% 的釋放率上限</mark>——這是可計算的承諾，而非酌情決定：即使金庫被完全掌控，也無法以超過每年二十分之一的速度耗盡儲備。平衡設計是刻意的：<mark class=\"key\">議院與公民各持約一半的投票權重</mark>，因此機構與人群都無法單獨動用儲備<sup><a href=\"#cite-5\">[5]</a></sup>。", "whitepaper.ch7_disc": "<b>免責聲明。</b>本白皮書描述一個開源軟體專案及其燃料資產。它不是投資建議、不是出售證券的要約、也不是回報承諾。標註 ◇ 的參數是草案預設值，可能在發布前變更。這條迴路裡沒有「相信我」式行銷：請閱讀倉庫。", "whitepaper.ch7_li1": "<b>執行風險：</b>Aether 主網部署、M11 章程儲存與 spark-ledger 服務是 TGE 流程所依賴的未完成組件<sup><a href=\"#cite-2\">[2]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.ch7_li2": "<b>跨鏈風險：</b>已在設計上緩解——SPARK 與 Aether 治理/金庫部署在同一條 BNB 智慧鏈 ◇，因此儲備操作無需任何橋依賴即可原生結算。", "whitepaper.ch7_li3": "<b>市場風險：</b>LBP 誠實地發現價格——這意味著它也可能向下發現價格。固定的低價預售定價補償了早期信任，但並不保證報酬。", "whitepaper.ch7_li4": "<b>監理風險：</b>代幣發行面臨不盡相同的監管；不同司法轄區可能施加限制；法律顧問審查是一項前置條件，而非走形式。", "whitepaper.ch7_li5": "<b>智慧合約風險：</b>稽核能降低但永遠無法消除風險；只與官網公布的地址進行互動。", "whitepaper.fig2_sub": "流通量：TGE 時為 17.5%（2.5% 預售 + 5% IDO + 10% LP），隨兩個份額歸屬每月上升 2.5%，並在之後第 9 個月達到其 40% 的日曆上限。10% 的激勵份額按專案結算；其餘 50% 僅透過治理流動，章程上限為 ≤5%/年。", "whitepaper.tl_now_d": "Engine v3.64.7 與 Vault v3.70.0 已交付——Binder IPC 直連通道與簽名交易 SPARK 錢包上線，兩個應用均已用 R8 混淆加固，每日燃料補貼在中繼處以不可關聯的裝置-日雜湊去重；Havix 在關閉 15 項稽核發現後進入封閉測試；BSC 上的 Aether v3.6（稽核修復已關閉）正待主網部署<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>。預售白名單已開放。", "whitepaper.tl01_d": "錢包地址已收集；預售價格、IDO 邊界、歸屬與 LP 鎖定參數已確認；合約已稽核且地址已公布。", "whitepaper.tl02_d": "白名單錢包以固定的低價、在 $500 上限內用 USDT/BNB 認購。", "whitepaper.tl03_d": "3–7 天的公開輪次；價格自行發現；收盤時公布對帳結果。", "whitepaper.tl9_d": "預售與 IDO 歸屬完成——日曆流通量達到其 40% 上限；Aether 主網治理全面接管儲備職權，釋放以章程上限 ≤5%/年約束。", "whitepaper.tltge_d": "預售 25% + IDO 25% 的初始分配進入錢包；10% 的流動性份額注入 DEX 資金池；spark-ledger 上線用於 Engine 結算<sup><a href=\"#cite-2\">[2]</a></sup>。", "whitepaper.tll1_d": "節點級 AI 在章程下加入網路——大腦到來，照料一條已然跳動的迴路<sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.ch4b5_li1": "<b>安全：</b>代幣、預售與 LBP 合約在接收任何資金前必須通過公認機構的稽核；報告與地址一同公布。", "whitepaper.ch4b5_li2": "<b>透明：</b>預售與 IDO 的合約地址和規則在每段窗口開啟前公布；認購對帳結果在 TGE 分配前發布。", "whitepaper.ch4b5_li3": "<b>反機器人：</b>LBP 的價格衰減擊敗狙擊；每錢包上限（預售 $500；IDO 最小/最大）限制集中度；預售合約上可能應用動態滑點邊界 ◇。", "whitepaper.ch4b5_li4": "<b>法律：</b>本次啟動正由法律顧問就相關司法轄區進行審核；必要時參與可能受限。此處任何內容都不是證券要約。"},
  ja: {"vault.nav_home": "ホーム", "vault.nav_rewards": "リワード", "vault.chip": "オフライン · エアギャップ · 主権", "vault.h1_a": "決してネットワークに", "vault.h1_grad": "決して話さない金庫", "vault.hero_desc": "<strong>Vault</strong> は Engine 系アプリのための汎用オフライン金庫です。<strong>ネットワーク権限ゼロ</strong>で秘密鍵とログイン署名を保存し、端末のセキュアシリコンに封入、指紋で署名し、光だけで——QR コード——鍵を新しいハードウェアへ移します。「接続しないと約束します」ではなく、<strong>接続できません</strong>。", "vault.btn_ceremony": "▶ 署名の儀式を試す", "vault.btn_migration": "⟳ 鍵の移行", "vault.btn_audit": "↗ 暗号層の監査", "vault.stat_internet": "マニフェスト内の INTERNET 権限", "vault.stat_tee": "ハードウェア封入の鍵", "vault.stat_wallet": "ウォレット保管と引き継ぎ", "vault.stat_qr": "鍵の唯一の出口", "vault.tag_demo": "デモ映像から再現", "vault.title_demo": "金庫を手に取る", "vault.sub_demo": "左は実際の Vault アプリ:SPARK ウォレット表示——残高は署名済み取引の合計にすぎず、引き継ぎは常に下部バーから1タップ。中央は Vault が守る全アプリ鍵を一覧するステータス画面。<b>Sign</b> を押すと生体認証の儀式が始まります。右は電話自体が自らの隔離状態を報告したもの。", "vault.wallet_title": "SPARK ウォレット", "vault.wallet_sub": "Vault 保管 · 署名取引チェーン", "vault.wallet_balsub": "残高 = Σ 署名済み取引", "vault.wallet_handover": "⇄ ウォレット引き継ぎ", "vault.wallet_keys": "鍵: 3", "vault.vs_title": "守護中の鍵", "vault.vs_fingerprint": "フィンガープリント", "vault.vs_algorithm": "アルゴリズム", "vault.vs_sealed": "封入済み", "vault.vs_sealed_val": "Keystore TEE · AES-256-GCM", "vault.vs_lastreq": "最後の要求", "vault.vs_waiting": "待機中…", "vault.vs_sign": "Engine リクエストに署名", "vault.vs_migrate": "⟳ 新しい端末へ移行", "vault.bio_touch": "センサーに触れてください", "vault.bio_title": "BiometricPrompt", "vault.bio_desc": "鍵は TEE から決して出ません——安全なハードウェア内で署名します。", "vault.console_head": "adb shell — エアギャップ自己点検", "vault.sim_caption": "<b>上記のイベントはすべてローカルです。</b>コンソールにネットワークからの報告はありません——ネットワークが存在しないからです。", "vault.tag_guards": "何を守るのか", "vault.title_guards_a": "仕事はただひとつ:", "vault.title_guards_grad": "あらゆる主権アプリの金庫", "vault.sub_guards": "Vault は設計上アプリ非依存です。Engine のような——オンライン生活とオフラインの鍵を両立したいアプリ——なら、その身分を金庫に委ねられます。", "vault.card1_t": "アプリの秘密鍵", "vault.card1_d": "Engine などのアプリが生成した ECDSA P-256 身分で、到着した瞬間に封入されます。", "vault.card2_t": "ログインとウォレット署名", "vault.card2_d": "チャレンジ・レスポンスのログインコードと SPARK ウォレット取引——金庫内で署名され、決してオンライン保存されません。残高の変化はいずれも append-only チェーン上の署名取引です。", "vault.card3_t": "端末移行バインディング", "vault.card3_d": "署名付き再バインド記録で、クラウドバックアップなしに身分を新しいハードウェアへ移します。", "vault.card4_t": "フィンガープリント台帳", "vault.card4_d": "守護中の全鍵のローカル台帳:フィンガープリントと封入状態を一目で確認できます。", "vault.card5_t": "それ以外は何もない", "vault.card5_d": "ブラウズも、同期も、広告も、テレメトリもありません。画面付きの金庫であって、スマホアプリではありません。", "vault.card6_t": "生体認証のみで解除", "vault.card6_d": "すべての解除は ±120 秒のフレッシュネス窓付きで BiometricPrompt を通過します——時計ベースのリプレイ保護。", "vault.tag_ceremony": "オンラインアプリがどうオフラインで署名するか", "vault.title_ceremony_a": "鍵が署名する。", "vault.title_ceremony_grad": "鍵は決して離れない。", "vault.pl1": "Engine が署名を要求", "vault.pl2": "IPC 要求 + チャレンジ", "vault.pl3": "BiometricPrompt", "vault.pl4": "TEE が解除し署名", "vault.pl5": "署名済みコールバック", "vault.pl6": "Engine が署名と Δt&lt;120s を検証", "vault.co_tag": "なぜ ±120 秒の窓が重要なのか", "vault.co_text": "コールバック署名は <b>sessionId ‖ status ‖ timestamp</b> を覆います。コールバックが盗まれても数分後に再送はできません——時計が証明の一部だからです。リレーは鍵を見ず、Engine も鍵を持ちません。<b>TEE だけが持ちます。</b>", "vault.tag_migration": "新しい端末、同じ身分", "vault.title_mig_a": "光の束を使って", "vault.title_mig_grad": "引っ越す", "vault.sub_migration": "秘密鍵は唯一、クラウドに決して任せてはいけないものです。ハードウェアが変わると、Vault は画面から画面へ身分を移します——以下で順に体験。", "vault.migprev": "前へ", "vault.mignext": "次へ", "vault.flag_t": "FLAG_SECURE", "vault.flag_d": "QR 画面はスクリーンショットと録画を真っ黒にします。残る攻撃手段は肩越しの盗み見だけです。", "vault.payload_t": "暗号化ペイロード", "vault.payload_d": "バインド URI は暗号化されたセッションペイロードを持ちます——生の秘密鍵は決して URI に現れません。", "vault.burn_t": "バインド後は焼却", "vault.burn_d": "Engine は convertBoundToPublicKeyOnly() を呼びます——Vault が引き継いだ瞬間、秘密鍵のコピーは消去されます。", "vault.title_compare": "今夜、鍵はどこで眠るのか？", "vault.th_storage": "保管モデル", "vault.th_network": "ネットワーク到達性", "vault.th_extraction": "抽出リスク", "vault.th_migration": "移行経路", "vault.tr_ext_t": "ブラウザ拡張ウォレット", "vault.tr_ext_reach": "常時オンライン", "vault.tr_ext_risk": "高 — メモリとディスクが読み取り可能", "vault.tr_ext_mig": "紙のシードフレーズ", "vault.tr_hot_t": "ホットサーバー / カストディ", "vault.tr_hot_reach": "24時間365日の攻撃面", "vault.tr_hot_risk": "全体的 — 一度の侵害で全鍵", "vault.tr_hot_mig": "運用者を信頼", "vault.tr_cloud_t": "クラウド鍵バックアップ", "vault.tr_cloud_reach": "設計上同期", "vault.tr_cloud_risk": "アカウント侵害 = 鍵侵害", "vault.tr_cloud_mig": "再ダウンロード", "vault.tr_vault_reach": "INTERNET 権限なし", "vault.tr_vault_risk": "TEE シリコン + 生体認証ゲート", "vault.tr_vault_mig": "QR 光チャネル、署名付き再バインド", "vault.co2_tag": "約束ではなく物理", "vault.co2_text": "表のどの行も「誰かがまともに振る舞う」ことに依存しています。Vault の隔離は Android マニフェストで宣言され OS が強制します——<b>パケットは送れないので、約束はそもそも不要です。</b>", "vault.foot_desc": "eneatlnc-cell Loop の独立した解釈です。E2EE プロトコルスタックは監査に開放されています。あらゆる主張はコードとホワイトペーパーに遡れます。", "vault.foot_layers": "レイヤー", "vault.foot_engine": "主権ソーシャル", "vault.foot_vault": "オフライン保管", "vault.foot_havix": "L0 · パラレル身分", "vault.foot_spark": "燃料", "vault.foot_rewards": "紹介ポリシー", "vault.foot_loop": "Web4 ループ", "vault.foot_repos": "リポジトリ", "vault.foot_bottom": "鍵はオフライン · SBT ガバナンス · $SPARK 燃料 · AI 認可", "vault.log_settle_pre": "計量バッチが TEE 内で共同署名 → tx #", "vault.log_settle_suf": " チェーンに追加 · 残高 = Σ 署名済み取引", "vault.log_handover": "引き継ぎ証明書に署名 · 全残高が創世取引として新端末へ移行", "vault.log_bio_dismiss": "生体認証プロンプトが閉じられました", "vault.log_ipc_pre": "IPC 署名要求を受領 · challenge=0x", "vault.log_ipc_suf": " · 生体認証を待機中", "vault.sig_result": "✓ 署名済み · ECDSA P-256 · TEE", "vault.log_bio_ok": "生体認証 ✓ → TEE 内で鍵を解除 → セキュア世界で署名 → 再封入", "vault.log_callback": "コールバック検証:sig(sessionId‖status‖ts) ✓ · Δt &lt; 120s ✓", "vault.mig1_title": "新しい端末が新しい鍵ペアを生成", "vault.mig1_desc": "新しい端末は Engine 内で独自の ECDSA P-256 身分を生成します。空中から何もインポートされません——決して。", "vault.mig2_title": "旧 Vault が移行バインディングを出力", "vault.mig2_desc": "旧 Vault は QR フレームに許可を封じます。FLAG_SECURE がスクリーンショットを黒くし、鍵自体は決して TEE を離れません。", "vault.mig3_title": "新 Vault がスキャン——光チャネルのみ", "vault.mig3_desc": "ML Kit がカメラを通してフレームを読み取ります。関わる唯一のネットワークは光です。", "vault.mig4_title": "身分が新しい鍵に再バインド", "vault.mig4_desc": "署名付き再バインドコールバックが DID を新端末の公開鍵へ移します。連絡先は新しい指紋を自動検証します。", "vault.mig5_title": "SPARK 保管も引き継がれる", "vault.mig5_desc": "旧 Vault が全残高でチェーンを終了する引き継ぎ証明書に署名し、新 Vault が検証して創世取引で台帳を引き継ぎます——未署名の残高は一切存在しません。", "vault.mig6_title": "旧コピーを焼却、残滓ゼロ", "vault.mig6_desc": "旧 Vault はゼロオーバーライトで封入鍵を消去します。移行完了——どの鍵もインターネットに触れていません。", "vault.log_boot1": "AndroidManifest: uses-permission INTERNET → <b>見つからない</b> ✓", "vault.log_boot2": "ネットワークスタック:到達不可 · socket:なし · テレメトリ:なし", "vault.log_boot3": "Keystore TEE 稼働 · 鍵封入済み（AES-256-GCM）· 生体認証待機", "vault.log_boot4": "SPARK ウォレットチェーン準備完了 · HWM アンチリプレイ · 引き継ぎ準備", "whitepaper.nav_home": "ホーム", "whitepaper.nav_rewards": "リワード", "whitepaper.kicker": "// プロジェクトホワイトペーパー", "whitepaper.chip": "バージョン 1.0 · ドラフト", "whitepaper.h1": "SPARK <span class=\"grad\">&amp; Web4 主権ループ</span>", "whitepaper.hero_desc": "4つの器官——<strong>Vault</strong>・<strong>Engine</strong>・<strong>Aether</strong>・<strong>Havix</strong>——が一つの閉じたループを成し、<strong>SPARK</strong> がそれを回す燃料です。E2EE プロトコルスタックは監査開放。本書は構築済みアーキテクチャ、設計されたトークンエコノミクス、そして二段階ローンチ(ホワイトリスト先行販売＋公開 LBP 型 IDO)を説明します。", "whitepaper.meta_1": "2026年8月", "whitepaper.meta_2": "4 リポジトリ · AGPL + APACHE", "whitepaper.meta_3": "先行販売ホワイトリスト受付中", "whitepaper.meta_4": "総供給 1,000T SPARK", "whitepaper.stat_dao": "DAO リザーブ——ガバナンス制御", "whitepaper.stat_tge": "TGE で流動（10% LP 含む）", "whitepaper.stat_cap": "ウォレット毎の先行販売上限", "whitepaper.stat_kb": "メッセージ 1KB 毎の SPARK", "whitepaper.abstract": "<b>要旨。</b>Web3 はユーザーにウォレットを与えましたが、SNS はサーバーに置いたままです。Web4 プロトタイプループはその溝を <mark class=\"key\">物理的隔離</mark> で埋めます:鍵を一切持たないオンライン SNS アプリ（<strong>Engine</strong>）、鍵を持ち決して接続しないオフライン金庫（<strong>Vault</strong>）、燃料備蓄を保有する SBT ガバナンスの議会（<strong>Aether</strong>）、そして生きた憲法の下で AI を認可するパラレル身分ネットワーク — マスター DID から派生し信用・価値の二重経済を走らせるもの（<strong>Havix</strong>）。<strong>$SPARK</strong> は唯一発行される資産で、アプリ内の表現を計量し、DAO リザーブに注ぎ、それらの間を流れます——ループの燃料であり、決して投票ではありません。本書は公開リポジトリに存在するアーキテクチャを記録し、次にトークンを規定します:効用、配分（10% 先行販売 / 20% IDO / 10% DEX 流動性 / 50% DAO リザーブ / 10% コミュニティインセンティブ）、二段階ローンチ、解放スケジュール、そしてローンチの公平とリザーブの主権を守る安全策です。", "whitepaper.toc1": "主権ループ", "whitepaper.toc2": "アーキテクチャ:隔離と身分", "whitepaper.toc3": "4つの器官", "whitepaper.toc4": "SPARK トークンエコノミクス", "whitepaper.toc4b": "二段階ローンチ", "whitepaper.toc5": "リザーブのガバナンス", "whitepaper.toc6": "TGE へのロードマップ", "whitepaper.toc7": "リスクと免責", "whitepaper.ch1": "主権ループ", "whitepaper.ch1_p1": "これは<b>ひとつのプロジェクトであって、製品のポートフォリオではありません</b>。各リポジトリは器官であり、器官は一つの血流——SPARK を共有します。ユーザーは Engine で話し、すべてのメッセージが燃料を燃やし、燃料は Aether リザーブに蓄えられ、リザーブは Havix の認可 AI によって流動に保たれ、Havix のネットワーク効果が Engine を生かし、Engine の需要が SPARK に実体のある裏付けを与えます。どの器官を切ってもループは止まります。", "whitepaper.th_organ": "器官", "whitepaper.th_metaphor": "比喩", "whitepaper.th_function": "ループ内の機能", "whitepaper.th_status": "実際の状態", "whitepaper.rv_mt": "金庫", "whitepaper.rv_fn": "すべての秘密鍵をオフライン保管。代理署名。鍵の移行は QR のみ", "whitepaper.rv_st": "v3.70.0 出荷済み", "whitepaper.re_mt": "アプリ", "whitepaper.re_fn": "主権ソーシャルメッセンジャー。純メモリ・E2E 暗号化。キロバイト単位で SPARK を消費", "whitepaper.re_st": "v3.64.7 出荷済み", "whitepaper.rs_mt": "燃料", "whitepaper.rs_fn": "表現を計量し、リザーブを潤し、リザーブと市場をつなぐ", "whitepaper.rs_st": "先行販売 + IDO", "whitepaper.ra_mt": "議会", "whitepaper.ra_fn": "SBT ガバナンスの DAO:三院制、ソウルバウンド階級、マルチシグ財務", "whitepaper.ra_st": "v3.6 · BSC · 監査完了 · メインネット待ち", "whitepaper.rh_mt": "身分のルート", "whitepaper.rh_fn": "マスター DID 由来のパラレル身分:4 コンテキスト派生、信用・価値の二重トラック、AI 認可面", "whitepaper.rh_st": "M10 クローズドベータ", "whitepaper.rig_mt": "脳", "whitepaper.rig_fn": "自らの身分で推論するノードレベル AI", "whitepaper.rig_st": "将来段階", "whitepaper.ch1_meta": "比喩はそのままアーキテクチャです:<mark class=\"key\">金庫はネットワークに触れない</mark>、<mark class=\"key\">議会はソウルバウンド SBT で統治する</mark>、<mark class=\"key\">脳は信頼ではなく認可される</mark>。以下はすべて公開コードに遡れます<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>。", "whitepaper.ch2": "アーキテクチャ:隔離と身分", "whitepaper.h21": "物理的隔離をセキュリティモデルに", "whitepaper.ch2_p1": "ループの根本的なセキュリティ判断は<b>ポリシーではなく物理による分離</b>です。Engine はオンラインでも秘密鍵を一切持たず、Vault は鍵を持ち、<mark class=\"key\">ネットワーク権限をまったく持たず</mark>に作られています——Android マニフェストは INTERNET 権限を宣言しないため、持ち出しは論理問題ではなく物理問題になります<sup><a href=\"#cite-3\">[3]</a></sup>。署名要求は署名保護付き IPC で Engine から Vault へ渡り、鍵マテリアルは端末間を暗号化 QR フレームとしてのみ移動します——カメラ対カメラ、エアギャップ強制<sup><a href=\"#cite-3\">[3]</a></sup>。", "whitepaper.ch2_p2": "信頼は監査可能です:Engine の <span class=\"mono\">core/</span> モジュール（プロトコル・暗号・IPC）は Vault のものと<b>バイト単位で同一</b>なので、両アプリは同じ公開ソースに対して検証します<sup><a href=\"#cite-1\">[1]</a></sup>。メッセージは ECDH 鍵合意と AES-256-GCM でエンドツーエンド暗号化され、リレーが見るのは封筒だけで平文は見えません<sup><a href=\"#cite-1\">[1]</a></sup>。", "whitepaper.h22": "一つの身分、四つの非連携コンテキスト", "whitepaper.ch2_p3": "Havix は単一のマスター鍵から HKDF で四つの文脈別サブ身分——公開・市場・トンネル・wiki 文脈——を導出します<sup><a href=\"#cite-6\">[6]</a></sup>。導出は暗号的に非連結:市場のペルソナは私人の通信と相関できません。これにより一人は同時に <mark class=\"key\">議会の市民、市場の取引者、チャットの私人</mark> になれます——三つのアカウントも、マッピングを持つプラットフォームも不要で。", "whitepaper.h23": "三つの平面、一つのループ", "whitepaper.ch2_li1": "<b>アプリケーション平面（オンライン）:</b>Engine——ユーザー向け、鍵なし、純メモリ。メッセージは RAM にのみ存在し、押収に対する攻撃面はほぼゼロです。", "whitepaper.ch2_li2": "<b>保管平面（オフライン）:</b>Vault——鍵ストアは生体認証の背後に封入され、導出は QR のみ。", "whitepaper.ch2_li3": "<b>調整平面（オフチェーン P2P）:</b>Havix——身分導出、評判/信用台帳、仲裁、そして AI を認可する憲章<sup><a href=\"#cite-6\">[6]</a></sup>。", "whitepaper.ch2_li4": "<b>決済平面（オンチェーン）:</b>BNB Smart Chain の Aether——ガバナンス、財務、タイムロック実行。譲渡可能なトークン供給ではなくソウルバウンド SBT 階級で統治されます<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>。", "whitepaper.ch2_p4": "Havix 自身のロードマップはこれを三層スタック——ネットワーク基盤(L0)、認知実行(L1, Germ)、オンチェーンガバナンス(L2, Aether)——として形式化し、4 コンテキスト DID が層間の暗号的隔離を強制します<sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.ch3": "4つの器官", "whitepaper.h31": "Vault — 金庫", "whitepaper.note31": "v3.70.0 · 出荷済み", "whitepaper.ch3_p1": "汎用のオフラインキーストアで、Engine の付属品ではありません:あらゆる準拠アプリのために鍵を保管できます。仕組み:ネットワーク権限なし。鍵は TEE に封入。生体認証ゲートの署名（利用可能なら StrongBox 準拠）。SPARK ウォレット保管——残高はセキュア世界内で共同署名された append-only の取引チェーンとして存在し、ウォレット引き継ぎは全残高を創世取引として新端末へ移します。新ハードウェアへの移行は QR のみで、秘密鍵は決してネットワークスタックに入りません<sup><a href=\"#cite-3\">[3]</a></sup>。v3.40 以降、Engine は署名保護された Binder IPC 直通チャネルで Vault に到達します——旧来のクロスアプリジャンプダイアログは廃止です<sup><a href=\"#cite-3\">[3]</a></sup>。", "whitepaper.ch3_p2": "ループ全体の市場参入点:純メモリアーキテクチャ、グループメッセージ、60 絵文字の表現経済、DID プロフィールを備えた主権ソーシャルメッセンジャーです<sup><a href=\"#cite-1\">[1]</a></sup>。経済エンジンはリポジトリで既に指定されています:<mark class=\"key\">1 キロバイトで 10 SPARK</mark> — 各メッセージは UTF-8 サイズで計量され切り上げ、1 メッセージ最低 10 SPARK。日次燃料補助 1,000 SPARK（暦日ごとに冪等、権威台帳が裁定、バインドされた Vault 身分でゲート）。ヘビーユーザーはウォレットからチャージします<sup><a href=\"#cite-2\">[2]</a></sup>。ウォレット残高は保存された数値ではなく、Vault 保有のウォレット鍵が共同署名した append-only 取引チェーンの導出です——例外なく、残高の変化はすべて署名取引です<sup><a href=\"#cite-2\">[2]</a></sup>。クライアント側の前払い控除が実装され、独立した spark-ledger サービスがサーバー側で残高を決済します<sup><a href=\"#cite-2\">[2]</a></sup>。", "whitepaper.h33": "Aether — 議会", "whitepaper.note33": "v3.6 · BSC · 監査完了 · メインネット待ち", "whitepaper.ch3_p3": "BNB Smart Chain 上の SBT ガバナンス DAO カーネルです。重みは買うのではなく稼ぎます:AetherRing が譲渡不可のソウルバウンド階級を 14 種発行し、三つの院（評議会・議会・長老）と市民レファレンダムが、長老拒否権付きの 7 段階提案ライフサイクルで互いにチェックします。財務は 3/5 の Safe マルチシグでタイムロック呼び出しを実行します<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>。意図的な設計的緊張関係:<mark class=\"key\">ガバナンスはソウルバウンド(SBT)だが、燃料は実在する発行済み資産</mark> — クジラは $SPARK を買えますが、$SPARK が買うのはメッセージであって票ではありません。ひとつ別格の契約があります:AetherDonation は<b>外部フィランソロフィーチャネル</b>（公共財への USDC チップ）であり、ループの経済とは独立です。", "whitepaper.h34": "Havix — 身分のルート", "whitepaper.note34": "検証済み · 待機", "whitepaper.ch3_p4": "ループの下層にある調整ネットワーク:８個のモジュール（身分・メッセージ型・信用・裏書き・wiki・仲裁・市場・s-node ランタイム）、1,174 の通過テスト（MVP 980＋検証実験 194、M10 監査ベースライン）、そして二回の監査プログラム——M9 は 15 件すべてをクローズ、M10 の深層監査はさらに 52 件（P0 5＋P1 15＋P2 32）を浮かび上がらせ、P0/P1 はクローズドベータ前に是正済み<sup><a href=\"#cite-6\">[6]</a></sup>。その憲章面こそが AI を魔法ではなく法的基盤に置きます:日常操作は領収書付きで自動実行され、<mark class=\"key\">レッドライン操作は物理的に人によるオンチェーン投票にルーティングされます</mark>。憲章ストアとインターセプタは M11 ワークストリームとして予定されています<sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.h35": "Germ — 脳、後日", "whitepaper.ch3_p5": "Germ はノードレベル AI 層です:Havix ネットワーク上で自らの 4 コンテキスト身分で推論する AI。意図的に後回しにされています——<mark class=\"key\">今日の市場参入は Engine</mark>。ループに大切にする価値のあるユーザーが集まったとき、脳はやって来ます。本書で Germ は経済が余地を確保しなければならない箇所（リザーブ AI、§5）にのみ登場します。", "whitepaper.ch4": "SPARK トークンエコノミクス", "whitepaper.h41": "効用:物理が裏にある燃料", "whitepaper.ch4_p1": "SPARK は<b>計量資産</b>です。Engine では 1 キロバイトごとに 10 SPARK かかります——メッセージサイズで計量、切り上げ、1 メッセージ最低 10——計量はサービス規約ではなくプロトコルにあります<sup><a href=\"#cite-2\">[2]</a></sup>。予算は実際の 100&nbsp;Mbps リレーベースラインから導出されます:テキスト封筒は最大 40&nbsp;KB、メディアは最大 48&nbsp;KB、128&nbsp;KB のハードフレーム上限、グループは 200 に制限<sup><a href=\"#cite-1\">[1]</a></sup>。表現するすべてのバイトに燃料がかかるため、スパムには限界費用がかかり、発言は自由であり続けます。", "whitepaper.ch4_li1": "<b>入手:</b>日次燃料補助（暦日ごとに 1,000 SPARK、冪等、バインドされた Vault 身分でゲート<sup><a href=\"#cite-2\">[2]</a></sup>）、ウォレットからのチャージ、または TGE 後の市場購入。", "whitepaper.ch4_li2": "<b>消費:</b>メッセージ燃料、グループとメディアの予算、SDK アプリの使用。", "whitepaper.ch4_li3": "<b>保有:</b>DAO 財務は SPARK を長期リザーブとして保有します——実際の使用からの需要がすべてのホルダーに均等に帰属します。", "whitepaper.ch4_note": "◇ 設計パラメータ（権利確定期間、LP ロック、手数料ルーティング、割り当て減衰）はこのドラフトの推奨既定値です。それぞれは先行販売開始前にガバナンスが確認または修正します。オンチェーン計量レート（1 KB = 10 SPARK、1 メッセージ最低 10、暦日ごとに 1,000 の燃料補助）は Engine の仕様で固定されています<sup><a href=\"#cite-2\">[2]</a></sup>。", "whitepaper.h42": "同じ資産の二つの段階——計量台帳、そして固定供給", "whitepaper.ch4_p2": "SPARK は意図的な二段階で出荷され、その順序こそが設計です。<b>フェーズ A — 計量台帳（本日稼働）:</b>出荷済みの Engine ソフトウェア内で、SPARK はオフチェーンのハッシュ連結台帳として存在します。各デバイスは Vault が共同署名する燃料補助により<b>暦日ごとに 1,000</b> を鋳造します——アンチシビル防御は本番運用中:TEE/DRM のデバイスアンカー、リレー側の非連結デバイスハッシュの日次重複排除、署名ゲートで強制される金額ホワイトリスト。フェーズ A の残高は<mark class=\"key\">譲渡不可・取引不可・兌換不可</mark> — 今日それは割当てであり、有価証券ではありません。", "whitepaper.ch4_p3": "<b>フェーズ B — TGE マッピング（計画中）:</b>固定の <b>1,000T 供給</b>が TGE で発効します。初期供給は §4.3 の先行販売・IDO・流動性・リザーブの各トランシェと、フェーズ A 残高のスナップショットベースのマッピング（コミュニティインセンティブ・トランシェへ）を組み合わせます——具体的な換算パラメータは草案既定値 ◇ で、先行販売開始前にガバナンスが確認します。TGE 後は SPARK は自由に流通し、<b>開放された USDC 等のステーブルコインペアを含みます</b>。変換チャネルは今日、意図的に未構築です:デバイスアンカー、日次重複排除、金額ホワイトリストは、守るべき金庫ができる<i>前</i>に存在しなければならず、兌換が始まる日にはこれらの防御は割当て衛生から金庫の門へ昇格します。", "whitepaper.h43": "供給と配分", "whitepaper.ch4_p4": "総供給は <b>1,000T SPARK（1,000,000,000,000,000 — 千兆）</b>に固定されています。配分は 10 / 20 / 10 / 50 / 10 の分割に従います:先行販売・IDO・DEX 流動性・DAO リザーブ・コミュニティインセンティブ。<mark class=\"key\">チームトランシェも、インサイダー配分も、マーケティングトランシェもありません</mark> — チームの上昇余地は DAO と共有する 50% リザーブで、公開ガバナンスを通してのみ解放され、憲章により年間リザーブの ≤5% に上限が課されます。", "whitepaper.fig1": "図 1 — TGE 時点の SPARK 配分（精緻化:10 スライス、5 トランシェ）", "whitepaper.fig1_sub": "総供給 1,000T（1,000,000,000,000,000）。先行販売は TGE で 2.5%＋7.5% 権利確定に分割。IDO は TGE で 5%＋15% 権利確定（両トランシェとも TGE 時 25%、その後 9 ヶ月リニア）。リザーブの下位分割は憲章で制約された草案既定値 ◇ で、放出は ≤5%/年が上限——リザーブ自体にはカレンダー解放がありません。", "whitepaper.th_tranche": "トランシェ", "whitepaper.th_share": "シェア", "whitepaper.th_amount": "数量", "whitepaper.th_unlock": "解放", "vault.foot_home": "ホーム", "whitepaper.ch4b": "デュアルトラック・ローンチ", "whitepaper.h44": "フェーズ 1 — 先行販売 (10%)", "whitepaper.h45": "フェーズ 2 — IDO (20%)", "whitepaper.h46": "流動性と DEX (10%)", "whitepaper.h47": "解放スケジュール", "whitepaper.h48": "保護とコンプライアンス", "whitepaper.h32": "Engine — アプリ", "whitepaper.note32": "v3.64.7 · 出荷済み", "whitepaper.ch5": "リザーブのガバナンス", "whitepaper.ch6": "TGE へのロードマップ", "whitepaper.ch7": "リスクと免責事項", "whitepaper.fig2": "図 2 — TGE 後の流通供給", "whitepaper.m1": "先行販売——ホワイトリスト · $500 上限", "whitepaper.m2": "IDO — LBP · 3〜7 日", "whitepaper.m3": "流動性——TGE でシード", "whitepaper.m4": "コミュニティインセンティブ——紹介と有効化", "whitepaper.m5": "DAO リザーブ——ガバナンス制御 · ≤5%/年", "whitepaper.tl_now_t": "稼働中のループ", "whitepaper.tltge_t": "トークン生成イベント", "whitepaper.tl01_t": "ホワイトリストとパラメータ確定", "whitepaper.tl02_t": "先行販売ウィンドウ", "whitepaper.tl03_t": "LBP での IDO", "whitepaper.tl9_t": "フロート完了 · DAO がリザーブを引き継ぐ", "whitepaper.tll1_t": "Germ、後日", "whitepaper.src": "出典", "whitepaper.src6": "eneatlnc-cell、Havix リポジトリ——パラレル身分ネットワーク:8 モジュール、1,174 テスト（M10 監査ベースライン）、15 件の監査指摘をクローズ。", "whitepaper.src1": "eneatlnc-cell、Engine 3.0 — E2EE プロトコルスタックの公開監査版（core-crypto、core-protocol、core-ipc;AGPL-3.0）。", "whitepaper.src2": "Engine、SparkEconomy エンジニアリング記録（内部）——1 KB = 10 SPARK（1 メッセージ最低 10）、暦日ごとの 1,000 日次燃料補助、署名取引 SPARK ウォレット（v3.37+）、ウォレットチャージ、spark-ledger サービス計画。", "whitepaper.src3": "eneatlnc-cell、Engine 3.0 — core-ipc:オフラインキーストアの背後にある Engine↔Vault 署名コントラクト（ネットワーク権限なし、生体認証署名、QR 移行）。", "whitepaper.src4": "eneatlnc-cell、Aether リポジトリ——SBT ガバナンス DAO カーネル:AetherRing、Governance、Election、Safe 財務。", "whitepaper.src5": "Aether、docs/TECHNICAL_WHITEPAPER.md — 三院制、7 段階ライフサイクル、長老拒否権、院/市民のバランス。", "whitepaper.src7": "Havix、NEXT-STEPS.md — L0/L1/L2 三層スタック、M11 憲章ストアとレッドライン・インターセプタ計画。", "whitepaper.foot_copy": "© <span class=\"yr\">2026</span> SparkLoop · ホワイトペーパー v1.0 ドラフト", "whitepaper.foot_cta": "先行販売のホワイトリストに参加", "whitepaper.tr_presale_amt": "100T", "whitepaper.tr_presale_t": "先行販売——ホワイトリスト", "whitepaper.tr_tge_amt": "25T", "whitepaper.tr_tge_t": "└ TGE 解放", "whitepaper.tr_tge_un": "TGE で流動化", "whitepaper.tr_9m_amt": "75T", "whitepaper.tr_9m_t": "└ 9ヶ月ベスト", "whitepaper.tr_9m_un": "リニア、1〜9 ヶ月", "whitepaper.tr_a_un": "TGE 時 25% ◇、その後 9 ヶ月リニア ◇", "whitepaper.tr_b_un": "TGE 時 25% ◇、その後 9 ヶ月リニア ◇", "whitepaper.tr_ido_amt": "200T", "whitepaper.tr_ido_t": "IDO — 公開 LBP ラウンド", "whitepaper.tr_tge2_amt": "50T", "whitepaper.tr_tge2_t": "└ TGE 解放", "whitepaper.tr_9m2_amt": "150T", "whitepaper.tr_9m2_t": "└ 9ヶ月ベスト", "whitepaper.tr_dex_amt": "100T", "whitepaper.tr_dex_t": "DEX 流動性", "whitepaper.tr_dex_un": "TGE でプールにシード · LP ロック 12 ヶ月 ◇", "whitepaper.tr_dao_amt": "500T", "whitepaper.tr_dao_t": "DAO リザーブ", "whitepaper.tr_dao_un": "カレンダーなし——Aether 提案のみで解放 · 憲章上限 ≤5%/年", "whitepaper.tr_comm_amt": "100T", "whitepaper.tr_comm_t": "コミュニティインセンティブ", "whitepaper.tr_comm_un": "紹介ボーナス＋活性化助成 · プログラムごとに精算", "whitepaper.tr_fuel_amt": "150T", "whitepaper.tr_fuel_t": "└ Engine 燃料補助", "whitepaper.tr_fuel_un": "憲章既定 ◇ — 補助エポック", "whitepaper.tr_relay_amt": "100T", "whitepaper.tr_relay_t": "└ リレーとインフラ", "whitepaper.tr_relay_un": "憲章既定 ◇ — リレー、s-node", "whitepaper.tr_eco_amt": "150T", "whitepaper.tr_eco_t": "└ エコシステム助成", "whitepaper.tr_eco_un": "憲章既定 ◇ — アプリ、リレー、ツール", "whitepaper.tr_ai_amt": "100T", "whitepaper.tr_ai_t": "└ AI 流動性と基金", "whitepaper.tr_ai_un": "憲章既定 ◇ — AI 範囲", "whitepaper.ch4b_p1": "ローンチの要は<b>先行販売と IDO の並行、異なるテンポ</b>：先行販売は中核コミュニティを、IDO は一般市場を対象にします。<mark class=\"key\">先行販売が基盤を作り、IDO が市場を開く。</mark>", "whitepaper.ch4b_li1": "<b>対象:</b>初期コアコントリビューターと活発なコミュニティメンバーのみ。ウォレットアドレスは事前にホワイトリスト化され、開始時刻は最初にリストへ通知されます。", "whitepaper.ch4b_li2": "<b>アンチ・ホエール:</b>厳格な <mark class=\"key\">ウォレットごとの $500 上限</mark>。", "whitepaper.ch4b_li3": "<b>条件:</b>固定の低価格で USDT や BNB で支払います。25% は TGE で解放、残りは 9 ヶ月でリニアに権利確定 ◇。", "whitepaper.ch4b_li4": "<b>実行:</b>ウィンドウが開くと、ホワイトリスト化されたウォレットが公式サイトで接続し、上限内で申し込みます。", "whitepaper.ch4b2_li1": "<b>プラットフォーム:</b>Fjord Foundry 級の LBP ランチパッド——価格は高く始まり需要が追いつくまで減衰します。<mark class=\"key\">スナイピングの優位を排除</mark>し、ホワイトリストも先着ブロックの優位もありません。", "whitepaper.ch4b2_li2": "<b>パラメータ:</b>プールへの資金投入前にトークンアドレスを三重確認（不可逆）。支払いは USDT や BNB。3〜7 日の窓口。ウォレットごとの最小・最大上限。開始価格は先行販売価格より高く。", "whitepaper.ch4b2_li3": "<b>配分:</b>各ウォレットの割り当て 25% は TGE で請求可能、残りは 9 ヶ月でリニアに権利確定 ◇。収益は直接プロジェクトのマルチシグへ。", "whitepaper.ch4b2_li4": "<b>会計:</b>ウィンドウ終了後、申込リストと金額を照合して公開してから配分します。", "whitepaper.ch4b3_note": "アドレスはデプロイの瞬間に Spark ページで公開されます。それまでは、SPARK を名乗るアドレスはすべて詐欺です。", "whitepaper.ch4b3_p1": "TGE で流動性トランシェが DEX プールにシードされ、BNB とペアになります。SPARK は BNB チェーン上の BEP-20 トークンとして発行されるのが推奨 ◇ — 両ラウンドの USDT/BNB 決済レールに一致 — Aether 財務とガバナンスは同じ BNB Smart Chain にデプロイされ<sup><a href=\"#cite-4\">[4]</a></sup>、リザーブ操作はクロスチェーンブリッジなしでネイティブに決済されます<sup><a href=\"#cite-5\">[5]</a></sup>。", "whitepaper.ch4b4_p1": "構造的な約束は<mark class=\"key\">厳格なフロート上限</mark>:カレンダーは 40%（先行販売＋IDO＋LP）を超えて解放できません。10% のインセンティブ・トランシェは検証済みの紹介と有効化のみに支払われ、50% のリザーブは公開で拒否可能な提案を通してのみ動き、憲章は解放を<b>年間リザーブの ≤5%</b> に制限します。初期購入者は最大フロートを正確に知っています。", "whitepaper.ch5_p1": "50% のリザーブは財務ウォレットではなく<b>憲法上の対象物</b>です。保管は 3/5 の Safe マルチシグに置かれ、移動には Aether の 7 段階ライフサイクルを通した提案、長老拒否権ウィンドウの通過、タイムロック実行が必要です<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>。そのプロセスでの重みはソウルバウンドで稼ぐものです——買うことも譲渡もできない 14 の AetherRing 階級<sup><a href=\"#cite-4\">[4]</a></sup>。", "whitepaper.ch5_p2": "リザーブの用途は憲章で制限されます:Engine 燃料のユーザー補助エポック、リレーとインフラ資金、エコシステム助成、そして——Germ が存在すれば——ハードな制限内での認可 AI による流動性管理で、レッドラインは人間の投票へ戻ります<sup><a href=\"#cite-6\">[6]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>。憲章はさらに<mark class=\"key\">年間リザーブの ≤5% というリリース率上限</mark>を定めます——裁量ではなく計算可能な約束:完全に掌握された財務でも、リザーブを年 20 分の 1 より速く使い切れません。バランス設計は意図的です:<mark class=\"key\">院と市民がそれぞれおよそ半分の投票権を持つ</mark>ため、機関も群衆も単独でリザーブを使えません<sup><a href=\"#cite-5\">[5]</a></sup>。", "whitepaper.ch7_disc": "<b>免責事項。</b>本書はオープンソースソフトウェアプロジェクトとその燃料資産を説明します。投資助言でも、有価証券の販売申し出でも、リターンの約束でもありません。◇ と付いたパラメータは草案既定値で、ローンチ前に変更され得ます。このループに「私を信じて」式のマーケティングはありません:リポジトリを読んでください。", "whitepaper.ch7_li1": "<b>実行リスク:</b>Aether メインネット導入、M11 憲章ストア、spark-ledger サービスは TGE シーケンスが依存する未完成コンポーネントです<sup><a href=\"#cite-2\">[2]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.ch7_li2": "<b>クロスチェーンリスク:</b>設計で軽減—SPARK と Aether ガバナンス/財務は同じ BNB Smart Chain ◇ にデプロイされ、リザーブ操作はブリッジ依存なしでネイティブに決済されます。", "whitepaper.ch7_li3": "<b>市場リスク:</b>LBP は価格を正直に見つけ出します——つまり下方にも発見します。固定の低い先行販売価格は初期の信頼を補償しますが、リターンを保証しません。", "whitepaper.ch7_li4": "<b>規制リスク:</b>トークンランチは異なる規制に直面し、管轄により制限がかかる場合があります。弁護士審査は形式的なものではなく前提条件です。", "whitepaper.ch7_li5": "<b>スマートコントラクトリスク:</b>監査はリスクを減らしますが決して消しません。公式サイトで公開されたアドレスとだけやり取りしてください。", "whitepaper.fig2_sub": "流動のフロート:TGE で 17.5%（2.5% 先行販売＋5% IDO＋10% LP）、両トランシェの権利確定に伴い毎月 2.5% 上昇し、9 か月目に 40% のカレンダー上限へ。10% のインセンティブ・トランシェはプログラムごとに精算され、残り 50% はガバナンスのみで動き、憲章上限は ≤5%/年。", "whitepaper.tl_now_d": "Engine v3.64.7 と Vault v3.70.0 が出荷されました——Binder IPC 直通チャネルと署名取引 SPARK ウォレットが稼働し、両アプリのリリースは R8 難読化で強化され、日次燃料補助はリレー側で非連結のデバイス・日ハッシュにより重複排除されます。Havix は 15 件の監査指摘クローズ後にクローズドベータへ。BSC の Aether v3.6（監査修正クローズ）はメインネット配備待ち<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>。先行販売のホワイトリストは受付中です。", "whitepaper.tl01_d": "ウォレットアドレスを収集。先行販売価格、IDO の境界、権利確定と LP ロックのパラメータを確認。契約は監査済みでアドレスを公開。", "whitepaper.tl02_d": "ホワイトリストのウォレットが固定の低価格で $500 上限内 USDT/BNB で申し込む。", "whitepaper.tl03_d": "3〜7 日の公開ラウンド。価格は自己発見。終了時に精算を公開。", "whitepaper.tl9_d": "先行販売と IDO の権利確定が完了し、カレンダーのフロートは 40% の上限へ。Aether メインネットガバナンスがリザーブ・マンデートを全面的に引き継ぎ、解放は憲章上限 ≤5%/年で制限されます。", "whitepaper.tltge_d": "先行販売 25%＋IDO 25% の初期配分がウォレットへ。10% の流動性トランシェが DEX プールにシード。spark-ledger が Engine 決済で稼働<sup><a href=\"#cite-2\">[2]</a></sup>。", "whitepaper.tll1_d": "ノードレベル AI が憲章のもとネットワークに加わります——脳は、すでに鼓動するループを世話するためにやって来ます<sup><a href=\"#cite-7\">[7]</a></sup>。", "whitepaper.ch4b5_li1": "<b>セキュリティ:</b>資金を受け入れる前に、トークン・先行販売・LBP の各コントラクトは公認企業の監査を受けなければなりません。報告はアドレスと共に公開されます。", "whitepaper.ch4b5_li2": "<b>透明性:</b>先行販売と IDO のコントラクトアドレスと規則は各ウィンドウ開始前に発表され、購入精算は TGE 配分前に公開されます。", "whitepaper.ch4b5_li3": "<b>アンチボット:</b>LBP の価格減衰がスナイピングを退けます。ウォレットごとの上限（先行販売 $500、IDO 最小/最大）が集中を制限。先行販売コントラクトには動的スリッページ境界を適用できる場合があります ◇。", "whitepaper.ch4b5_li4": "<b>法律:</b>対象管轄について法的助言者による審査が行われています。必要な場合、参加は制限されることがあります。ここに証券の申し出はありません。"},
  ko: {"vault.nav_home": "홈", "vault.nav_rewards": "보상", "vault.chip": "오프라인 · 네트워크 분리 · 주권", "vault.h1_a": "안전한 금고,", "vault.h1_grad": "절대 네트워크에 말하지 않습니다", "vault.hero_desc": "<strong>Vault</strong>는 Engine 계열 앱을 위한 범용 오프라인 금고입니다. <strong>인터넷 권한 제로</strong>로 개인키와 로그인 서명을 저장하고, 휴대폰의 보안 실리콘 안에 봉인하며, 지문으로 서명하고, 오직 빛——QR 코드——을 통해서만 키를 새 하드웨어로 옮깁니다. \"연결하지 않겠다고 약속\"이 아니라 <strong>연결할 수 없습니다</strong>.", "vault.btn_ceremony": "▶ 서명 의례 체험하기", "vault.btn_migration": "⟳ 키 마이그레이션", "vault.btn_audit": "↗ 암호 계층 감사", "vault.stat_internet": "매니페스트의 INTERNET 권한", "vault.stat_tee": "하드웨어 봉인 키", "vault.stat_wallet": "지갑 보관 및 인계", "vault.stat_qr": "키의 유일한 출구", "vault.tag_demo": "데모 영화에서 재현", "vault.title_demo": "금고를 직접 만져보세요", "vault.sub_demo": "왼쪽은 실제 Vault 앱: SPARK 지갑 뷰——잔액은 서명된 거래의 합일 뿐이며, 하단 바 한 번 탭으로 인계가 가능합니다. 가운데는 Vault가 지키는 모든 앱 키를 나열하는 상태 페이지——<b>Sign</b>을 누르면 생체 인증 의례를 볼 수 있습니다. 오른쪽은 휴대폰이 자신의 격리 상태에 대해 보고하는 내용입니다.", "vault.wallet_title": "SPARK 지갑", "vault.wallet_sub": "Vault 보관 · 서명된 거래 체인", "vault.wallet_balsub": "잔액 = Σ 서명된 거래", "vault.wallet_handover": "⇄ 지갑 인계", "vault.wallet_keys": "키: 3", "vault.vs_title": "보호 중인 키", "vault.vs_fingerprint": "지문", "vault.vs_algorithm": "알고리즘", "vault.vs_sealed": "봉인됨", "vault.vs_sealed_val": "Keystore TEE · AES-256-GCM", "vault.vs_lastreq": "최근 요청", "vault.vs_waiting": "대기 중…", "vault.vs_sign": "Engine 요청 서명", "vault.vs_migrate": "⟳ 새 기기로 마이그레이션", "vault.bio_touch": "센서를 터치하세요", "vault.bio_title": "BiometricPrompt", "vault.bio_desc": "키는 TEE 밖으로 나가지 않습니다——보안 하드웨어 안에서 서명합니다.", "vault.console_head": "adb shell — 네트워크 분리 자가 점검", "vault.sim_caption": "<b>위의 모든 이벤트는 로컬입니다.</b> 콘솔에는 네트워크에서 보고할 내용이 없습니다——네트워크가 존재하지 않기 때문입니다.", "vault.tag_guards": "무엇을 지키나", "vault.title_guards_a": "단 하나의 임무:", "vault.title_guards_grad": "모든 주권 앱의 금고", "vault.sub_guards": "Vault는 설계상 앱 독립적입니다. Engine처럼——온라인 생활과 오프라인 키를 함께 원하는 앱——이라면 그 정체성을 금고에 위임할 수 있습니다.", "vault.card1_t": "앱 개인키", "vault.card1_d": "Engine 같은 앱이 생성한 ECDSA P-256 신원으로, 도착하는 순간 봉인됩니다.", "vault.card2_t": "로그인 및 지갑 서명", "vault.card2_d": "챌린지-리스폰스 로그인 코드와 SPARK 지갑 거래——금고 안에서 서명되며 결코 온라인에 저장되지 않습니다. 모든 잔액 변동은 추가 전용 체인의 서명된 거래입니다.", "vault.card3_t": "기기 마이그레이션 바인딩", "vault.card3_d": "서명된 재바인딩 기록으로 클라우드 백업 없이 신원을 새 하드웨어로 옮깁니다.", "vault.card4_t": "지문 디렉터리", "vault.card4_d": "보호 중인 모든 키의 로컬 레지스트리: 지문과 봉인 상태를 한눈에 볼 수 있습니다.", "vault.card5_t": "그 외에는 없습니다", "vault.card5_d": "브라우징도, 동기화도, 광고도, 텔레메트리도 없습니다. 스크린이 있는 금고이지 스마트폰 앱이 아닙니다.", "vault.card6_t": "생체 인증 전용 잠금 해제", "vault.card6_d": "모든 잠금 해제는 ±120초 신선도 창과 함께 BiometricPrompt를 통과합니다——시계 기반 재생 방지.", "vault.tag_ceremony": "온라인 앱이 오프라인에서 서명하는 방법", "vault.title_ceremony_a": "키가 서명합니다.", "vault.title_ceremony_grad": "키는 결코 떠나지 않습니다.", "vault.pl1": "Engine에 서명 필요", "vault.pl2": "IPC 요청 + 챌린지", "vault.pl3": "BiometricPrompt", "vault.pl4": "TEE 해제 및 서명", "vault.pl5": "서명된 콜백", "vault.pl6": "Engine이 서명 + Δt&lt;120s 검증", "vault.co_tag": "±120초 창이 중요한 이유", "vault.co_text": "콜백 서명은 <b>sessionId ‖ status ‖ timestamp</b>를 포함합니다. 콜백이 도난당해도 몇 분 후에 재생할 수 없습니다——시계가 증명의 일부이기 때문입니다. 릴레이는 키를 보지 못하고, Engine도 키를 보유하지 않습니다.<b>오직 TEE만 보유합니다.</b>", "vault.tag_migration": "새 폰, 같은 신원", "vault.title_mig_a": "빛줄기를 통해", "vault.title_mig_grad": "이사하기", "vault.sub_migration": "개인키는 결코 클라우드에 맡겨서는 안 되는 유일한 것입니다. 하드웨어가 바뀌면 Vault가 화면에서 화면으로 신원을 옮깁니다——아래에서 단계별로 확인하세요.", "vault.migprev": "이전", "vault.mignext": "다음", "vault.flag_t": "FLAG_SECURE", "vault.flag_d": "QR 화면은 스크린샷과 화면 녹화를 검게 만듭니다. 남은 공격은 어깨너머 훔쳐보기뿐입니다.", "vault.payload_t": "암호화된 페이로드", "vault.payload_d": "바인드 URI는 암호화된 세션 페이로드를 담습니다——원본 개인키는 결코 URI에 나타나지 않습니다.", "vault.burn_t": "바인딩 후 소각", "vault.burn_d": "Engine는 convertBoundToPublicKeyOnly()를 호출합니다——Vault가 인계하는 순간 개인키 사본이 제거됩니다.", "vault.title_compare": "오늘 밤 키는 어디서 잠자나요?", "vault.th_storage": "저장 모델", "vault.th_network": "네트워크 도달성", "vault.th_extraction": "추출 위험", "vault.th_migration": "마이그레이션 경로", "vault.tr_ext_t": "브라우저 확장 지갑", "vault.tr_ext_reach": "항상 온라인", "vault.tr_ext_risk": "높음 — 메모리 및 디스크 읽기 가능", "vault.tr_ext_mig": "종이에 적은 시드 문구", "vault.tr_hot_t": "핫 서버 / 수탁 보관", "vault.tr_hot_reach": "연중무휴 공격 표면", "vault.tr_hot_risk": "시스템적 — 한 번의 침해로 모든 키 유출", "vault.tr_hot_mig": "운영자를 신뢰", "vault.tr_cloud_t": "클라우드 키 백업", "vault.tr_cloud_reach": "설계상 동기화", "vault.tr_cloud_risk": "계정 침해 = 키 침해", "vault.tr_cloud_mig": "재다운로드", "vault.tr_vault_reach": "INTERNET 권한 없음", "vault.tr_vault_risk": "TEE 실리콘 + 생체 인증 게이트", "vault.tr_vault_mig": "QR 빛 채널, 서명된 재바인딩", "vault.co2_tag": "약속이 아닌 물리", "vault.co2_text": "표의 모든 행은 누군가가 제대로 행동하기를 기대합니다. Vault의 격리는 Android 매니페스트에 선언되고 OS가 강제합니다——<b>패킷을 보낼 수 없으므로 약속 자체가 필요 없습니다.</b>", "vault.foot_desc": "eneatlnc-cell Loop에 대한 독립적 해석입니다. E2EE 프로토콜 스택은 감사용으로 공개되어 있으며, 모든 주장은 코드와 백서로 거슬러 올라갑니다.", "vault.foot_layers": "레이어", "vault.foot_engine": "주권 소셜", "vault.foot_vault": "오프라인 보관", "vault.foot_havix": "L0 · 병렬 신원", "vault.foot_spark": "연료", "vault.foot_rewards": "추천 정책", "vault.foot_loop": "Web4 루프", "vault.foot_repos": "저장소", "vault.foot_bottom": "키 오프라인 · SBT 거버넌스 · $SPARK 연료 · AI 인가", "vault.log_settle_pre": "계량 배치가 TEE 안에서 공동 서명됨 → tx #", "vault.log_settle_suf": " 체인에 추가됨 · 잔액 = Σ 서명된 거래", "vault.log_handover": "인계 증서 서명됨 · 전체 잔액이 genesis 거래로 새 기기로 이전", "vault.log_bio_dismiss": "생체 인증 프롬프트 닫힘", "vault.log_ipc_pre": "IPC 서명 요청 수신 · challenge=0x", "vault.log_ipc_suf": " · 생체 인증 대기 중", "vault.sig_result": "✓ 서명됨 · ECDSA P-256 · TEE", "vault.log_bio_ok": "생체 인증 ✓ → TEE 안에서 키 해제 → 보안 세계에서 서명 → 재봉인", "vault.log_callback": "콜백 검증: sig(sessionId‖status‖ts) ✓ · Δt &lt; 120s ✓", "vault.mig1_title": "새 기기가 새 키 쌍 생성", "vault.mig1_desc": "새 폰은 Engine 안에서 자신의 ECDSA P-256 신원을 생성합니다. 어떤 것도 무선으로 가져오지 않습니다——절대로.", "vault.mig2_title": "기존 Vault가 마이그레이션 바인딩 내보냄", "vault.mig2_desc": "기존 Vault는 QR 프레임에 인증을 봉인합니다. FLAG_SECURE가 스크린샷을 검게 만들고, 키 자체는 결코 TEE를 떠나지 않습니다.", "vault.mig3_title": "새 Vault 스캔——광학 채널 전용", "vault.mig3_desc": "ML Kit가 카메라를 통해 프레임을 읽습니다. 관여하는 유일한 네트워크는 빛입니다.", "vault.mig4_title": "신원이 새 키에 재바인딩", "vault.mig4_desc": "서명된 재바인딩 콜백이 DID를 새 기기의 공개키로 이전합니다. 연락처가 새 지문을 자동으로 검증합니다.", "vault.mig5_title": "SPARK 보관도 인계됨", "vault.mig5_desc": "기존 Vault가 전체 잔액으로 체인을 종료하는 인계 증서에 서명하고, 새 Vault가 검증 후 genesis 거래로 원장을 이어받습니다——서명되지 않은 잔액은 존재하지 않습니다.", "vault.mig6_title": "기존 복사본 소각, 잔여물 제로", "vault.mig6_desc": "기존 Vault가 제로 덮어쓰기로 봉인 키를 삭제합니다. 마이그레이션 완료——어떤 키도 인터넷에 닿지 않았습니다.", "vault.log_boot1": "AndroidManifest: uses-permission INTERNET → <b>없음</b> ✓", "vault.log_boot2": "네트워크 스택: 도달 불가 · 소켓: 없음 · 텔레메트리: 없음", "vault.log_boot3": "Keystore TEE 활성 · 키 봉인됨(AES-256-GCM) · 생체 인증 준비됨", "vault.log_boot4": "SPARK 지갑 체인 준비됨 · HWM 재생 방지 · 인계 준비 완료", "whitepaper.nav_home": "홈", "whitepaper.nav_rewards": "보상", "whitepaper.kicker": "// 프로젝트 백서", "whitepaper.chip": "버전 1.0 · 초안", "whitepaper.h1": "SPARK <span class=\"grad\">&amp; Web4 주권 루프</span>", "whitepaper.hero_desc": "네 가지 기관——<strong>Vault</strong>, <strong>Engine</strong>, <strong>Aether</strong>, <strong>Havix</strong>——이 하나의 닫힌 루프를 이루고, <strong>SPARK</strong>가 그것을 돌게 하는 연료입니다. E2EE 프로토콜 스택은 감사용으로 공개됩니다. 이 문서는 구축된 아키텍처, 설계된 토큰 경제, 그리고 이중 트랙 런칭(화이트리스트 사전판매 후 공개 LBP 기반 IDO)을 설명합니다.", "whitepaper.meta_1": "2026년 8월", "whitepaper.meta_2": "저장소 4개 · AGPL + APACHE", "whitepaper.meta_3": "사전판매 화이트리스트 오픈", "whitepaper.meta_4": "총공급 1,000T SPARK", "whitepaper.stat_dao": "DAO 예비금——거버넌스 게이트", "whitepaper.stat_tge": "TGE 시 유동 (LP 10% 포함)", "whitepaper.stat_cap": "지갑당 사전판매 상한", "whitepaper.stat_kb": "메시지 킬로바이트당 SPARK", "whitepaper.abstract": "<b>요약.</b> Web3는 사용자에게 지갑을 주었지만 소셜 생활은 서버에 남겨뒀습니다. Web4 프로토타입 루프는 <mark class=\"key\">물리적 격리</mark>로 그 간극을 메웁니다: 키를 전혀 보유하지 않는 온라인 소셜 앱(<strong>Engine</strong>), 키를 보유하고 절대 연결하지 않는 오프라인 금고(<strong>Vault</strong>), SBT로 통치되고 연료 예비금을 관리하는 의회(<strong>Aether</strong>), 그리고 살아있는 헌장 아래 AI를 인가하는 병렬 신원 네트워크(<strong>Havix</strong>)——마스터 DID에서 파생되어 신용-가치 이중 경제를 운영합니다. <strong>$SPARK</strong>는 유일하게 발행된 자산으로, 앱 내 표현을 계량하고 DAO 예비금에 주입하며 그 사이를 흐릅니다——루프의 연료이지 결코 투표가 아닙니다. 이 백서는 공개 저장소에 존재하는 아키텍처를 기록한 뒤 토큰을 규정합니다: 효용, 배분(사전판매 10% / IDO 20% / DEX 유동성 10% / DAO 예비금 50% / 커뮤니티 인센티브 10%), 이단계 런칭, 잠금 해제 일정, 그리고 공정한 런칭과 주권적 예비금을 지키는 안전장치.", "whitepaper.toc1": "주권 루프", "whitepaper.toc2": "아키텍처: 격리와 신원", "whitepaper.toc3": "네 가지 기관", "whitepaper.toc4": "SPARK 토큰 경제", "whitepaper.toc4b": "이중 트랙 런칭", "whitepaper.toc5": "예비금 거버넌스", "whitepaper.toc6": "TGE까지의 로드맵", "whitepaper.toc7": "위험 및 면책", "whitepaper.ch1": "주권 루프", "whitepaper.ch1_p1": "이것은 <b>하나의 프로젝트이지 제품 포트폴리오가 아닙니다</b>. 각 저장소는 기관이며, 기관은 하나의 혈류——SPARK를 공유합니다. 사용자는 Engine에서 채팅하고, 모든 메시지는 연료를 소모하며, 연료는 Aether 예비금에 적립되고, 예비금은 Havix의 인가된 AI가 유동성으로 유지하며, Havix의 네트워크 효과가 Engine을 살리고, Engine의 수요가 SPARK에 실물 뒷받침을 줍니다. 어떤 기관을 끊어도 루프는 멈춥니다.", "whitepaper.th_organ": "기관", "whitepaper.th_metaphor": "은유", "whitepaper.th_function": "루프에서의 기능", "whitepaper.th_status": "실제 상태", "whitepaper.rv_mt": "금고", "whitepaper.rv_fn": "모든 개인키를 오프라인으로 보관하고 대리 서명하며, QR로만 키를 이전", "whitepaper.rv_st": "v3.70.0 출시됨", "whitepaper.re_mt": "앱", "whitepaper.re_fn": "주권 소셜 메신저. 순수 메모리, E2E 암호화. KB 단위로 SPARK 소모", "whitepaper.re_st": "v3.64.7 출시됨", "whitepaper.rs_mt": "연료", "whitepaper.rs_fn": "표현을 계량하고 예비금을 적립하며 예비금과 시장을 잇는다", "whitepaper.rs_st": "사전판매 + IDO", "whitepaper.ra_mt": "의회", "whitepaper.ra_fn": "SBT 거버넌스 DAO: 세 개의 회의체, 소울바운드 직급, 멀티시그 재고", "whitepaper.ra_st": "v3.6 · BSC · 감사 종료 · 메인넷 대기", "whitepaper.rh_mt": "신원 루트", "whitepaper.rh_fn": "마스터 DID 파생 병렬 신원: 4컨텍스트 파생, 신용-가치 이중 트랙, AI 헌장 평면", "whitepaper.rh_st": "M10 클로즈드 베타", "whitepaper.rig_mt": "두뇌", "whitepaper.rig_fn": "자신의 신원으로 추론하는 노드 레벨 AI", "whitepaper.rig_st": "미래 단계", "whitepaper.ch1_meta": "은유가 곧 아키텍처입니다: <mark class=\"key\">금고는 네트워크에 닿지 않고</mark>, <mark class=\"key\">의회는 소울바운드 SBT로 통치하며</mark>, <mark class=\"key\">두뇌는 신뢰가 아니라 인가를 받습니다</mark>. 아래의 모든 것은 공개 코드로 추적할 수 있습니다<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>.", "whitepaper.ch2": "아키텍처: 격리와 신원", "whitepaper.h21": "물리적 격리를 보안 모델로", "whitepaper.ch2_p1": "루프의 근본 보안 결정은 <b>정책이 아닌 물리적 분리</b>입니다. Engine은 온라인으로 실행되지만 개인키를 전혀 보유하지 않고, Vault는 키를 보유하며 <mark class=\"key\">전혀 네트워크 권한 없이</mark> 구축됩니다——Android 매니페스트가 INTERNET 권한을 선언하지 않기 때문에 유출은 논리적 문제가 아닌 물리적 문제가 됩니다<sup><a href=\"#cite-3\">[3]</a></sup>. 서명 요청은 서명 보호된 IPC를 통해 Engine에서 Vault로 이동하고, 키 자료는 기기 간에 암호화된 QR 프레임으로만 이동합니다——카메라 대 카메라, 네트워크 격리 강제<sup><a href=\"#cite-3\">[3]</a></sup>.", "whitepaper.ch2_p2": "신뢰는 감사 가능합니다: Engine의 <span class=\"mono\">core/</span> 모듈(프로토콜, 암호, IPC)은 Vault의 것과 <b>바이트 단위로 동일</b>하므로 두 앱 모두 동일한 공개 소스에 대해 검증합니다<sup><a href=\"#cite-1\">[1]</a></sup>. 메시지는 ECDH 키 합의와 AES-256-GCM으로 종단간 암호화되며, 릴레이는 봉투만 보고 평문은 결코 보지 못합니다<sup><a href=\"#cite-1\">[1]</a></sup>.", "whitepaper.h22": "하나의 신원, 네 가지 연결 불가 컨텍스트", "whitepaper.ch2_p3": "Havix는 HKDF로 단일 마스터 키에서 네 가지 컨텍스트별 하위 신원——공개, 시장, 터널, 위키 컨텍스트——을 파생합니다<sup><a href=\"#cite-6\">[6]</a></sup>. 파생은 암호학적으로 연결 불가능합니다: 시장 페르소나는 사적인 통신과 상관될 수 없습니다. 이것이 한 사람이 동시에 <mark class=\"key\">의회의 시민, 시장의 거래자, 채팅의 사적 인물</mark>이 될 수 있게 합니다——계정 세 개도, 매핑을 가진 플랫폼도 필요 없이.", "whitepaper.h23": "세 개의 평면, 하나의 루프", "whitepaper.ch2_li1": "<b>애플리케이션 평면(온라인):</b> Engine——사용자 대상, 키 없음, 순수 메모리. 메시지는 RAM에만 존재하며, 압수에 대한 공격 표면은 거의 제로입니다.", "whitepaper.ch2_li2": "<b>보관 평면(오프라인):</b> Vault——키 저장소는 생체 인증 뒤에 봉인되고, 내보내기는 QR로만 가능합니다.", "whitepaper.ch2_li3": "<b>조정 평면(오프체인 P2P):</b> Havix——신원 파생, 평판/신용 원장, 중재, AI를 인가하는 헌장<sup><a href=\"#cite-6\">[6]</a></sup>.", "whitepaper.ch2_li4": "<b>결제 평면(온체인):</b> BNB 스마트체인의 Aether——거버넌스, 재고, 타임락 실행. 양도 가능한 토큰 공급이 아닌 소울바운드 SBT 등급으로 통치됩니다<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch2_p4": "Havix 자체의 로드맵은 이를 3계층 스택——네트워크 기반(L0), 인지 실행(L1, Germ), 온체인 거버넌스(L2, Aether)——으로 공식화하며, 4컨텍스트 DID가 계층 간 암호학적 분리를 강제합니다<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch3": "네 가지 기관", "whitepaper.h31": "Vault — 금고", "whitepaper.note31": "v3.70.0 · 출시됨", "whitepaper.ch3_p1": "범용 오프라인 키스토어이며 Engine의 부속품이 아닙니다: 규정을 준수하는 모든 앱을 위해 키를 보관할 수 있습니다. 메커니즘: 네트워크 권한 없음; 키는 TEE에 봉인; 생체 인증 게이트 서명(가능한 경우 StrongBox 기반); SPARK 지갑 보관——잔액은 보안 세계에서 공동 서명된 추가 전용 거래 체인으로 존재하며, 지갑 인계는 전체 잔액을 genesis 거래로 새 기기로 이전합니다; 새 하드웨어로의 마이그레이션은 QR로만 가능하고 개인키는 결코 네트워크 스택에 들어가지 않습니다<sup><a href=\"#cite-3\">[3]</a></sup>. v3.40부터 Engine은 서명 보호된 Binder IPC 직통 채널로 Vault에 도달합니다——기존의 크로스 앱 점프 다이얼로그는 제거되었습니다<sup><a href=\"#cite-3\">[3]</a></sup>.", "whitepaper.ch3_p2": "전체 루프의 시장 진입점: 순수 메모리 아키텍처, 그룹 메시징, 60개 이모지 표현 경제, DID 프로필을 갖춘 주권 소셜 메신저입니다<sup><a href=\"#cite-1\">[1]</a></sup>. 경제 엔진은 저장소에 이미 명시되어 있습니다: <mark class=\"key\">1KB당 10 SPARK</mark> — 모든 메시지는 UTF-8 크기로 계량되고 올림되며, 메시지당 최소 10 SPARK; 일일 연료 보조금 1,000 SPARK(자연일에 대해 멱등하며 권위 있는 원장이 판정하고 바인딩된 Vault 신원으로 게이트); 헤비 유저는 지갑에서 충전합니다<sup><a href=\"#cite-2\">[2]</a></sup>. 지갑 잔액은 저장된 숫자가 아니라, Vault가 보유한 지갑 키가 공동 서명한 추가 전용 거래 체인의 파생입니다——예외 없이 모든 잔액 변동은 서명된 거래입니다<sup><a href=\"#cite-2\">[2]</a></sup>. 클라이언트 측 선차감이 구현되었고, 독립된 spark-ledger 서비스가 서버 측에서 잔액을 정산합니다<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.h33": "Aether — 의회", "whitepaper.note33": "v3.6 · BSC · 감사 종료 · 메인넷 대기", "whitepaper.ch3_p3": "BNB 스마트체인의 SBT 거버넌스 DAO 커널입니다. 가중치는 사는 것이 아니라 얻는 것입니다: AetherRing이 양도 불가능한 소울바운드 직급 14개를 발행하고, 세 회의체(평의회, 의회, 원로)와 시민 국민투표가 장로 거부권이 있는 7단계 제안 수명주기를 통해 서로 견제합니다. 재고는 타임락 호출을 실행하는 3/5 Safe 멀티시그입니다<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>. 의도적인 설계적 긴장: <mark class=\"key\">거버넌스는 소울바운드(SBT)인 반면 연료는 실제 발행된 자산</mark>입니다 — 고래는 $SPARK를 살 수 있지만 $SPARK가 사는 것은 메시지이지 표가 아닙니다. 한 계약은 돋보입니다: AetherDonation은 <b>외부 자선 채널</b>(공공재에 대한 USDC 팁)이며 루프의 경제와 독립적입니다.", "whitepaper.h34": "Havix — 신원 루트", "whitepaper.note34": "검증됨 · 대기", "whitepaper.ch3_p4": "루프 아래의 조정 네트워크: 8개 모듈(신원, 메시지 유형, 신용, 보증, 위키, 중재, 시장, s-node 런타임), 통과 테스트 1,174개(MVP 980 + 검증 실험 194, M10 감사 기준), 그리고 2차례 감사 프로그램——M9가 15개 발견 사항을 모두 종결했고, M10 심층 감사가 52개 더(5 P0 + 15 P1 + 32 P2)를 드러냈으며 P0/P1은 클로즈드 베타 전에 해결되었습니다<sup><a href=\"#cite-6\">[6]</a></sup>. 그 헌장 평면이 바로 AI를 마법이 아닌 법적 토대 위에 두는 것입니다: 일상 작업은 영수증과 함께 자동 실행되고, <mark class=\"key\">레드라인 작업은 물리적으로 인간의 온체인 투표로 라우팅됩니다</mark>. 헌장 저장소와 인터셉터는 M11 작업 흐름으로 예정되어 있습니다<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.h35": "Germ — 두뇌, 나중에", "whitepaper.ch3_p5": "Germ은 노드 레벨 AI 계층입니다: Havix 네트워크에서 자신의 4컨텍스트 신원으로 추론하는 AI. 고의적으로 연기되었습니다——<mark class=\"key\">오늘의 시장 진입은 Engine</mark>입니다; 돌볼 가치가 있는 사용자가 루프에 모이면 두뇌가 도착합니다. 이 백서에서 Germ은 경제가 그를 위해 공간을 비워야 하는 곳(예비금 AI, §5)에서만 등장합니다.", "whitepaper.ch4": "SPARK 토큰 경제", "whitepaper.h41": "효용: 물리가 뒷받침하는 연료", "whitepaper.ch4_p1": "SPARK는 <b>계량 자산</b>입니다. Engine에서 모든 킬로바이트는 10 SPARK를 소모합니다——메시지 크기로 계량되고 올림되며, 메시지당 최소 10——미터는 서비스 약관이 아니라 프로토콜에 있습니다<sup><a href=\"#cite-2\">[2]</a></sup>. 예산은 실제 100&nbsp;Mbps 릴레이 기준선에서 파생됩니다: 텍스트 봉투 최대 40&nbsp;KB, 미디어 최대 48&nbsp;KB, 128&nbsp;KB 하드 프레임 상한, 그룹 200명 제한<sup><a href=\"#cite-1\">[1]</a></sup>. 표현하는 모든 바이트에 연료가 들기 때문에 스팸에는 한계 비용이 있고, 발언은 자유로워집니다.", "whitepaper.ch4_li1": "<b>획득:</b> 일일 연료 보조금(자연일마다 1,000 SPARK, 멱등, 바인딩된 Vault 신원으로 게이트<sup><a href=\"#cite-2\">[2]</a></sup>), 지갑 충전<sup><a href=\"#cite-2\">[2]</a></sup>, 또는 TGE 후 시장 구매.", "whitepaper.ch4_li2": "<b>소비:</b> 메시지 연료; 그룹 및 미디어 예산; SDK 앱 사용.", "whitepaper.ch4_li3": "<b>보유:</b> DAO 재고는 SPARK를 장기 예비금으로 보유합니다——실제 사용에서 오는 수요가 모든 보유자에게 대칭적으로 귀속됩니다.", "whitepaper.ch4_note": "◇ 설계 매개변수(베스팅 기간, LP 잠금, 수수료 라우팅, 허용량 감쇠)는 이 초안의 권장 기본값입니다. 각각은 사전판매 시작 전에 거버넌스가 확인하거나 수정합니다. 온체인 계량 요율(1KB = 10 SPARK, 메시지당 최소 10, 자연일당 1,000 일일 연료 보조금)은 Engine 사양에 고정되어 있습니다<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.h42": "동일 자산의 두 단계——계량 원장, 그리고 고정 공급", "whitepaper.ch4_p2": "SPARK는 의도적인 두 단계로 출시되며, 그 순서가 곧 설계입니다. <b>단계 A — 계량 원장(현재 운영 중):</b> 출시된 Engine 소프트웨어 내부에서 SPARK는 오프체인 해시 연결 원장으로 존재합니다. 각 기기는 Vault가 공동 서명한 연료 보조금으로 <b>자연일당 1,000</b>을 발행합니다——안티-시빌 방어는 이미 운영 중: TEE/DRM 기기 앵커, 릴레이 측의 연결 불가 기기 해시 일일 중복 제거, 서명 게이트에서 강제되는 금액 화이트리스트. 단계 A 잔액은 <mark class=\"key\">양도 불가, 거래 불가, 전환 불가</mark>입니다——오늘 그것은 할당량이지 유가증권이 아닙니다.", "whitepaper.ch4_p3": "<b>단계 B — TGE 매핑(계획):</b> 고정된 <b>1,000T 공급</b>이 TGE에서 발효됩니다. 초기 공급은 §4.3의 사전판매, IDO, 유동성, 예비금 트랜치와 단계 A 잔액의 스냅샷 기반 매핑(커뮤니티 인센티브 트랜치로)을 결합합니다——구체적 전환 매개변수는 초안 기본값 ◇이며 사전판매 시작 전에 거버넌스가 확인합니다. TGE 후 SPARK는 자유롭게 유통되며, <b>공개 USDC 및 기타 스테이블코인 페어를 포함</b>합니다. 전환 채널은 오늘 의도적으로 미구축입니다: 기기 앵커링, 일일 중복 제거, 금액 화이트리스트는 지켜야 할 금고가 생기기 <i>전에</i> 존재해야 하며, 그래야 전환성이 열리는 날 그 방어가 할당 위생에서 금고의 문으로 승격합니다.", "whitepaper.h43": "공급 및 배분", "whitepaper.ch4_p4": "총 공급은 <b>1,000T SPARK(1,000,000,000,000,000 — 1천조)</b>로 고정됩니다. 배분은 10/20/10/50/10 분할을 따릅니다: 사전판매, IDO, DEX 유동성, DAO 예비금, 커뮤니티 인센티브. <mark class=\"key\">팀 트랜치도, 내부자 배분도, 마케팅 트랜치도 없습니다</mark>——팀의 상승 여력은 DAO와 공유하는 50% 예비금이며, 공개 거버넌스를 통해서만 해제되고 헌장으로 연간 예비금의 ≤5%로 제한됩니다.", "whitepaper.fig1": "그림 1 — TGE 시 SPARK 배분(정제됨: 10개 슬라이스, 5개 트랜치)", "whitepaper.fig1_sub": "총 공급 1,000T(1,000,000,000,000,000). 사전판매는 TGE에서 2.5% + 7.5% 베스팅으로 분할; IDO는 TGE에서 5% + 15% 베스팅 분할(두 트랜치 모두: TGE 시 25%, 이후 9개월 선형); 예비금 하위 분할은 헌장으로 제한된 초안 기본값 ◇이며 방출 상한이 ≤5%/연——예비금 자체에는 캘린더 잠금 해제가 없습니다.", "whitepaper.th_tranche": "트랜치", "whitepaper.th_share": "비율", "whitepaper.th_amount": "수량", "whitepaper.th_unlock": "잠금 해제", "vault.foot_home": "홈", "whitepaper.ch4b": "이중 트랙 런칭", "whitepaper.h44": "단계 1 — 사전판매(10%)", "whitepaper.h45": "단계 2 — IDO(20%)", "whitepaper.h46": "유동성 및 DEX(10%)", "whitepaper.h47": "잠금 해제 일정", "whitepaper.h48": "안전장치 및 규정 준수", "whitepaper.h32": "Engine — 앱", "whitepaper.note32": "v3.64.7 · 출시됨", "whitepaper.ch5": "예비금 거버넌스", "whitepaper.ch6": "TGE 로의 로드맵", "whitepaper.ch7": "위험 및 고지 사항", "whitepaper.fig2": "그림 2 — TGE 이후 유통 공급", "whitepaper.m1": "사전판매——화이트리스트 · $500 상한", "whitepaper.m2": "IDO——LBP · 3-7일", "whitepaper.m3": "유동성——TGE에서 시드", "whitepaper.m4": "커뮤니티 인센티브——추천 및 활성화", "whitepaper.m5": "DAO 예비금——거버넌스 게이트 · 연 ≤5%", "whitepaper.tl_now_t": "실전 루프", "whitepaper.tltge_t": "토큰 생성 이벤트", "whitepaper.tl01_t": "화이트리스트 및 매개변수 확정", "whitepaper.tl02_t": "사전판매 기간", "whitepaper.tl03_t": "LBP에서의 IDO", "whitepaper.tl9_t": "유동 상한 도달 · DAO가 예비금 인수", "whitepaper.tll1_t": "Germ, 나중에", "whitepaper.src": "출처", "whitepaper.src6": "eneatlnc-cell, Havix 저장소——병렬 신원 네트워크: 모듈 8개, 테스트 1,174개(M10 감사 기준), 감사 발견 15건 종결.", "whitepaper.src1": "eneatlnc-cell, Engine 3.0——E2EE 프로토콜 스택의 공개 감사판(core-crypto, core-protocol, core-ipc; AGPL-3.0).", "whitepaper.src2": "Engine, SparkEconomy 공학 기록(내부)——1KB = 10 SPARK(메시지당 최소 10), 자연일당 일일 연료 보조금 1,000, 서명 거래 SPARK 지갑(v3.37+), 지갑 충전, spark-ledger 서비스 계획.", "whitepaper.src3": "eneatlnc-cell, Engine 3.0——core-ipc: 오프라인 키스토어 뒤의 Engine↔Vault 서명 계약(네트워크 권한 없음, 생체 인증 서명, QR 마이그레이션).", "whitepaper.src4": "eneatlnc-cell, Aether 저장소——SBT 거버넌스 DAO 커널: AetherRing, Governance, Election, Safe 재고.", "whitepaper.src5": "Aether, docs/TECHNICAL_WHITEPAPER.md——세 회의체, 7단계 수명주기, 원로 거부권, 회의체/시민 균형.", "whitepaper.src7": "Havix, NEXT-STEPS.md——L0/L1/L2 3계층 스택, M11 헌장 저장소 및 레드라인 인터셉터 계획.", "whitepaper.foot_copy": "© <span class=\"yr\">2026</span> SparkLoop · 백서 v1.0 초안", "whitepaper.foot_cta": "사전판매 화이트리스트 참여", "whitepaper.tr_presale_amt": "100T", "whitepaper.tr_presale_t": "사전판매——화이트리스트", "whitepaper.tr_tge_amt": "25T", "whitepaper.tr_tge_t": "└ TGE 잠금 해제", "whitepaper.tr_tge_un": "TGE에서 유동", "whitepaper.tr_9m_amt": "75T", "whitepaper.tr_9m_t": "└ 9개월 베스팅", "whitepaper.tr_9m_un": "선형, 1-9개월", "whitepaper.tr_a_un": "TGE에서 25% ◇, 이후 9개월 선형 ◇", "whitepaper.tr_b_un": "TGE에서 25% ◇, 이후 9개월 선형 ◇", "whitepaper.tr_ido_amt": "200T", "whitepaper.tr_ido_t": "IDO——공개 LBP 라운드", "whitepaper.tr_tge2_amt": "50T", "whitepaper.tr_tge2_t": "└ TGE 잠금 해제", "whitepaper.tr_9m2_amt": "150T", "whitepaper.tr_9m2_t": "└ 9개월 베스팅", "whitepaper.tr_dex_amt": "100T", "whitepaper.tr_dex_t": "DEX 유동성", "whitepaper.tr_dex_un": "TGE에서 풀에 시드 · LP 12개월 잠금 ◇", "whitepaper.tr_dao_amt": "500T", "whitepaper.tr_dao_t": "DAO 예비금", "whitepaper.tr_dao_un": "캘린더 없음——Aether 제안으로만 방출 · 헌장 상한 연 ≤5%", "whitepaper.tr_comm_amt": "100T", "whitepaper.tr_comm_t": "커뮤니티 인센티브", "whitepaper.tr_comm_un": "추천 보너스 + 활성화 보조금 · 프로그램별 정산", "whitepaper.tr_fuel_amt": "150T", "whitepaper.tr_fuel_t": "└ Engine 연료 보조금", "whitepaper.tr_fuel_un": "헌장 기본 ◇——보조금 에폭", "whitepaper.tr_relay_amt": "100T", "whitepaper.tr_relay_t": "└ 릴레이 및 인프라", "whitepaper.tr_relay_un": "헌장 기본 ◇——릴레이, s-node", "whitepaper.tr_eco_amt": "150T", "whitepaper.tr_eco_t": "└ 생태계 보조금", "whitepaper.tr_eco_un": "헌장 기본 ◇——앱, 릴레이, 도구", "whitepaper.tr_ai_amt": "100T", "whitepaper.tr_ai_t": "└ AI 유동성 및 기금", "whitepaper.tr_ai_un": "헌장 기본 ◇——AI 범위", "whitepaper.ch4b_p1": "런칭의 핵심은 <b>사전판매와 IDO 병행, 서로 다른 템포</b>입니다: 사전판매는 핵심 커뮤니티를, IDO는 대중을 대상으로 합니다. <mark class=\"key\">사전판매가 기반을 만들고 IDO가 시장을 엽니다.</mark>", "whitepaper.ch4b_li1": "<b>대상:</b> 초기 핵심 기여자와 활발한 커뮤니티 구성원만. 지갑 주소는 사전에 화이트리스트로 수집되고 시작 시간은 먼저 목록에 공지됩니다.", "whitepaper.ch4b_li2": "<b>안티-고래:</b> 하드한 <mark class=\"key\">지갑당 $500 상한</mark>.", "whitepaper.ch4b_li3": "<b>조건:</b> 고정된 저가에 USDT 또는 BNB로 지불; 25%는 TGE에서 잠금 해제, 나머지는 9개월에 걸쳐 선형 베스팅 ◇.", "whitepaper.ch4b_li4": "<b>실행:</b> 창이 열리면 화이트리스트 지갑이 공식 사이트에서 연결되어 상한 내에서 구독합니다.", "whitepaper.ch4b2_li1": "<b>플랫폼:</b> Fjord Foundry급 LBP 런치패드——가격은 높게 시작해 수요가 따라잡을 때까지 감소하며, 이는 <mark class=\"key\">스나이핑 우위를 제거</mark>합니다; 화이트리스트도, 선착 블록 우위도 없습니다.", "whitepaper.ch4b2_li2": "<b>매개변수:</b> 풀에 자금을 넣기 전 토큰 주소 3중 확인(되돌릴 수 없음); USDT 또는 BNB 지불; 3-7일 창; 지갑별 최소 및 최대 상한; 시작가는 사전판매가보다 높음.", "whitepaper.ch4b2_li3": "<b>배분:</b> 각 지갑 할당의 25%는 TGE에서 청구 가능하고 나머지는 9개월 선형 베스팅 ◇; 수익은 프로젝트 멀티시그로 직접 흐릅니다.", "whitepaper.ch4b2_li4": "<b>회계:</b> 창이 닫힌 후 구독 목록과 금액을 조정하여 공개한 뒤 분배합니다.", "whitepaper.ch4b3_note": "주소는 배포 순간 Spark 페이지에 공개됩니다. 그 이전에 SPARK를 사칭하는 모든 주소는 사기입니다.", "whitepaper.ch4b3_p1": "TGE에서 유동성 트랜치가 DEX 풀에 시드되어 BNB와 페어링됩니다. SPARK는 BNB 체인의 BEP-20 토큰으로 발행되는 것이 권장됩니다 ◇——양 라운드의 USDT/BNB 지불 수단과 일치——Aether 재고와 거버넌스는 동일한 BNB 스마트체인에 배포되어<sup><a href=\"#cite-4\">[4]</a></sup>, 예비금 작업은 크로스체인 브리지 없이 네이티브로 정산됩니다<sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch4b4_p1": "구조적 약속은 <mark class=\"key\">하드 플로트 상한</mark>입니다: 캘린더는 40%(사전판매 + IDO + LP)를 넘어 잠금 해제할 수 없습니다; 10% 인센티브 트랜치는 검증된 추천과 활성화에만 지급되고, 50% 예비금은 공개적이고 거부 가능한 제안을 통해서만 움직이며, 헌장은 방출을 <b>연간 예비금의 ≤5%</b>로 제한합니다. 초기 구매자는 최대 플로트가 정확히 무엇인지 압니다.", "whitepaper.ch5_p1": "50% 예비금은 재고 지갑이 아니라 <b>헌법적 대상</b>입니다. 보관은 3/5 Safe 멀티시그에 있고, 모든 이동은 Aether의 7단계 수명주기 제안을 거치고 원로 거부권 창을 통과하며 타임락으로 실행됩니다<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>. 그 과정의 가중치는 소울바운드이며 얻어지는 것입니다——사거나 양도할 수 없는 AetherRing 직급 14개<sup><a href=\"#cite-4\">[4]</a></sup>.", "whitepaper.ch5_p2": "예비금 용도는 헌장으로 제한됩니다: Engine 연료 사용자 보조금 에폭, 릴레이 및 인프라 자금, 생태계 보조금, 그리고——Germ이 존재하면——하드 한도 내 특허받은 AI의 유동성 관리로, 레드라인은 인간 투표로 돌아갑니다<sup><a href=\"#cite-6\">[6]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>. 헌장은 또한 <mark class=\"key\">연간 예비금의 ≤5%라는 방출률 상한</mark>을 정합니다——재량이 아닌 계산 가능한 약속: 완전히 장악된 재고라도 예비금을 연 20분의 1보다 빠르게 고갈시킬 수 없습니다. 균형 설계는 의도적입니다: <mark class=\"key\">회의체와 시민이 각각 투표 가중치의 약 절반을 가집니다</mark>, 그래서 기관도 군중도 단독으로 예비금을 쓸 수 없습니다<sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch7_disc": "<b>고지 사항.</b> 이 백서는 오픈소스 소프트웨어 프로젝트와 그 연료 자산을 설명합니다. 그것은 투자 조언도, 증권 판매의 제안도, 수익 약속도 아닙니다. ◇로 표시된 매개변수는 런칭 전에 변경될 수 있는 초안 기본값입니다. 이 루프에는 \"저를 믿으세요\"식 마케팅이 없습니다: 저장소를 읽으세요.", "whitepaper.ch7_li1": "<b>실행 위험:</b> Aether 메인넷 배포, M11 헌장 저장소, spark-ledger 서비스는 TGE 순서가 의존하는 미완성 구성 요소입니다<sup><a href=\"#cite-2\">[2]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch7_li2": "<b>크로스체인 위험:</b> 설계상 완화됨——SPARK와 Aether 거버넌스/재고가 동일한 BNB 스마트체인 ◇에 배포되어 예비금 작업이 어떤 브리지 의존 없이 네이티브로 정산됩니다.", "whitepaper.ch7_li3": "<b>시장 위험:</b> LBP는 가격을 정직하게 발견합니다——즉 하방으로도 발견할 수 있습니다. 고정된 낮은 사전판매 가격은 초기 신뢰를 보상하지만 수익을 보장하지는 않습니다.", "whitepaper.ch7_li4": "<b>규제 위험:</b> 토큰 발행은 서로 다른 규제에 직면하며, 관할권에 따라 제한이 적용될 수 있습니다. 법률 검토는 형식이 아니라 전제 조건입니다.", "whitepaper.ch7_li5": "<b>스마트 계약 위험:</b> 감사는 위험을 줄이지만 결코 제거하지 못합니다. 공식 사이트에 게시된 주소와만 상호작용하십시오.", "whitepaper.fig2_sub": "유동 플로트: TGE에서 17.5%(사전판매 2.5% + IDO 5% + LP 10%), 두 트랜치가 베스팅됨에 따라 매월 2.5%씩 상승하여 9개월 차에 40% 캘린더 상한에 도달합니다. 10% 인센티브 트랜치는 프로그램별로 정산되고, 나머지 50%는 거버넌스로만 움직이며 헌장 상한은 연 ≤5%입니다.", "whitepaper.tl_now_d": "Engine v3.64.7과 Vault v3.70.0이 출시되었습니다——Binder IPC 직통 채널과 서명 거래 SPARK 지갑이 가동되고, 두 앱 모두 R8 난독화로 강화되었으며, 일일 연료 보조금은 릴레이에서 연결 불가한 기기-일 해시로 중복 제거됩니다. Havix는 감사 발견 15건 종결 후 클로즈드 베타에 있으며, BSC의 Aether v3.6(감사 수정 종결)은 메인넷 배포를 기다립니다<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>. 사전판매 화이트리스트가 열려 있습니다.", "whitepaper.tl01_d": "지갑 주소 수집; 사전판매 가격, IDO 경계, 베스팅 및 LP 잠금 매개변수 확정; 계약 감사 및 주소 게시.", "whitepaper.tl02_d": "화이트리스트 지갑이 고정된 저가로 $500 상한 안에서 USDT/BNB로 구독합니다.", "whitepaper.tl03_d": "3-7일 공개 라운드; 가격은 스스로 발견되고 종료 시 조정 결과가 공개됩니다.", "whitepaper.tl9_d": "사전판매와 IDO 베스팅 완료——캘린더 플로트가 40% 상한에 도달; Aether 메인넷 거버넌스가 예비금 임무를 전면 인수하고 방출은 헌장 상한 연 ≤5%로 제한됩니다.", "whitepaper.tltge_d": "사전판매 25% + IDO 25% 초기 배분이 지갑에 도착; 10% 유동성 트랜치가 DEX 풀에 시드; spark-ledger가 Engine 정산용으로 가동<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.tll1_d": "노드 레벨 AI가 헌장 아래 네트워크에 합류합니다——두뇌는 이미 뛰고 있는 루프를 돌보기 위해 도착합니다<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch4b5_li1": "<b>보안:</b> 토큰, 사전판매, LBP 계약은 자금을 받기 전에 인정된 회사의 감사를 받아야 합니다. 보고서는 주소와 함께 게시됩니다.", "whitepaper.ch4b5_li2": "<b>투명성:</b> 사전판매와 IDO 계약 주소와 규칙은 각 창이 열리기 전에 공지되고, 구독 조정 결과는 TGE 배분 전에 게시됩니다.", "whitepaper.ch4b5_li3": "<b>안티봇:</b> LBP 가격 감소가 스나이핑을 무너뜨립니다; 지갑당 상한(사전판매 $500, IDO 최소/최대)이 집중을 제한; 사전판매 계약에 동적 슬리피지 경계가 적용될 수 있습니다 ◇.", "whitepaper.ch4b5_li4": "<b>법률:</b> 런칭은 관련 관할권에 대해 법률 고문이 검토 중이며, 필요한 경우 참여가 제한될 수 있습니다. 여기의 어떤 내용도 증권 제안이 아닙니다."},
  ar: {"vault.nav_home": "الرئيسية", "vault.nav_rewards": "المكافآت", "vault.chip": "غير متصل · معزول · سيادي", "vault.h1_a": "الخزنة التي", "vault.h1_grad": "لا تتصل بالشبكة أبدًا", "vault.hero_desc": "<strong>خزنة</strong> هي الخزنة غير المتصلة الشاملة لتطبيقات فئة Engine. تخزّن المفاتيح الخاصة وتواقيع الدخول بـ<strong>صفر إذن إنترنت</strong>، وتُحكم إغلاقها داخل شريحة الهاتف الآمنة، وتوقّع ببصمة أصبعك، وتنقل المفاتيح إلى عتاد جديد عبر الضوء فقط — رمز QR. لا «نعدّ بعدم الاتصال» بل <strong>لا تستطيع الاتصال</strong>.", "vault.btn_ceremony": "▶ جرّب مراسم التوقيع", "vault.btn_migration": "⟳ ترحيل المفاتيح", "vault.btn_audit": "↗ افحص طبقة التشفير", "vault.stat_internet": "أذونات الإنترنت في البيان", "vault.stat_tee": "مفاتيح مُحكمة بعتاد", "vault.stat_wallet": "حفظ المحفظة ونقلها", "vault.stat_qr": "المخرج الوحيد للمفتاح", "vault.tag_demo": "أُعيد إنشاؤه من فيلم العرض", "vault.title_demo": "أمسك الخزنة بين يديك", "vault.sub_demo": "على اليسار تطبيق Vault الحقيقي: عرض محفظة SPARK — الرصيد ما هو إلا مجموع الصفقات الموقّعة، والنقل دائمًا على بُعد نقرة من الشريط السفلي. في الوسط صفحة حالة الخزنة التي تسرد كل مفتاح تطبيق تحرسه — اضغط <b>وقّع</b> وشاهد مراسم المقاييس الحيوية. وعلى اليمين ما يبلّغه الهاتف نفسه عن عزلته.", "vault.wallet_title": "محفظة SPARK", "vault.wallet_sub": "حفظ Vault · سلسلة صفقات موقّعة", "vault.wallet_balsub": "الرصيد = Σ المعاملات الموقّعة", "vault.wallet_handover": "⇄ نقل المحفظة", "vault.wallet_keys": "المفاتيح: 3", "vault.vs_title": "المفاتيح المحروسة", "vault.vs_fingerprint": "بصمة", "vault.vs_algorithm": "الخوارزمية", "vault.vs_sealed": "مُحكم", "vault.vs_sealed_val": "Keystore TEE · AES-256-GCM", "vault.vs_lastreq": "آخر طلب", "vault.vs_waiting": "في انتظار…", "vault.vs_sign": "وقّع على طلب Engine", "vault.vs_migrate": "⟳ ترحيل إلى جهاز جديد", "vault.bio_touch": "لمس المستشعر", "vault.bio_title": "BiometricPrompt", "vault.bio_desc": "المفتاح لا يغادر TEE أبدًا — يوقّع داخل عتاد آمن.", "vault.console_head": "adb shell — فحص ذاتي للعزل", "vault.sim_caption": "<b>كل حدث أعلاه محلي.</b> ليست لدى وحدة التحكم ما تبلّغه من الشبكة — لأنها غير موجودة.", "vault.tag_guards": "ماذا تحرس", "vault.title_guards_a": "مهمة واحدة: أن تكون", "vault.title_guards_grad": "خزنة كل تطبيق سيادي", "vault.sub_guards": "Vault مصممة لتكون مستقلة عن التطبيقات. أي شيء شبيه بـ Engine — تطبيق يريد حياة إنترنت مع مفاتيح غير متصلة — يمكنه تفويض هويته إلى الخزنة.", "vault.card1_t": "مفاتيح التطبيق الخاصة", "vault.card1_d": "هويات ECDSA P-256 مولدة من تطبيقات مثل Engine، تُحكم إغلاقها فور وصولها.", "vault.card2_t": "تواقيع الدخول والمحفظة", "vault.card2_d": "رموز دخول التحدي-الاستجابة ومعاملات محفظة SPARK — تُوقَّع داخل الخزنة ولا تُخزَّن أبدًا على الإنترنت. كل تغيّر في الرصيد صفقة موقّعة على سلسلة قابلة للإضافة فقط.", "vault.card3_t": "ترابطات ترحيل الأجهزة", "vault.card3_d": "سجلات إعادة ربط موقّعة تنقل هويتك إلى عتاد جديد دون نسخة احتياطية سحابية.", "vault.card4_t": "دليل البصمات", "vault.card4_d": "سجل محلي لكل مفتاح محروس، بصمته وحالة إحكامه — مرئية بنظرة واحدة.", "vault.card5_t": "لا شيء آخر", "vault.card5_d": "لا تصفّح ولا مزامنة ولا إعلانات ولا تتبع. خزنة بشاشة، وليست تطبيق هاتف ذكي.", "vault.card6_t": "فتح يقتصر على المقاييس الحيوية", "vault.card6_d": "كل فتح يمر عبر BiometricPrompt بنافذة نضارة ±120 ثانية — حماية من إعادة التشغيل مبنية على الساعة.", "vault.tag_ceremony": "كيف يوقّع تطبيق متصل دون اتصال", "vault.title_ceremony_a": "المفتاح يوقّع.", "vault.title_ceremony_grad": "المفتاح لا يغادر.", "vault.pl1": "Engine تحتاج إلى توقيع", "vault.pl2": "طلب IPC + تحدٍّ", "vault.pl3": "BiometricPrompt", "vault.pl4": "TEE يفتح ويوقّع", "vault.pl5": "استدعاء موقّع", "vault.pl6": "Engine تتحقق من التوقيع + Δt&lt;120s", "vault.co_tag": "لماذا تهمّ نافذة ±120 ثانية", "vault.co_text": "توقيع الاستدعاء يغطي <b>sessionId ‖ status ‖ timestamp</b>. حتى لو سُرق الاستدعاء لا يمكن إعادة تشغيله بعد دقائق — الساعة جزء من الإثبات. المرحّل لا يرى المفتاح أبدًا؛ Engine لا يمسكه أبدًا؛<b>فقط TEE يمسكه.</b>", "vault.tag_migration": "هاتف جديد، الهوية ذاتها", "vault.title_mig_a": "الانتقال عبر", "vault.title_mig_grad": "حزمة ضوء", "vault.sub_migration": "المفاتيح الخاصة هي الشيء الوحيد الذي لا يجب أن تثق به سحابة أبدًا. عندما يتغير عتادك، تمشي Vault بهويتك عبر الأجهزة شاشةً إلى شاشة — مرّ بها أدناه.", "vault.migprev": "السابق", "vault.mignext": "التالي", "vault.flag_t": "FLAG_SECURE", "vault.flag_d": "شاشة QR تُسوّد لقطات الشاشة والتسجيلات. التلصّص من فوق الكتف هو الهجوم الوحيد المتبقي.", "vault.payload_t": "حمولة مشفرة", "vault.payload_d": "URI الرابط يحمل حمولة جلسة مشفرة — المفتاح الخاص الخام لا يظهر أبدًا في أي URI.", "vault.burn_t": "أحرق بعد الربط", "vault.burn_d": "Engine يستدعي convertBoundToPublicKeyOnly() — تُمسح نسخة مفتاحه الخاص لحظة تولّي Vault.", "vault.title_compare": "أين تنام المفاتيح الليلة؟", "vault.th_storage": "نموذج التخزين", "vault.th_network": "مدى الوصول للشبكة", "vault.th_extraction": "خطر الاستخراج", "vault.th_migration": "مسار الترحيل", "vault.tr_ext_t": "محفظة إضافة متصفح", "vault.tr_ext_reach": "متصل دائمًا", "vault.tr_ext_risk": "مرتفع — الذاكرة والقرص قابلان للقراءة", "vault.tr_ext_mig": "عبارة البذرة على ورق", "vault.tr_hot_t": "خادم ساخن / إيداعي", "vault.tr_hot_reach": "سطح هجوم 24/7", "vault.tr_hot_risk": "نظامي — اختراق واحد، كل المفاتيح", "vault.tr_hot_mig": "ثق بالمشغّل", "vault.tr_cloud_t": "نسخة احتياطية سحابية للمفاتيح", "vault.tr_cloud_reach": "متزامن بالتصميم", "vault.tr_cloud_risk": "اختراق الحساب = اختراق المفتاح", "vault.tr_cloud_mig": "إعادة تنزيل", "vault.tr_vault_reach": "لا إذن إنترنت", "vault.tr_vault_risk": "شريحة TEE + بوابة بيومترية", "vault.tr_vault_mig": "قناة QR الضوئية، إعادة ربط موقّعة", "vault.co2_tag": "فيزياء لا وعود", "vault.co2_text": "كل صف في هذا الجدول يعتمد على حسن سلوك شخص ما. عزلة Vault معلنة في بيان Android ويفرضها نظام التشغيل — <b>لا يمكن إرسال حزمة، لذا لا يُحتاج إلى أي وعد.</b>", "vault.foot_desc": "تفسير مستقل لحلقة eneatlnc-cell. مكدس بروتوكول E2EE مفتوح للتدقيق؛ كل ادعاء يعود إلى الشيفرة والمستندات البيضاء.", "vault.foot_layers": "الطبقات", "vault.foot_engine": "اجتماعي سيادي", "vault.foot_vault": "حفظ غير متصل", "vault.foot_havix": "L0 · هوية متوازية", "vault.foot_spark": "الوقود", "vault.foot_rewards": "سياسة الإحالة", "vault.foot_loop": "حلقة Web4", "vault.foot_repos": "المستودعات", "vault.foot_bottom": "مفاتيح غير متصلة · حوكمة SBT · وقود $SPARK · AI مرخّص", "vault.log_settle_pre": "تمت المحاسبة جماعيًا داخل TEE → tx #", "vault.log_settle_suf": " أُضيف إلى السلسلة · الرصيد = Σ صفقات موقعة", "vault.log_handover": "وَقِّع على شهادة النقل · الرصيد كله ينتقل كصفقة تأسيس", "vault.log_bio_dismiss": "أُغلق طلب المقاييس الحيوية", "vault.log_ipc_pre": "استُلم طلب IPC · challenge=0x", "vault.log_ipc_suf": " · في انتظار المقاييس الحيوية", "vault.sig_result": "✓ موقّع · ECDSA P-256 · TEE", "vault.log_bio_ok": "مقاييس حيوية ✓ → فُتح المفتاح في TEE → وُقّع في العالم الآمن → أُحكم من جديد", "vault.log_callback": "تحقق الاستدعاء: sig(sessionId‖status‖ts) ✓ · Δt &lt; 120s ✓", "vault.mig1_title": "الجهاز الجديد يولّد زوج مفاتيح جديد", "vault.mig1_desc": "الجهاز الجديد يولّد هوية ECDSA P-256 الخاصة داخل Engine. لا يُستورد شيء عبر الهواء — أبدًا.", "vault.mig2_title": "الـVault القديمة تُصدّر ترابط الترحيل", "vault.mig2_desc": "الـVault القديمة تُحكم إذنًا على إطار QR. FLAG_SECURE تُسوّد لقطات الشاشة؛ المفتاح نفسه لا يغادر TEE أبدًا.", "vault.mig3_title": "الـVault الجديدة تمسح — قناة بصرية فقط", "vault.mig3_desc": "يقوم ML Kit بقراءة الإطار عبر الكاميرا. الشبكة الوحيدة المعنية هي الضوء.", "vault.mig4_title": "إعادة ربط الهوية بالمفتاح الجديد", "vault.mig4_desc": "استدعاء إعادة ربط موقّع ينقل DID إلى المفتاح العام للجهاز الجديد. تتحقق جهات الاتصال من البصمة الجديدة تلقائيًا.", "vault.mig5_title": "حفظ SPARK يُنقل أيضًا", "vault.mig5_desc": "الـVault القديمة توقّع شهادة نقل تُنهي سلسلتها بالرصيد كله؛ والـVault الجديدة تتحقق منها وتواصل دفتر الحسابات بصفقة تأسيس — لا يوجد رصيد غير موقّع أبدًا.", "vault.mig6_title": "أُحرقت النسخة القديمة، صفر بقايا", "vault.mig6_desc": "الـVault القديمة تمسح المفتاح المُحكم بمحو صفري. اكتمل الترحيل — لا مفتاح لمس الإنترنت أبدًا.", "vault.log_boot1": "AndroidManifest: uses-permission INTERNET → <b>غير موجود</b> ✓", "vault.log_boot2": "مكدس الشبكة: غير قابل للوصول · مآخذ: لا شيء · تتبع: لا شيء", "vault.log_boot3": "Keystore TEE حي · مفاتيح مُحكمة（AES-256-GCM）· مقاييس حيوية جاهزة", "vault.log_boot4": "سلسلة محفظة SPARK جاهزة · HWM ضد إعادة التشغيل · النقل جاهز", "whitepaper.nav_home": "الرئيسية", "whitepaper.nav_rewards": "المكافآت", "whitepaper.kicker": "// المستند التقني للمشروع", "whitepaper.chip": "الإصدار 1.0 · مسودة", "whitepaper.h1": "SPARK <span class=\"grad\">&amp; حلقة Web4 السيادية</span>", "whitepaper.hero_desc": "أعضاء أربعة — <strong>Vault</strong> و<strong>Engine</strong> و<strong>Aether</strong> و<strong>Havix</strong> — تشكل حلقة مغلقة واحدة، و<strong>SPARK</strong> هو الوقود الذي يديرها. مكدس بروتوكول E2EE مفتوح للتدقيق؛ تصف هذه الوثيقة البنية كما بُنيت، واقتصاديات الرمز كما صُمّمت، والإطلاق المزدوج: بيع مسبق بالقائمة البيضاء يليه IDO مبني على LBP.", "whitepaper.meta_1": "أغسطس 2026", "whitepaper.meta_2": "4 مستودعات · AGPL + APACHE", "whitepaper.meta_3": "القائمة البيضاء للبيع المسبق مفتوحة", "whitepaper.meta_4": "المعروض 1,000T SPARK", "whitepaper.stat_dao": "احتياطي DAO — بحوكمة", "whitepaper.stat_tge": "سائل عند TGE (يشمل 10% LP)", "whitepaper.stat_cap": "سقف البيع المسبق لكل محفظة", "whitepaper.stat_kb": "SPARK لكل كيلوبايت من الرسالة", "whitepaper.abstract": "<b>الملخص.</b> منح Web3 المستخدمين محافظ، لكنه أبقي حياتهم الاجتماعية على الخوادم. تسدّ حلقة Web4 النموذجية هذه الفجوة بـ<mark class=\"key\">العزل الفيزيائي</mark>: تطبيق اجتماعي متصل (<strong>Engine</strong>) لا يملك مفاتيح، وخزنة غير متصلة (<strong>Vault</strong>) تملك المفاتيح ولا تتصل أبدًا، وبرلمان تحكمه SBT (<strong>Aether</strong>) يودع احتياطي الوقود، وشبكة هويات متوازية (<strong>Havix</strong>) — مشتقة من DID رئيسي وتدير اقتصادًا مزدوجًا للائتمان والقيمة — ترخّص الذكاء الاصطناعي تحت دستور حيّ.<strong>$SPARK</strong> هو الأصل الوحيد المصدر الذي يقدّر التعبير في التطبيق ويموّل احتياطي DAO ويتدفق بينها — وقود للحلقة وليس تصويتًا أبدًا. توثق هذه الوثيقة البنية كما هي في المستودعات العامة، ثم تحدد الرمز: المنفعة، والتوزيع (بيع مسبق 10% / IDO 20% / سيولة DEX 10% / احتياطي DAO 50% / حوافز المجتمع 10%)، والإطلاق على مرحلتين، وجدول الفتح، والضمانات التي تُبقي الإطلاق عادلًا والاحتياطي سياديًا.", "whitepaper.toc1": "حلقة السيادة", "whitepaper.toc2": "البنية: العزل والهوية", "whitepaper.toc3": "الأعضاء الأربعة", "whitepaper.toc4": "اقتصاديات رمز SPARK", "whitepaper.toc4b": "الإطلاق المزدوج", "whitepaper.toc5": "حوكمة الاحتياطي", "whitepaper.toc6": "خارطة الطريق إلى TGE", "whitepaper.toc7": "المخاطر وإخلاء المسؤولية", "whitepaper.ch1": "حلقة السيادة", "whitepaper.ch1_p1": "هذا <b>مشروع واحد، وليس محفظة منتجات</b>. كل مستودع عضو؛ وتشترك الأعضاء بدم واحد — SPARK. يتحادث المستخدم في Engine؛ وكل رسالة تحرق وقودًا؛ والوقود يُودَع في احتياطي Aether؛ ويُبقي الذكاء الاصطناعي المرخّص على Havix الاحتياطي سائلًا؛ وتأثيرات Havix الشبكية تُبقي Engine حيًا؛ وطلب Engine يعطي SPARK سنده المادي. اقطع أي عضو فتتوقف الحلقة.", "whitepaper.th_organ": "العضو", "whitepaper.th_metaphor": "الاستعارة", "whitepaper.th_function": "الوظيفة في الحلقة", "whitepaper.th_status": "الحالة الفعلية", "whitepaper.rv_mt": "الخزنة", "whitepaper.rv_fn": "حفظ غير متصل لكل مفتاح خاص؛ يوقّع بالوكالة؛ يهاجر المفاتيح عبر QR فقط", "whitepaper.rv_st": "v3.70.0 صدر", "whitepaper.re_mt": "التطبيق", "whitepaper.re_fn": "مراسل اجتماعي سيادي؛ ذاكرة نقية ومشفر من طرف إلى طرف؛ ينفق SPARK بالكيلوبايت", "whitepaper.re_st": "v3.64.7 صدر", "whitepaper.rs_mt": "الوقود", "whitepaper.rs_fn": "يقدّر التعبير؛ يموّل الاحتياطي؛ يربط الاحتياطي والأسواق", "whitepaper.rs_st": "بيع مسبق + IDO", "whitepaper.ra_mt": "البرلمان", "whitepaper.ra_fn": "منظمة DAO تحكمها SBT: ثلاثة مجالس، رتب مرتبطة بالروح، خزينة متعددة التوقيع", "whitepaper.ra_st": "v3.6 · BSC · اكتمل التدقيق · الرئيسية قيد الانتظار", "whitepaper.rh_mt": "جذر الهوية", "whitepaper.rh_fn": "هويات متوازية مشتقة من DID رئيسي: اشتقاق 4 سياقات، مسار مزدوج للائتمان والقيمة، ومستوى ميثاق الذكاء الاصطناعي", "whitepaper.rh_st": "نسخة تجريبية مغلقة M10", "whitepaper.rig_mt": "الدماغ", "whitepaper.rig_fn": "ذكاء اصطناعي على مستوى العقدة يفكر بهويته الخاصة", "whitepaper.rig_st": "مرحلة مستقبلية", "whitepaper.ch1_meta": "الاستعارات هي البنية نفسها: <mark class=\"key\">الخزنة لا تلمس الشبكة</mark>، و<mark class=\"key\">البرلمان يحكم عبر SBT مرتبطة بالروح</mark>، و<mark class=\"key\">الدماغ مرخّص لا موثوق</mark>. كل ما يلي قابل للتتبع إلى شيفرة عامة<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>.", "whitepaper.ch2": "البنية: العزل والهوية", "whitepaper.h21": "العزل الفيزيائي كنموذج أمني", "whitepaper.ch2_p1": "قرار الأمان الجذري للحلقة هو <b>الفصل بالفيزياء لا بالسياسة</b>. يشتغل Engine متصلًا ولا يملك أي مفاتيح خاصة؛ يحتفظ Vault بالمفاتيح وهو مبنيّ بـ<mark class=\"key\">لا إذن شبكة إطلاقًا</mark> — بيانه في Android لا يعلن أي إذن إنترنت، فيجعل التسريب مشكلة فيزيائية لا منطقية<sup><a href=\"#cite-3\">[3]</a></sup>. تنتقل طلبات التوقيع من Engine إلى Vault عبر IPC محمي بالتوقيع؛ ولا تنتقل المواد الحساسة بين الأجهزة إلا كأطر QR مشفرة — كاميرا إلى كاميرا، بعزل إجباري<sup><a href=\"#cite-3\">[3]</a></sup>.", "whitepaper.ch2_p2": "الثقة قابلة للتدقيق: وحدات <span class=\"mono\">core/</span> الخاصة بـ Engine (البروتوكول، التشفير، IPC) <b>مطابقة بايتًا ببايت</b> لوحدات Vault، لذا يتحقق التطبيقان من نفس الشيفرة العامة<sup><a href=\"#cite-1\">[1]</a></sup>. الرسائل مشفرة من الطرف إلى الطرف باتفاق مفاتيح ECDH وAES-256-GCM؛ والمرحّل يرى أغلفة ولا يرى نصًا صريحًا أبدًا<sup><a href=\"#cite-1\">[1]</a></sup>.", "whitepaper.h22": "هوية واحدة، أربعة سياقات غير قابل للربط", "whitepaper.ch2_p3": "تشتق Havix أربع هويات فرعية حسب السياق من مفتاح رئيسي واحد عبر HKDF — سياقات عامة وسوق ونفق وويكي<sup><a href=\"#cite-6\">[6]</a></sup>. الاشتقاق غير قابل للربط تشفيريًا: لا يمكن ربط شخصيتك السوقية بمراسلاتك الخاصة. هذا ما يتيح للشخص الواحد أن يكون في آنٍ <mark class=\"key\">مواطنًا في البرلمان وتاجرًا في السوق وخاصًا في الدردشة</mark> — دون ثلاثة حسابات ودون منصة تحمل الربط.", "whitepaper.h23": "ثلاث مستويات، حلقة واحدة", "whitepaper.ch2_li1": "<b>مستوى التطبيق (متصل):</b> Engine — مواجه للمستخدم، بلا مفاتيح، ذاكرة نقية. الرسائل موجودة في الرام فقط؛ وسطح هجوم المصادرة صفر تقريبًا.", "whitepaper.ch2_li2": "<b>مستوى الحفظ (غير متصل):</b> Vault — متاجر مفاتيح مُحكمة خلف المقاييس الحيوية، ولا تصدير إلا عبر QR.", "whitepaper.ch2_li3": "<b>مستوى التنسيق (نظير لنظير خارج السلسلة):</b> Havix — اشتقاق الهوية، سجلات السمعة/الائتمان، التحكيم، والميثاق الذي يرخّص الذكاء الاصطناعي<sup><a href=\"#cite-6\">[6]</a></sup>.", "whitepaper.ch2_li4": "<b>مستوى التسوية (على السلسلة):</b> Aether على سلسلة BNB الذكية — الحوكمة والخزينة والتنفيذ بتوقيت زمني، محكومًا بدرجة SBT مرتبطة بالروح لا بعرض رمز قابل للتحويل<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch2_p4": "خارطة طريق Havix نفسها تبلور هذا كمكدس من ثلاث طبقات — أساس الشبكة (L0)، والتنفيذ المعرفي (L1، Germ)، والحوكمة على السلسلة (L2، Aether) — مع فرض DID رباعي السياقات للفصل التشفيري بين الطبقات<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch3": "الأعضاء الأربعة", "whitepaper.h31": "Vault — الخزنة", "whitepaper.note31": "v3.70.0 · صدر", "whitepaper.ch3_p1": "مخزن مفاتيح غير متصل عام، وليس ملحقًا لـ Engine: يمكنه حفظ مفاتيح أي تطبيق متوافق. الآلية: لا إذن شبكة؛ مخازن مفاتيح مُحكمة في TEE؛ توقيع ببوابة بيومترية (مدعوم بـ StrongBox حيث يتوفر)؛ حفظ محفظة SPARK — الرصيد يعيش كسلسلة صفقات قابلة للإضافة فقط موقّعة داخل العالم الآمن، ونقل المحفظة ينقل الرصيد كله كصفقة تأسيس إلى جهاز جديد؛ هجرة إلى عتاد جديد عبر QR فقط، ولا يدخل المفتاح الخاص أي مكدس شبكة أبدًا<sup><a href=\"#cite-3\">[3]</a></sup>. منذ v3.40 يصل Engine إلى Vault عبر قناة IPC مباشرة Binder محمية بالتوقيع — حوارات القفز بين التطبيقات القديمة اختفت<sup><a href=\"#cite-3\">[3]</a></sup>.", "whitepaper.ch3_p2": "نقطة دخول السوق للحلقة كلها: مراسل اجتماعي سيادي بهندسة ذاكرة نقية، ورسائل جماعية، واقتصاد تعبير من 60 رمزًا تعبيريًا، وملفات DID<sup><a href=\"#cite-1\">[1]</a></sup>. محركه الاقتصادي محدد أصلًا في المستودع: <mark class=\"key\">الكيلوبايت الواحد يكلف عشرة SPARK</mark> — كل رسالة تُقاس بحجمها UTF-8 وتُقرَّب لأعلى، بحد أدنى عشرة SPARK لكل رسالة؛ دعم وقود يومي قدره 1,000 SPARK (متكرر متطابق لكل يوم تقويمي، تحكمه السجلات الموثوقة، ومشروط بهوية Vault مرتبطة)؛ يعبّئ المستخدمون الثقيلون من محفظة<sup><a href=\"#cite-2\">[2]</a></sup>. رصيد المحفظة ليس رقمًا مخزّنًا: إنه اشتقاق سلسلة صفقات قابلة للإضافة فقط موقّعة من مفتاح المحفظة الذي تحفظه Vault — كل تغيّر في الرصيد، دون استثناء، صفقة موقّعة<sup><a href=\"#cite-2\">[2]</a></sup>. الخصم المسبق من جانب العميل مطبّق؛ وخدمة spark-ledger مستقلة تسوّي الأرصدة من جانب الخادم<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.h33": "Aether — البرلمان", "whitepaper.note33": "v3.6 · BSC · اكتمل التدقيق · الرئيسية قيد الانتظار", "whitepaper.ch3_p3": "نواة DAO تحكمها SBT على سلسلة BNB الذكية. الوزن يُكسَب لا يُشترى: يسكّ AetherRing 14 مرتبة سولباوند غير قابلة للتحويل؛ وتدقق ثلاثة مجالس (المجلس والبرلمان والشيوخ) مع استفتاء المواطنين بعضها بعضًا عبر دورة حياة اقتراح من 7 مراحل مع حق نقض للشيوخ؛ والخزينة توقيع ثلاثي خماسي Safe تنفذ استدعاءات موقوتة<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>. التوتر التصميمي المتعمد: <mark class=\"key\">الحوكمة مرتبطة بالروح (SBT) بينما الوقود أصل حقيقي مصدر</mark> — يمكن للحيتان شراء $SPARK، لكن $SPARK يشتري رسائل لا أصواتًا. عقد واحد مختلف: AetherDonation قناة <b>خيرية خارجية</b> (نصائح USDC للصالح العام) ومستقل عن اقتصاد الحلقة.", "whitepaper.h34": "Havix — جذر الهوية", "whitepaper.note34": "تم التحقق · في وضع الاستعداد", "whitepaper.ch3_p4": "شبكة التنسيق أسفل الحلقة: ثماني وحدات (الهوية، أنواع الرسائل، الائتمان، الضمان، الويكي، التحكيم، السوق، تشغيل عقد s-node)، و1,174 اختبارًا ناجحًا (MVP 980 + تجربة تحقق 194، وخط أساس مراجعة M10)، وبرنامج مراجعة من جولتين — أغلقت M9 كل نتائجها الـ15، بينما أظهر تدقيق M10 العميق 52 أخرى (5 P0 + 15 P1 + 32 P2) عولجت P0/P1 قبل النسخة التجريبية المغلقة<sup><a href=\"#cite-6\">[6]</a></sup>. مستو ميثاقها هو ما يضع الذكاء الاصطناعي على أساس قانوني لا سحري: العمليات الروتينية تنفذ تلقائيًا مع إيصالات؛ <mark class=\"key\">العمليات الحمراء تُوجَّه فيزيائيًا إلى تصويت بشري على السلسلة</mark>. مخزن الميثاق والمعترض مقرران كمسار عمل M11<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.h35": "Germ — الدماغ، لاحقًا", "whitepaper.ch3_p5": "Germ هي طبقة الذكاء الاصطناعي على مستوى العقدة: ذكاء يفكر بهوياته الأربعة المرتبطة بالسياق على شبكة Havix. وهو مؤجَّل عمدًا — <mark class=\"key\">دخول السوق اليوم هو Engine</mark>؛ ويصل الدماغ حين توجد في الحلقة مستخدمون يستحقون الرعاية. في هذه الوثيقة لا يظهر Germ إلا حيث يجب على الاقتصاد أن يبقي له مساحة (ذكاء احتياطي، §5).", "whitepaper.ch4": "اقتصاديات رمز SPARK", "whitepaper.h41": "المنفعة: وقود بفيزياء خلفه", "whitepaper.ch4_p1": "SPARK أصل <b>قياسي</b>. في Engine، كل كيلوبايت يكلف 10 SPARK — يُقاس بحجم الرسالة ويُقرَّب لأعلى، بحد أدنى 10 لكل رسالة — العداد في البروتوكول لا في شروط الخدمة<sup><a href=\"#cite-2\">[2]</a></sup>. الميزانيات مشتقة من خط أساس حقيقي 100&nbsp;ميجابايت/ثانية للمرحّلات: أغلفة نصوص حتى 40&nbsp;KB ووسائط حتى 48&nbsp;KB وسقف إطار صلب 128&nbsp;KB ومجموعات محدودة بـ200<sup><a href=\"#cite-1\">[1]</a></sup>. لأن كل بايت تعبيري يكلف وقودًا، فللرسائل المزعجة تكلفة حدّية ويبقى الكلام حرًا.", "whitepaper.ch4_li1": "<b>الحصول:</b> دعم وقود يومي (1,000 SPARK لكل يوم تقويمي، متطابق، مشروط بهوية Vault مرتبطة<sup><a href=\"#cite-2\">[2]</a></sup>)، أو تعبئة المحفظة<sup><a href=\"#cite-2\">[2]</a></sup>، أو شراء من السوق بعد TGE.", "whitepaper.ch4_li2": "<b>النفقات:</b> وقود الرسائل؛ ميزانيات المجموعات والوسائط؛ استخدام تطبيقات SDK.", "whitepaper.ch4_li3": "<b>الإمساك:</b> تحتفظ خزينة DAO بـ SPARK كاحتياطي طويل الأجل — الطلب من الاستخدام الحقيقي يتجمع لكل حامل بشكل متماثل.", "whitepaper.ch4_note": "◇ معالم التصميم (مدد الاستحقاق، قفل LP، توجيه الرسوم، تراجع المخصصات) قيم افتراضية موصى بها لهذه المسودة؛ يُؤكَّد كل منها أو يُعدَّل بالحوكمة قبل فتح البيع المسبق. معدلات القياس على السلسلة (1 KB = 10 SPARK، حد أدنى 10 للرسالة؛ 1,000 دعم وقود يومي لكل يوم تقويمي) مثبتة في مواصفات Engine<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.h42": "مرحلتان للأصل نفسه — سجل قياس، ثم معروض ثابت", "whitepaper.ch4_p2": "يُطلق SPARK على مرحلتين متعمدتين، والتسلسل هو التصميم نفسه. <b>المرحلة أ — سجل القياس (يعمل اليوم):</b> داخل برمجية Engine الصادرة، يوجد SPARK كسجل متسلسل التجزئة خارج السلسلة. كل جهاز يصكّ <b>1,000 لكل يوم تقويمي</b> عبر دعم وقود موقّع مشتركًا من Vault — دفاعات مكافحة سيبيل قيد الإنتاج أصلًا: مرساة جهاز TEE/DRM، وإلغاء تكرار يومي على مستوى المرحّل لتمدادات أجهزة غير قابلة للربط، وقائمة بيضاء للمبالغ تفرضها بوابة التوقيع. أرصدة المرحلة أ <mark class=\"key\">غير قابلة للتحويل ولا للتداول ولا للاستبدال</mark> — اليوم هي حصص وليست أوراقًا مالية.", "whitepaper.ch4_p3": "<b>المرحلة ب — ربط TGE (مخطط):</b> يبدأ سريان <b>المعروض الثابت 1,000T</b> عند TGE. يجمع العرض الأولي شرائح §4.3 من البيع المسبق والـIDO والسيولة والاحتياطي مع ربط أرصدة المرحلة أ عبر لقطة — ضمن شريحة حوافز المجتمع — معاملات التحويل المحددة قيم افتراضية ◇ تؤكدها الحوكمة قبل فتح البيع المسبق. بعد TGE، يتداول SPARK بحرية، <b>بما يشمل أزواج USDC مفتوحة وأزواج عملات مستقرة أخرى</b>. قناة التحويل غير مبنية عمدًا اليوم: تثبيت الجهاز وإلغاء التكرار اليومي وإدراج المبالغ في القائمة البيضاء يجب أن توجد <i>قبل</i> وجود خزنة تُدافع عنها، ليتخرج هذا دفاع من تدبير الحصص إلى بوابات الخزنة يوم يفتح قابلية الاستبدال.", "whitepaper.h43": "المعروض والتوزيع", "whitepaper.ch4_p4": "المعروض الإجمالي مثبت عند <b>1,000T SPARK (1,000,000,000,000,000 — ألف ترليون)</b>. يتبع التوزيع التقسيم 10 / 20 / 10 / 50 / 10: بيع مسبق، وIDO، وسيولة DEX، واحتياطي DAO، وحوافز مجتمع. <mark class=\"key\">لا شريحة فريق، ولا توزيع داخلي، ولا شريحة تسويق</mark> — صعود الفريق في احتياطي 50% الذي يشاركه مع DAO، ولا يُفتح إلا عبر حوكمة عامة، ويُقيَّد بالميثاق بحد أقصى 5% من الاحتياطي سنويًا.", "whitepaper.fig1": "الشكل 1 — توزيع SPARK عند TGE (مُحسَّن: 10 شرائح، 5 دفعات)", "whitepaper.fig1_sub": "إجمالي المعروض 1,000T (1,000,000,000,000,000). البيع المسبق يقسم 2.5% عند TGE + 7.5% استحقاق؛ والـIDO يقسم 5% عند TGE + 15% استحقاق (كلتا الدفعتين: 25% عند TGE، ثم خطّي على 9 أشهر)؛ والتقسيمات الفرعية للاحتياطي قيم افتراضية مقيدة بالميثاق ◇ مع سقف إطلاق ≤5%/سنة — الاحتياطي نفسه لا فتح تقويمي له.", "whitepaper.th_tranche": "الدفعة", "whitepaper.th_share": "الحصة", "whitepaper.th_amount": "المبلغ", "whitepaper.th_unlock": "الفتح", "vault.foot_home": "الرئيسية", "whitepaper.ch4b": "الإطلاق ثنائي المسار", "whitepaper.h44": "المرحلة 1 — البيع المسبق (10%)", "whitepaper.h45": "المرحلة 2 — IDO (20%)", "whitepaper.h46": "السيولة و DEX (10%)", "whitepaper.h47": "جدول الفتح", "whitepaper.h48": "الضمانات والامتثال", "whitepaper.h32": "Engine — التطبيق", "whitepaper.note32": "v3.64.7 · صدر", "whitepaper.ch5": "حوكمة الاحتياطي", "whitepaper.ch6": "خارطة الطريق إلى TGE", "whitepaper.ch7": "المخاطر وسياسة إخلاء المسؤولية", "whitepaper.fig2": "الشكل 2 — المعروض المتداول بعد TGE", "whitepaper.m1": "بيع مسبق — قائمة بيضاء · سقف $500", "whitepaper.m2": "IDO — LBP · 3–7 أيام", "whitepaper.m3": "سيولة — تُحقن عند TGE", "whitepaper.m4": "حوافز المجتمع — الإحالة والتفعيل", "whitepaper.m5": "احتياطي DAO — بوابة حوكمة · ≤5%/سنة", "whitepaper.tl_now_t": "الحلقة على أرض الواقع", "whitepaper.tltge_t": "حدث إنشاء الرمز", "whitepaper.tl01_t": "القائمة البيضاء والمعايير نهائية", "whitepaper.tl02_t": "نافذة البيع المسبق", "whitepaper.tl03_t": "IDO على منصة LBP", "whitepaper.tl9_t": "اكتمال العرض · DAO يتولى الاحتياطي", "whitepaper.tll1_t": "Germ، لاحقًا", "whitepaper.src": "المصادر", "whitepaper.src6": "eneatlnc-cell، مستودع Havix — شبكة هويات متوازية: 8 وحدات، و1,174 اختبارًا (خط أساس مراجعة M10)، و15 نتيجة مراجعة مُغلقة.", "whitepaper.src1": "eneatlnc-cell، Engine 3.0 — نسخة المراجعة العامة لمكدس بروتوكول E2EE (core-crypto وcore-protocol وcore-ipc؛ AGPL-3.0).", "whitepaper.src2": "Engine، سجل هندسة SparkEconomy (داخلي) — 1 KB = 10 SPARK (حد أدنى 10 للرسالة)، ودعم وقود يومي 1,000 لكل يوم تقويمي، ومحفظة SPARK بمعاملات موقّعة (v3.37+)، وتعبئة المحفظة، وخطة خدمة spark-ledger.", "whitepaper.src3": "eneatlnc-cell، Engine 3.0 — core-ipc: عقد توقيع Engine↔Vault خلف مخزن المفاتيح غير المتصل (لا إذن شبكة، توقيع بيومتري، هجرة QR).", "whitepaper.src4": "eneatlnc-cell، مستودع Aether — نواة DAO تحكمها SBT: AetherRing وGovernance وElection وخزينة Safe.", "whitepaper.src5": "Aether، docs/TECHNICAL_WHITEPAPER.md — ثلاثة مجالس، دورة حياة من 7 مراحل، حق نقض الشيوخ، توازن المجالس/المواطنين.", "whitepaper.src7": "Havix، NEXT-STEPS.md — مكدس من ثلاث طبقات L0/L1/L2، وخطة مخزن ميثاق M11 ومعترض الخط الأحمر.", "whitepaper.foot_copy": "© <span class=\"yr\">2026</span> SparkLoop · وثيقة v1.0 مسودة", "whitepaper.foot_cta": "انضم إلى القائمة البيضاء للبيع المسبق", "whitepaper.tr_presale_amt": "100T", "whitepaper.tr_presale_t": "بيع مسبق — قائمة بيضاء", "whitepaper.tr_tge_amt": "25T", "whitepaper.tr_tge_t": "└ فتح TGE", "whitepaper.tr_tge_un": "متداول عند TGE", "whitepaper.tr_9m_amt": "75T", "whitepaper.tr_9m_t": "└ استحقاق 9 أشهر", "whitepaper.tr_9m_un": "خطّي، الأشهر 1–9", "whitepaper.tr_a_un": "25% عند TGE ◇، ثم خطّي على 9 أشهر ◇", "whitepaper.tr_b_un": "25% عند TGE ◇، ثم خطّي على 9 أشهر ◇", "whitepaper.tr_ido_amt": "200T", "whitepaper.tr_ido_t": "IDO — جولة LBP عامة", "whitepaper.tr_tge2_amt": "50T", "whitepaper.tr_tge2_t": "└ فتح TGE", "whitepaper.tr_9m2_amt": "150T", "whitepaper.tr_9m2_t": "└ استحقاق 9 أشهر", "whitepaper.tr_dex_amt": "100T", "whitepaper.tr_dex_t": "سيولة DEX", "whitepaper.tr_dex_un": "تُحقن في المجمع عند TGE · قفل LP 12 شهرًا ◇", "whitepaper.tr_dao_amt": "500T", "whitepaper.tr_dao_t": "احتياطي DAO", "whitepaper.tr_dao_un": "لا جدول — يُطلق فقط بموجب اقتراح Aether · سقف الميثاق ≤5%/سنة", "whitepaper.tr_comm_amt": "100T", "whitepaper.tr_comm_t": "حوافز المجتمع", "whitepaper.tr_comm_un": "مكافآت إحالة + منح تفعيل · تُسوّى حسب البرنامج", "whitepaper.tr_fuel_amt": "150T", "whitepaper.tr_fuel_t": "└ دعم وقود Engine", "whitepaper.tr_fuel_un": "إعداد الميثاق ◇ — دورات الدعم", "whitepaper.tr_relay_amt": "100T", "whitepaper.tr_relay_t": "└ المرحّلات والبنية التحتية", "whitepaper.tr_relay_un": "إعداد الميثاق ◇ — مرحّلات وs-node", "whitepaper.tr_eco_amt": "150T", "whitepaper.tr_eco_t": "└ منح النظام البيئي", "whitepaper.tr_eco_un": "إعداد الميثاق ◇ — تطبيقات ومرحّلات وأدوات", "whitepaper.tr_ai_amt": "100T", "whitepaper.tr_ai_t": "└ سيولة الذكاء الاصطناعي ووقفية", "whitepaper.tr_ai_un": "إعداد الميثاق ◇ — حدود الذكاء الاصطناعي", "whitepaper.ch4b_p1": "جوهر الإطلاق هو <b>بيع مسبق وIDO بالتوازي، بإيقاعين مختلفين</b>: البيع المسبق يستهدف المجتمع الأساسي؛ والـIDO يواجه الجمهور. <mark class=\"key\">البيع المسبق يبني الأساس؛ والـIDO يفتح السوق.</mark>", "whitepaper.ch4b_li1": "<b>الجمهور:</b> المساهمون الأساسيون الأوائل وأعضاء المجتمع النشطون فقط. تُجمع عناوين المحافظ في قائمة بيضاء مسبقًا؛ ويُعلن وقت البدء للقائمة أولًا.", "whitepaper.ch4b_li2": "<b>مكافحة الحيتان:</b> <mark class=\"key\">سقف صارم $500 لكل محفظة</mark>.", "whitepaper.ch4b_li3": "<b>الشروط:</b> ادفع بـ USDT أو BNB بسعر منخفض ثابت؛ 25% تُفتح عند TGE، والبقية تستحق خطيًا على 9 أشهر ◇.", "whitepaper.ch4b_li4": "<b>التنفيذ:</b> عند فتح النافذة، تتصل المحافظ المدرجة في القائمة البيضاء بالموقع الرسمي وتكتتب ضمن السقف.", "whitepaper.ch4b2_li1": "<b>المنصة:</b> منصة إطلاق LBP من طراز Fjord Foundry — يبدأ السعر عاليًا ويتناقص حتى تلحق به الطلبات، ما <mark class=\"key\">يزيل أفضلية الاقتناص</mark>؛ لا قائمة بيضاء ولا أفضلية للكتلة الأولى.", "whitepaper.ch4b2_li2": "<b>المعايير:</b> تحقق ثلاثي من عنوان الرمز قبل تمويل المجمع (لا رجوع)؛ دفع بـ USDT أو BNB؛ نافذة 3–7 أيام؛ حدّان أدنى وأقصى لكل محفظة؛ سعر بدء أعلى من سعر البيع المسبق.", "whitepaper.ch4b2_li3": "<b>التوزيع:</b> 25% من حصة كل محفظة قابلة للمطالبة عند TGE، والبقية تستحق خطيًا على 9 أشهر ◇؛ والعائدات تذهب مباشرة إلى توقيع البروتوكول المتعدد.", "whitepaper.ch4b2_li4": "<b>المحاسبة:</b> بعد إغلاق النافذة، تُطابَق قائمة الاكتتاب والمبالغ وتُنشر قبل التوزيع.", "whitepaper.ch4b3_note": "تُنشر العناوين على صفحة Spark لحظة النشر. قبل تلك اللحظة، أي عنوان يدّعي أنه SPARK هو احتيال.", "whitepaper.ch4b3_p1": "عند TGE تُحقن شريحة السيولة مجمع DEX مقترنة بـ BNB. يُوصى بإصدار SPARK كرمز BEP-20 على سلسلة BNB ◇ — بما يطابق مسارات الدفع USDT/BNB للجولتين — مع نشر خزينة Aether وحوكمتها على نفس سلسلة BNB الذكية<sup><a href=\"#cite-4\">[4]</a></sup>، فتسوَّى عمليات الاحتياطي محليًا دون أي جسر عابر للسلسلة<sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch4b4_p1": "الوعد البنيوي هو <mark class=\"key\">سقف عائم صارم</mark>: لا يستطيع التقويم فتح أكثر من 40% (بيع مسبق + IDO + LP)؛ وشريحة الحوافز 10% لا تدفع إلا مقابل إحالات وتفعيلات موثقة؛ والاحتياطي 50% لا يتحرك إلا عبر اقتراح عام قابل للنقض، مع تقييد الميثاق للإطلاق بـ<b>≤5% من الاحتياطي سنويًا</b>. يعرف المشترون الأوائل بالضبط ما هو أقصى عرض متداول.", "whitepaper.ch5_p1": "الاحتياطي 50% ليس محفظة خزانة — بل <b>كائن دستوري</b>. الحفظ في توقيع ثلاثي خماسي Safe؛ وكل حركة تتطلب اقتراحًا عبر دورة حياة Aether من 7 مراحل، وتعبر نافذة نقض الشيوخ، وتنفذ عبر القفل الزمني<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>. الوزن في تلك العملية مرتبط بالروح ويُكتسب — 14 مرتبة AetherRing لا تُشترى ولا تُنقل<sup><a href=\"#cite-4\">[4]</a></sup>.", "whitepaper.ch5_p2": "استخدامات الاحتياطي محدودة بالميثاق: دورات دعم مستخدمين لوقود Engine، وتمويل المرحّلات والبنية التحتية، ومنح النظام البيئي، ومع وجود Germ — إدارة سيولة من ذكاء مرخّص ضمن حدود صارمة، مع عودة الخطوط الحمراء إلى تصويت بشري<sup><a href=\"#cite-6\">[6]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>. ويحدد الميثاق كذلك <mark class=\"key\">سقف معدل إطلاق ≤5% من الاحتياطي سنويًا</mark> — وعدٌ قابل للحساب لا تصرف اختياري: حتى الخزينة المسيطر عليها كليًا لا يمكنها سحب الاحتياطي أسرع من واحد على عشرين سنويًا. تصميم التوازن متعمد: <mark class=\"key\">المجالس والمواطنون يحمل كلٌّ نحو نصف وزن التصويت</mark>، فلا تستطيع المؤسسة ولا الجمهور إنفاق الاحتياطي وحدها<sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch7_disc": "<b>إخلاء المسؤولية.</b> تصف هذه الوثيقة مشروع برمجيات مفتوح المصدر ومصدر وقوده. إنها ليست نصيحة استثمارية، وليست عرضًا لبيع أوراق مالية، وليست وعدًا بعوائد. المعايير المعلَّمة ◇ قيم افتراضية قابلة للتغيير قبل الإطلاق. لا تسويق «ثق بي» في هذه الحلقة: اقرأ المستودعات.", "whitepaper.ch7_li1": "<b>خطر التنفيذ:</b> نشر Aether على الشبكة الرئيسية، ومخزن ميثاق M11، وخدمة spark-ledger مكونات غير مكتملة يعتمد عليها تسلسل TGE<sup><a href=\"#cite-2\">[2]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch7_li2": "<b>خطر عابر السلاسل:</b> مخفف بالتصميم — SPARK وحوكمة/خزينة Aether تُنشر على نفس سلسلة BNB الذكية ◇، فتسوَّى عمليات الاحتياطي محليًا دون أي اعتماد على جسر.", "whitepaper.ch7_li3": "<b>خطر السوق:</b> يكتشف LBP السعر بصدق — أي أنه قد يكتشفه نزولًا. التسعير المنخفض الثابت للبيع المسبق يعوّض الثقة المبكرة لكنه لا يضمن عوائد.", "whitepaper.ch7_li4": "<b>خطر تنظيمي:</b> تواجه عمليات إطلاق الرموز تنظيمًا متباينًا؛ وقد تُفرض قيود حسب الولاية القضائية؛ والمراجعة القانونية شرط مسبق لا مجرد إجراء شكلي.", "whitepaper.ch7_li5": "<b>خطر العقود الذكية:</b> تقلل المراجعات المخاطر لكنها لا تزيلها أبدًا؛ تفاعل فقط مع العناوين المنشورة في الموقع الرسمي.", "whitepaper.fig2_sub": "العرض المتداول: 17.5% عند TGE (2.5% بيع مسبق + 5% IDO + 10% LP)، يرتفع 2.5% شهريًا مع استحقاق الدفعتين ويبلغ سقفه التقويمي 40% عند الشهر التاسع. شريحة الحوافز 10% تُسوّى حسب البرنامج؛ والـ50% المتبقية تتحرك بالحوكمة فقط، بحد ميثاقي ≤5%/سنة.", "whitepaper.tl_now_d": "صدر Engine v3.64.7 وVault v3.70.0 — قناة Binder IPC المباشرة ومحفظة SPARK للمعاملات الموقّعة تعملان، والنسختان محصّنتان بتشويش R8، ودعم الوقود اليومي مفصول التكرار في المرحّل بتجزئة جهاز-يوم غير قابلة للربط؛ Havix في نسخة تجريبية مغلقة بعد إغلاق 15 نتيجة مراجعة؛ وAether v3.6 على BSC (إصلاحات المراجعة مغلقة) في انتظار النشر الرئيسي<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>. القائمة البيضاء للبيع المسبق مفتوحة.", "whitepaper.tl01_d": "يُجمع عناوين المحافظ؛ ويُؤكَّد سعر البيع المسبق وحدود IDO ومعالم الاستحقاق وقفل LP؛ وتُراجَع العقود وتُنشر العناوين.", "whitepaper.tl02_d": "تكتتب محافظ القائمة البيضاء بـ USDT/BNB داخل سقف $500 بالسعر المنخفض الثابت.", "whitepaper.tl03_d": "جولة عامة من 3–7 أيام؛ السعر يكتشف نفسه؛ وتُنشر التسوية عند الإغلاق.", "whitepaper.tl9_d": "اكتمال استحقاق البيع المسبق والـIDO — يبلغ العروض التقويمي سقفه 40%؛ وتتولى حوكمة Aether الرئيسية ولاية الاحتياطي بالكامل، مع إطلاق بسقف ميثاقي ≤5%/سنة.", "whitepaper.tltge_d": "تصل توزيعات البيع المسبق 25% والـIDO 25% الأولية إلى المحافظ؛ وتُحقن شريحة السيولة 10% مجمع DEX؛ ويُطلق spark-ledger لتسوية Engine<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.tll1_d": "ينضم ذكاء مستوى العقدة إلى الشبكة وفق الميثاق — يصل الدماغ ليعنى بحلقة تنبض أصلًا<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch4b5_li1": "<b>الأمان:</b> يجب أن تحمل عقود الرمز والبيع المسبق وLBP تدقيقًا من شركة معترف بها قبل قبول أي أموال؛ وتُنشر التقارير إلى جانب العناوين.", "whitepaper.ch4b5_li2": "<b>الشفافية:</b> تُعلن عناوين وقواعد عقود البيع المسبق والـIDO قبل فتح كل نافذة؛ وتُنشر تسوية الاكتتاب قبل توزيع TGE.", "whitepaper.ch4b5_li3": "<b>مكافحة الروبوتات:</b> تراجع سعر LBP يهزم الاقتناص؛ وحدود كل محفظة ($500 بيع مسبق؛ IDO أدنى/أقصى) تحدّ التركيز؛ وقد تُطبق حدود انزلاق ديناميكية على عقد البيع المسبق ◇.", "whitepaper.ch4b5_li4": "<b>قانوني:</b> الإطلاق قيد مراجعة المستشار القانوني للمناطق القضائية المعنية؛ وقد يُقيَّد المشاركة حيثما يلزم. لا شيء هنا عرضٌ للأوراق المالية."},
  es: {"vault.nav_home": "Inicio", "vault.nav_rewards": "Recompensas", "vault.chip": "sin conexión · aislado · soberano", "vault.h1_a": "Una caja fuerte que", "vault.h1_grad": "nunca habla con la red", "vault.hero_desc": "<strong>Vault</strong> es la caja fuerte offline universal para apps de clase Engine. Almacena claves privadas y firmas de inicio de sesión con <strong>permiso de Internet cero</strong>, las sella en el silicio seguro del teléfono, firma con tu huella y mueve claves a hardware nuevo solo mediante luz — un código QR. No es «prometemos no conectar», <strong>no puede conectar</strong>.", "vault.btn_ceremony": "▶ Prueba la ceremonia de firma", "vault.btn_migration": "⟳ Migración de claves", "vault.btn_audit": "↗ Auditoría de la capa criptográfica", "vault.stat_internet": "permisos de INTERNET en el manifiesto", "vault.stat_tee": "claves selladas en hardware", "vault.stat_wallet": "custodia y traspaso de wallet", "vault.stat_qr": "la única salida de una clave", "vault.tag_demo": "RECREADO DEL FILME DEMO", "vault.title_demo": "Ten la caja fuerte en tus manos", "vault.sub_demo": "A la izquierda, la app real de Vault: la vista de wallet SPARK — un saldo que no es más que la suma de transacciones firmadas, con el traspaso a un toque de la barra inferior. En el medio, la página de estado que lista cada clave que guarda — pulsa <b>Firmar</b> y mira la ceremonia biométrica. A la derecha, lo que el teléfono reporta sobre su propia aislamiento.", "vault.wallet_title": "Wallet SPARK", "vault.wallet_sub": "custodia Vault · cadena de tx firmadas", "vault.wallet_balsub": "saldo = Σ transacciones firmadas", "vault.wallet_handover": "⇄ Traspaso de wallet", "vault.wallet_keys": "Claves: 3", "vault.vs_title": "Claves protegidas", "vault.vs_fingerprint": "huella", "vault.vs_algorithm": "algoritmo", "vault.vs_sealed": "sellado", "vault.vs_sealed_val": "Keystore TEE · AES-256-GCM", "vault.vs_lastreq": "última solicitud", "vault.vs_waiting": "esperando…", "vault.vs_sign": "Firmar solicitud de Engine", "vault.vs_migrate": "⟳ Migrar a un dispositivo nuevo", "vault.bio_touch": "Toca el sensor", "vault.bio_title": "BiometricPrompt", "vault.bio_desc": "La clave nunca sale del TEE — firma dentro del hardware seguro.", "vault.console_head": "adb shell — autocomprobación de aislamiento", "vault.sim_caption": "<b>Cada evento de arriba es local.</b> La consola no tiene nada que reportar de la red — porque no la hay.", "vault.tag_guards": "QUÉ PROTEGE", "vault.title_guards_a": "Un solo trabajo: ser el", "vault.title_guards_grad": "caja fuerte de cada app soberana", "vault.sub_guards": "Vault es agnóstica por diseño. Cualquier cosa con forma de Engine — una app que quiere vida online con claves offline — puede delegar su identidad en la caja fuerte.", "vault.card1_t": "Claves privadas de apps", "vault.card1_d": "Identidades ECDSA P-256 generadas por apps como Engine, selladas al llegar.", "vault.card2_t": "Firmas de acceso y de wallet", "vault.card2_d": "Códigos de acceso desafío-respuesta y transacciones de wallet SPARK — firmadas dentro de la caja fuerte, nunca almacenadas online. Cada cambio de saldo es una transacción firmada en una cadena de solo-append.", "vault.card3_t": "Vínculos de migración de dispositivo", "vault.card3_d": "Registros de re-vinculación firmados que mueven tu identidad a hardware nuevo sin backup en la nube.", "vault.card4_t": "Directorio de huellas", "vault.card4_d": "Un registro local de cada clave protegida, su huella y estado de sellado — visible de un vistazo.", "vault.card5_t": "Nada más", "vault.card5_d": "Sin navegación, sin sincronización, sin anuncios, sin telemetría. Una caja fuerte con pantalla, no una app de smartphone.", "vault.card6_t": "Desbloqueo solo biométrico", "vault.card6_d": "Cada desellado pasa por BiometricPrompt con una ventana de frescura de ±120 s — protección de reproducción basada en reloj.", "vault.tag_ceremony": "CÓMO FIRMA OFFLINE UNA APP ONLINE", "vault.title_ceremony_a": "La clave firma.", "vault.title_ceremony_grad": "La clave nunca se va.", "vault.pl1": "Engine necesita una firma", "vault.pl2": "Solicitud IPC + desafío", "vault.pl3": "BiometricPrompt", "vault.pl4": "TEE desella y firma", "vault.pl5": "callback firmado", "vault.pl6": "Engine verifica sig + Δt&lt;120s", "vault.co_tag": "POR QUÉ IMPORTA LA VENTANA DE ±120s", "vault.co_text": "La firma del callback cubre <b>sessionId ‖ status ‖ timestamp</b>. Incluso un callback robado no puede reproducirse minutos después — el reloj es parte de la prueba. El relay nunca ve la clave; Engine nunca la tiene; <b>solo el TEE la tiene.</b>", "vault.tag_migration": "TELÉFONO NUEVO, MISMA IDENTIDAD", "vault.title_mig_a": "Mudándose a través de", "vault.title_mig_grad": "un haz de luz", "vault.sub_migration": "Las claves privadas son lo único que nunca debes confiar a una nube. Cuando tu hardware cambia, Vault mueve tu identidad entre dispositivos pantalla a pantalla — recórrelo abajo.", "vault.migprev": "Anterior", "vault.mignext": "Siguiente", "vault.flag_t": "FLAG_SECURE", "vault.flag_d": "La pantalla del QR pone en negro capturas y grabaciones. Solo queda el ataque por hombro.", "vault.payload_t": "carga cifrada", "vault.payload_d": "El URI de vínculo lleva una carga de sesión cifrada — la clave privada bruta nunca aparece en ningún URI.", "vault.burn_t": "Quemar tras el vínculo", "vault.burn_d": "Engine llama a convertBoundToPublicKeyOnly() — su copia de clave privada se borra en cuanto Vault toma el control.", "vault.title_compare": "¿Dónde duermen las claves esta noche?", "vault.th_storage": "Modelo de almacenamiento", "vault.th_network": "Alcance de red", "vault.th_extraction": "Riesgo de extracción", "vault.th_migration": "Ruta de migración", "vault.tr_ext_t": "Wallet de extensión de navegador", "vault.tr_ext_reach": "siempre online", "vault.tr_ext_risk": "alto — memoria y disco legibles", "vault.tr_ext_mig": "frase semilla en papel", "vault.tr_hot_t": "Servidor caliente / de custodia", "vault.tr_hot_reach": "superficie de ataque 24/7", "vault.tr_hot_risk": "sistémico — un brecha, todas las claves", "vault.tr_hot_mig": "confiar en el operador", "vault.tr_cloud_t": "Backup de claves en la nube", "vault.tr_cloud_reach": "sincronizado por diseño", "vault.tr_cloud_risk": "comprometer cuenta = comprometer clave", "vault.tr_cloud_mig": "re-descargar", "vault.tr_vault_reach": "sin permiso de INTERNET", "vault.tr_vault_risk": "silicio TEE + puerta biométrica", "vault.tr_vault_mig": "canal QR de luz, re-vínculo firmado", "vault.co2_tag": "FÍSICA, NO PROMESAS", "vault.co2_text": "Cada fila de esa tabla depende de que alguien se comporte bien. El aislamiento de Vault se declara en el manifiesto de Android y lo impone el SO — <b>un paquete no puede enviarse, así que nunca hace falta una promesa.</b>", "vault.foot_desc": "Una interpretación independiente del bucle eneatlnc-cell. La pila de protocolos E2EE está abierta a auditoría; cada afirmación se remonta a código y whitepapers.", "vault.foot_layers": "Capas", "vault.foot_engine": "social soberano", "vault.foot_vault": "custodia offline", "vault.foot_havix": "L0 · identidad paralela", "vault.foot_spark": "el combustible", "vault.foot_rewards": "política de referidos", "vault.foot_loop": "El bucle Web4", "vault.foot_repos": "Repositorios", "vault.foot_bottom": "claves offline · gobernanza SBT · combustible $SPARK · IA licenciada", "vault.log_settle_pre": "lote medido co-firmado dentro del TEE → tx #", "vault.log_settle_suf": " añadido a la cadena · saldo = Σ tx firmadas", "vault.log_handover": "certificado de traspaso firmado · el saldo completo migra como tx genésis", "vault.log_bio_dismiss": "prompt biométrico descartado", "vault.log_ipc_pre": "solicitud IPC recibida · challenge=0x", "vault.log_ipc_suf": " · esperando biométricos", "vault.sig_result": "✓ firmado · ECDSA P-256 · TEE", "vault.log_bio_ok": "Biométricos ✓ → clave desellada en TEE → firmada en el mundo seguro → re-sellada", "vault.log_callback": "callback verificado: sig(sessionId‖status‖ts) ✓ · Δt &lt; 120s ✓", "vault.mig1_title": "El nuevo dispositivo genera un par de claves nuevo", "vault.mig1_desc": "El nuevo teléfono crea su propia identidad ECDSA P-256 en Engine. Nada se importa por el aire — nunca.", "vault.mig2_title": "La Vault antigua exporta un vínculo de migración", "vault.mig2_desc": "La Vault antigua sella una autorización en un marco QR. FLAG_SECURE deja capturas en negro; la clave nunca sale del TEE.", "vault.mig3_title": "La Vault nueva escanea — solo canal óptico", "vault.mig3_desc": "ML Kit lee el marco por la cámara. La única red implicada es la luz.", "vault.mig4_title": "Identidad re-vinculada a la nueva clave", "vault.mig4_desc": "Un callback de re-vinculación firmado migra tu DID a la clave pública del nuevo dispositivo. Los contactos verifican la huella nueva automáticamente.", "vault.mig5_title": "La custodia SPARK también se traspasa", "vault.mig5_desc": "La Vault antigua firma un certificado de traspaso que termina su cadena con el saldo completo; la nueva lo verifica y continúa el libro con una tx genésis — nunca existe saldo sin firmar.", "vault.mig6_title": "Copia antigua quemada, residuo cero", "vault.mig6_desc": "La Vault antigua borra la clave sellada con sobrescritura cero. Migración completa — ninguna clave tocó Internet.", "vault.log_boot1": "AndroidManifest: uses-permission INTERNET → <b>no encontrado</b> ✓", "vault.log_boot2": "pila de red: inalcanzable · sockets: ninguno · telemetría: ninguna", "vault.log_boot3": "Keystore TEE vivo · claves selladas (AES-256-GCM) · biométricos listos", "vault.log_boot4": "cadena de wallet SPARK armada · anti-replay HWM · traspaso listo", "whitepaper.nav_home": "Inicio", "whitepaper.nav_rewards": "Recompensas", "whitepaper.kicker": "// WHITEPAPER DEL PROYECTO", "whitepaper.chip": "VERSIÓN 1.0 · BORRADOR", "whitepaper.h1": "SPARK <span class=\"grad\">&amp; el bucle de soberanía Web4</span>", "whitepaper.hero_desc": "Cuatro órganos — <strong>Vault</strong>, <strong>Engine</strong>, <strong>Aether</strong>, <strong>Havix</strong> — forman un bucle cerrado, y <strong>SPARK</strong> es el combustible que lo hace girar. La pila de protocolos E2EE está abierta a auditoría; este documento describe la arquitectura construida, la economía de tokens diseñada y el lanzamiento de doble vía: una preventa con lista blanca seguida de un IDO público basado en LBP.", "whitepaper.meta_1": "AGOSTO 2026", "whitepaper.meta_2": "4 REPOSITORIOS · AGPL + APACHE", "whitepaper.meta_3": "LISTA BLANCA DE PREVENTA ABIERTA", "whitepaper.meta_4": "SUMINISTRO 1,000T SPARK", "whitepaper.stat_dao": "reserva DAO — controlada por gobernanza", "whitepaper.stat_tge": "líquido en TGE (incl. 10% LP)", "whitepaper.stat_cap": "límite de preventa por wallet", "whitepaper.stat_kb": "SPARK por kilobyte de mensaje", "whitepaper.abstract": "<b>Resumen.</b> Web3 dio billeteras a los usuarios pero dejó su vida social en servidores. El bucle prototipo Web4 cierra esa brecha con <mark class=\"key\">aislamiento físico</mark>: una app social online (<strong>Engine</strong>) que no guarda claves, una caja fuerte offline (<strong>Vault</strong>) que guarda claves y nunca conecta, un parlamento gobernado por SBT (<strong>Aether</strong>) que deposita la reserva de combustible, y una red de identidad paralela (<strong>Havix</strong>) — derivada de master-DID, operando una economía dual de crédito y valor — que licencia la IA bajo una constitución viva. <strong>$SPARK</strong> es el único activo emitido que mide la expresión en la app, dota la reserva DAO y fluye entre ellos — combustible del bucle, nunca un voto. Este whitepaper documenta la arquitectura tal como existe en los repositorios públicos y luego especifica el token: utilidad, asignación (10% preventa / 20% IDO / 10% liquidez DEX / 50% reserva DAO / 10% incentivos comunitarios), el lanzamiento en dos fases, el calendario de desbloqueo y las salvaguardas que mantienen justa la venta y soberana la reserva.", "whitepaper.toc1": "El bucle de soberanía", "whitepaper.toc2": "Arquitectura: aislamiento e identidad", "whitepaper.toc3": "Los cuatro órganos", "whitepaper.toc4": "Economía del token SPARK", "whitepaper.toc4b": "El lanzamiento de doble vía", "whitepaper.toc5": "Gobernanza de la reserva", "whitepaper.toc6": "Hoja de ruta hacia TGE", "whitepaper.toc7": "Riesgos y descargos", "whitepaper.ch1": "El bucle de soberanía", "whitepaper.ch1_p1": "Este es <b>un proyecto, no un portafolio de productos</b>. Cada repositorio es un órgano; los órganos comparten un torrente sanguíneo — SPARK. Un usuario chatea en Engine; cada mensaje quema combustible; el combustible se deposita en la reserva Aether; la reserva se mantiene líquida por la IA licenciada en Havix; los efectos de red de Havix mantienen vivo a Engine; y la demanda de Engine da a SPARK su respaldo físico. Corta cualquier órgano y el bucle deja de girar.", "whitepaper.th_organ": "Órgano", "whitepaper.th_metaphor": "Metáfora", "whitepaper.th_function": "Función en el bucle", "whitepaper.th_status": "Estado real", "whitepaper.rv_mt": "la Caja Fuerte", "whitepaper.rv_fn": "custodia offline de cada clave privada; firma por proxy; migra claves solo por QR", "whitepaper.rv_st": "v3.70.0 publicado", "whitepaper.re_mt": "la App", "whitepaper.re_fn": "mensajero social soberano; memoria pura, cifrado E2E; gasta SPARK por kilobyte", "whitepaper.re_st": "v3.64.7 publicado", "whitepaper.rs_mt": "el Combustible", "whitepaper.rs_fn": "mide la expresión; dota la reserva; une reserva y mercados", "whitepaper.rs_st": "preventa + IDO", "whitepaper.ra_mt": "el Parlamento", "whitepaper.ra_fn": "DAO gobernada por SBT: tres cámaras, rangos soulbound, tesorería multisig", "whitepaper.ra_st": "v3.6 · BSC · auditoría cerrada · mainnet pendiente", "whitepaper.rh_mt": "la Raíz de Identidad", "whitepaper.rh_fn": "identidades paralelas derivadas de master-DID: derivación de 4 contextos, vía dual crédito-valor, plano de licencia de IA", "whitepaper.rh_st": "beta cerrada M10", "whitepaper.rig_mt": "el Cerebro", "whitepaper.rig_fn": "IA a nivel de nodo que razona con su propia identidad", "whitepaper.rig_st": "etapa futura", "whitepaper.ch1_meta": "Las metáforas son la arquitectura: la <mark class=\"key\">Caja Fuerte nunca toca la red</mark>, el <mark class=\"key\">Parlamento gobierna por SBT soulbound</mark>, el <mark class=\"key\">Cerebro se licencia, no se confía</mark>. Todo lo siguiente se remonta a código público<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>.", "whitepaper.ch2": "Arquitectura: aislamiento e identidad", "whitepaper.h21": "El aislamiento físico como modelo de seguridad", "whitepaper.ch2_p1": "La decisión de seguridad raíz del bucle es <b>separación por física, no por política</b>. Engine opera online pero tiene cero claves privadas; Vault tiene las claves y está construida <mark class=\"key\">sin ningún permiso de red</mark> — su manifiesto Android no declara permiso INTERNET, lo que convierte el robo en un problema físico y no lógico<sup><a href=\"#cite-3\">[3]</a></sup>. Las solicitudes de firma viajan de Engine a Vault por IPC protegido por firma; el material de claves solo viaja entre dispositivos como marcos QR cifrados — cámara a cámara, con aislamiento forzado<sup><a href=\"#cite-3\">[3]</a></sup>.", "whitepaper.ch2_p2": "La confianza es auditable: los módulos <span class=\"mono\">core/</span> de Engine (protocolo, cripto, IPC) son <b>idénticos byte a byte</b> a los de Vault, así ambas apps verifican contra la misma fuente pública<sup><a href=\"#cite-1\">[1]</a></sup>. Los mensajes se cifran de extremo a extremo con acuerdo de claves ECDH y AES-256-GCM; el relay ve sobres, nunca texto plano<sup><a href=\"#cite-1\">[1]</a></sup>.", "whitepaper.h22": "Una identidad, cuatro contextos no vinculables", "whitepaper.ch2_p3": "Havix deriva cuatro sub-identidades por contexto de una sola clave maestra usando HKDF — contextos público, mercado, túnel y wiki<sup><a href=\"#cite-6\">[6]</a></sup>. La derivación es criptográficamente no vinculable: tu persona de mercado no puede correlacionarse con tu correspondencia privada. Esto permite que una persona sea a la vez <mark class=\"key\">ciudadano en el Parlamento, trader en el mercado y persona privada en el chat</mark> — sin tres cuentas y sin una plataforma que tenga el mapeo.", "whitepaper.h23": "Tres planos, un bucle", "whitepaper.ch2_li1": "<b>Plano de aplicación (online):</b> Engine — orientada al usuario, sin claves, memoria pura. Los mensajes viven en RAM; la superficie de ataque para incautación es casi cero.", "whitepaper.ch2_li2": "<b>Plano de custodia (offline):</b> Vault — almacenes de claves sellados tras biométricos, exporte solo por QR.", "whitepaper.ch2_li3": "<b>Plano de coordinación (P2P off-chain):</b> Havix — derivación de identidad, libros de reputación/crédito, arbitraje y la carta que licencia la IA<sup><a href=\"#cite-6\">[6]</a></sup>.", "whitepaper.ch2_li4": "<b>Plano de liquidación (on-chain):</b> Aether en BNB Smart Chain — gobernanza, tesorería y ejecución con timelock, gobernado por rango SBT soulbound en lugar de oferta transferible<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch2_p4": "La propia hoja de ruta de Havix formaliza esto como una pila de tres capas — base de red (L0), ejecución cognitiva (L1, Germ), gobernanza on-chain (L2, Aether) — con el DID de 4 contextos imponiendo la separación criptográfica entre capas<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch3": "Los cuatro órganos", "whitepaper.h31": "Vault — la Caja Fuerte", "whitepaper.note31": "v3.70.0 · publicado", "whitepaper.ch3_p1": "Un almacén de claves offline genérico, no un accesorio de Engine: puede custodiar claves de cualquier app compatible. Mecanismo: sin permiso de red; almacenes sellados en el TEE; firma con puerta biométrica (respaldada por StrongBox donde esté disponible); custodia de wallet SPARK — el saldo vive como cadena de solo-append co-firmada en el mundo seguro, y un traspaso migra el saldo completo a un dispositivo nuevo como tx genésis; migración solo por QR al hardware nuevo, con la clave privada nunca entrando a una pila de red<sup><a href=\"#cite-3\">[3]</a></sup>. Desde v3.40 Engine alcanza Vault por un canal IP directo Binder protegido por firma — los viejos diálogos de salto entre apps han desaparecido<sup><a href=\"#cite-3\">[3]</a></sup>.", "whitepaper.ch3_p2": "El punto de entrada al mercado de todo el bucle: un mensajero social soberano con arquitectura de memoria pura, mensajería de grupo, una economía de expresión de 60 emojis y perfiles DID<sup><a href=\"#cite-1\">[1]</a></sup>. Su motor económico ya está especificado en el repositorio: <mark class=\"key\">un kilobyte cuesta diez SPARK</mark> — cada mensaje se mide por su tamaño UTF-8, redondeando hacia arriba, con un mínimo de diez SPARK por mensaje; un subsidio diario de combustible de 1,000 SPARK (idempotente por día calendario, regido por el libro autorizado, condicionado por una identidad Vault vinculada); los usuarios intensivos recargan desde una wallet<sup><a href=\"#cite-2\">[2]</a></sup>. El saldo de la wallet no es un número almacenado: es la derivación de una cadena de solo-append co-firmada por la clave de wallet que posee Vault — cada cambio de saldo, sin excepción, es una transacción firmada<sup><a href=\"#cite-2\">[2]</a></sup>. Se implementa la deducción previa del lado del cliente; un servicio spark-ledger independiente liquida saldos del lado del servidor<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.h33": "Aether — el Parlamento", "whitepaper.note33": "v3.6 · BSC · auditoría cerrada · mainnet pendiente", "whitepaper.ch3_p3": "Un núcleo DAO gobernado por SBT en BNB Smart Chain. El peso se gana, no se compra: AetherRing acuña 14 rangos soulbound no transferibles; tres cámaras (Consejo, Parlamento, Ancianos) más un referéndum ciudadano se verifican mutuamente en un ciclo de vida de propuesta de 7 etapas con veto de los ancianos; la tesorería es un multisig 3/5 Safe que ejecuta llamadas con timelock<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>. La tensión de diseño deliberada: <mark class=\"key\">la gobernanza es soulbound (SBT) mientras el combustible es un activo real emitido</mark> — las ballenas pueden comprar $SPARK, pero $SPARK compra mensajes, no votos. Un contrato destaca: AetherDonation es un <b>canal de filantropía externa</b> (propinas USDC para bienes públicos) e independiente de la economía del bucle.", "whitepaper.h34": "Havix — la Raíz de Identidad", "whitepaper.note34": "validado · en espera", "whitepaper.ch3_p4": "La red de coordinación bajo el bucle: ocho módulos (identidad, tipos de mensaje, crédito, aval, wiki, arbitraje, mercado, tiempo de ejecución s-node), 1,174 pruebas aprobadas (MVP 980 + experimento de validación 194, línea base de auditoría M10), y un programa de auditoría de dos rondas — M9 cerró los 15 hallazgos, mientras la auditoría profunda M10 sacó 52 más (5 P0 + 15 P1 + 32 P2) con P0/P1 remediados antes de la beta cerrada<sup><a href=\"#cite-6\">[6]</a></sup>. Su carta es lo que pone a la IA en un pie legal y no mágico: las operaciones rutinarias se ejecutan automáticamente con recibos; <mark class=\"key\">las operaciones de línea roja se enrutan físicamente a un voto humano on-chain</mark>. El almacén de la carta y el interceptor están programados como el flujo de trabajo M11<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.h35": "Germ — el Cerebro, más tarde", "whitepaper.ch3_p5": "Germ es la capa de IA a nivel de nodo: IA que razona con sus propias identidades de 4 contextos en la red Havix. Está deliberadamente diferida — <mark class=\"key\">Engine es la entrada de mercado de hoy</mark>; el Cerebro llega cuando el bucle tenga usuarios que valga la pena cuidar. En este whitepaper Germ aparece solo donde la economía debe reservarle espacio (IA de reserva, §5).", "whitepaper.ch4": "Economía del token SPARK", "whitepaper.h41": "Utilidad: combustible con física detrás", "whitepaper.ch4_p1": "SPARK es un <b>activo de medición</b>. En Engine, cada kilobyte cuesta 10 SPARK — medido por tamaño de mensaje, redondeado hacia arriba, mínimo 10 por mensaje — el contador está en el protocolo, no en los términos de servicio<sup><a href=\"#cite-2\">[2]</a></sup>. Los presupuestos derivan de una línea base real de relay de 100&nbsp;Mbps: sobres de texto hasta 40&nbsp;KB, medios hasta 48&nbsp;KB, un techo duro de marco de 128&nbsp;KB, grupos limitados a 200<sup><a href=\"#cite-1\">[1]</a></sup>. Como cada byte expresivo cuesta combustible, el spam tiene un costo marginal y la palabra sigue siendo libre.", "whitepaper.ch4_li1": "<b>Adquirir:</b> subsidio diario de combustible (1,000 SPARK por día calendario, idempotente, condicionado por una identidad Vault vinculada<sup><a href=\"#cite-2\">[2]</a></sup>), recarga de wallet<sup><a href=\"#cite-2\">[2]</a></sup>, o compra de mercado tras TGE.", "whitepaper.ch4_li2": "<b>Gastar:</b> combustible de mensajería; presupuestos de grupo y medios; uso de apps SDK.", "whitepaper.ch4_li3": "<b>Tener:</b> la tesorería DAO tiene SPARK como su reserva a largo plazo — la demanda del uso real se acumula simétricamente a cada poseedor.", "whitepaper.ch4_note": "◇ Los parámetros de diseño (duraciones de vesting, bloqueo de LP, enrutamiento de comisiones, decaimiento de asignaciones) son valores predeterminados recomendados de este borrador; cada uno lo confirma o enmienda la gobernanza antes de abrir la preventa. Las tarifas de medición on-chain (1 KB = 10 SPARK, mínimo 10 por mensaje; subsidio diario de 1,000 por día calendario) están fijas en la especificación de Engine<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.h42": "Dos fases del mismo activo — libro de medición, luego oferta fija", "whitepaper.ch4_p2": "SPARK se lanza en dos etapas deliberadas, y la secuencia es el diseño. <b>Fase A — libro de medición (activo hoy):</b> dentro del software de Engine publicado, SPARK existe como un libro encadenado por hash off-chain. Cada dispositivo acuña <b>1,000 por día calendario</b> mediante un subsidio de combustible co-firmado por Vault — las defensas anti-sybil ya están en producción: un ancla de dispositivo TEE/DRM, deduplicación diaria del lado del relay de hashes de dispositivos no vinculables, y una lista blanca de montos aplicada en la puerta de firma. Los saldos de la Fase A son <mark class=\"key\">no transferibles, no negociables, no convertibles</mark> — hoy son cuota, no valores.", "whitepaper.ch4_p3": "<b>Fase B — mapeo de TGE (planificado):</b> la <b>oferta fija de 1,000T</b> toma efecto en TGE. La oferta inicial combina los tramos de preventa, IDO, liquidez y reserva del §4.3 con un mapeo basado en instantánea de los saldos de la Fase A al tramo de incentivos comunitarios — los parámetros de conversión específicos son valores predeterminados ◇ confirmados por gobernanza antes de abrir la preventa. Tras TGE, SPARK circula libremente, <b>incluidos pares abiertos de USDC y otras stablecoins</b>. El canal de conversión está deliberadamente sin construir hoy: el anclaje de dispositivo, la deduplicación diaria y la lista blanca de montos deben existir <i>antes</i> de que haya una caja fuerte que defender, para que el día que abra la convertibilidad estas defensas pasen de higiene de cuota a puertas de bóveda.", "whitepaper.h43": "Suministro y asignación", "whitepaper.ch4_p4": "El suministro total está fijado en <b>1,000T SPARK (1,000,000,000,000,000 — un mil billones)</b>. La asignación sigue la división 10 / 20 / 10 / 50 / 10: preventa, IDO, liquidez DEX, reserva DAO, incentivos comunitarios. No hay <mark class=\"key\">tramo de equipo, ni asignación de conocidos, ni tramo de marketing</mark> — el techo del equipo es la reserva del 50% que comparte con el DAO, liberada solo mediante gobernanza pública y limitada por estatuto a ≤5% de la reserva al año.", "whitepaper.fig1": "Figura 1 — Asignación de SPARK en TGE (refinada: 10 segmentos, 5 tramos)", "whitepaper.fig1_sub": "Suministro total 1,000T (1,000,000,000,000,000). La preventa divide 2.5% en TGE + 7.5% de vesting; el IDO divide 5% en TGE + 15% vesting (ambos tramos: 25% en TGE, luego lineal de 9 meses); las subdivisiones de reserva son valores predeterminados limitados por estatuto ◇ con liberación tope de ≤5%/año — la reserva misma no tiene desbloqueo de calendario.", "whitepaper.th_tranche": "Tramo", "whitepaper.th_share": "Participación", "whitepaper.th_amount": "Cantidad", "whitepaper.th_unlock": "Desbloqueo", "vault.foot_home": "Inicio", "whitepaper.ch4b": "El lanzamiento de doble vía", "whitepaper.h44": "Fase 1 — Preventa (10%)", "whitepaper.h45": "Fase 2 — IDO (20%)", "whitepaper.h46": "Liquidez y DEX (10%)", "whitepaper.h47": "Calendario de desbloqueo", "whitepaper.h48": "Salvaguardas y cumplimiento", "whitepaper.h32": "Engine — la App", "whitepaper.note32": "v3.64.7 · publicado", "whitepaper.ch5": "Gobernanza de la Reserva", "whitepaper.ch6": "Hoja de ruta hacia TGE", "whitepaper.ch7": "Riesgos y notas de descargo", "whitepaper.fig2": "Figura 2 — Oferta circulante tras TGE", "whitepaper.m1": "preventa — lista blanca · tope de $500", "whitepaper.m2": "IDO — LBP · 3–7 días", "whitepaper.m3": "liquidez — sembrada en TGE", "whitepaper.m4": "incentivos comunitarios — referidos y activación", "whitepaper.m5": "reserva DAO — con gobernanza · ≤5%/año", "whitepaper.tl_now_t": "El bucle en el mundo real", "whitepaper.tltge_t": "Evento de generación del token", "whitepaper.tl01_t": "Lista blanca y parámetros finales", "whitepaper.tl02_t": "Ventana de preventa", "whitepaper.tl03_t": "IDO en el LBP", "whitepaper.tl9_t": "El float se completa · el DAO asume la reserva", "whitepaper.tll1_t": "Germ, más tarde", "whitepaper.src": "Fuentes", "whitepaper.src6": "eneatlnc-cell, repositorio Havix — red de identidad paralela: 8 módulos, 1,174 pruebas (línea base de auditoría M10), 15 hallazgos de auditoría cerrados.", "whitepaper.src1": "eneatlnc-cell, Engine 3.0 — edición de auditoría pública del stack de protocolo E2EE (core-crypto, core-protocol, core-ipc; AGPL-3.0).", "whitepaper.src2": "Engine, registro de ingeniería SparkEconomy (interno) — 1 KB = 10 SPARK (mínimo 10 por mensaje), subsidio diario de combustible de 1,000 por día calendario, wallet SPARK de transacciones firmadas (v3.37+), recarga de wallet, plan de servicio spark-ledger.", "whitepaper.src3": "eneatlnc-cell, Engine 3.0 — core-ipc: el contrato de firma Engine↔Vault detrás del almacén offline (sin permiso de red, firma biométrica, migración por QR).", "whitepaper.src4": "eneatlnc-cell, repositorio Aether — núcleo DAO gobernado por SBT: AetherRing, Governance, Election, tesorería Safe.", "whitepaper.src5": "Aether, docs/TECHNICAL_WHITEPAPER.md — tres cámaras, ciclo de vida de 7 etapas, veto de ancianos, equilibrio cámara/ciudadano.", "whitepaper.src7": "Havix, NEXT-STEPS.md — pila de tres capas L0/L1/L2, plan del almacén de carta M11 e interceptor de línea roja.", "whitepaper.foot_copy": "© <span class=\"yr\">2026</span> SparkLoop · Whitepaper v1.0 borrador", "whitepaper.foot_cta": "Únete a la lista blanca de preventa", "whitepaper.tr_presale_amt": "100T", "whitepaper.tr_presale_t": "Preventa — lista blanca", "whitepaper.tr_tge_amt": "25T", "whitepaper.tr_tge_t": "└ desbloqueo TGE", "whitepaper.tr_tge_un": "Líquido en TGE", "whitepaper.tr_9m_amt": "75T", "whitepaper.tr_9m_t": "└ vesting de 9 meses", "whitepaper.tr_9m_un": "Lineal, meses 1–9", "whitepaper.tr_a_un": "25% en TGE ◇, luego lineal de 9 meses ◇", "whitepaper.tr_b_un": "25% en TGE ◇, luego lineal de 9 meses ◇", "whitepaper.tr_ido_amt": "200T", "whitepaper.tr_ido_t": "IDO — ronda pública LBP", "whitepaper.tr_tge2_amt": "50T", "whitepaper.tr_tge2_t": "└ desbloqueo TGE", "whitepaper.tr_9m2_amt": "150T", "whitepaper.tr_9m2_t": "└ vesting de 9 meses", "whitepaper.tr_dex_amt": "100T", "whitepaper.tr_dex_t": "Liquidez DEX", "whitepaper.tr_dex_un": "Sembrada en el pool en TGE · LP bloqueado 12 meses ◇", "whitepaper.tr_dao_amt": "500T", "whitepaper.tr_dao_t": "Reserva DAO", "whitepaper.tr_dao_un": "Sin calendario — solo por propuesta de Aether · tope de carta ≤5%/año", "whitepaper.tr_comm_amt": "100T", "whitepaper.tr_comm_t": "Incentivos comunitarios", "whitepaper.tr_comm_un": "Bonos por referidos + subvenciones de activación · se liquida por programa", "whitepaper.tr_fuel_amt": "150T", "whitepaper.tr_fuel_t": "└ subsidios de combustible Engine", "whitepaper.tr_fuel_un": "Predeterminado de carta ◇ — épocas de subsidio", "whitepaper.tr_relay_amt": "100T", "whitepaper.tr_relay_t": "└ relay e infraestructura", "whitepaper.tr_relay_un": "Predeterminado de carta ◇ — relays, s-nodes", "whitepaper.tr_eco_amt": "150T", "whitepaper.tr_eco_t": "└ subvenciones de ecosistema", "whitepaper.tr_eco_un": "Predeterminado de carta ◇ — apps, relays, herramientas", "whitepaper.tr_ai_amt": "100T", "whitepaper.tr_ai_t": "└ liquidez y dotación de IA", "whitepaper.tr_ai_un": "Predeterminado de carta ◇ — límites de IA", "whitepaper.ch4b_p1": "El núcleo del lanzamiento es <b>preventa + IDO en paralelo, a distinto ritmo</b>: la preventa apunta a la comunidad núcleo; el IDO sale al público. <mark class=\"key\">La preventa construye la base; el IDO abre el mercado.</mark>", "whitepaper.ch4b_li1": "<b>Audiencia:</b> solo primeros contribuidores núcleo y miembros activos de la comunidad. Las direcciones se recogen por adelantado en una lista blanca; el inicio se anuncia primero a la lista.", "whitepaper.ch4b_li2": "<b>Anti-ballena:</b> un <mark class=\"key\">tope duro de $500 por wallet</mark>.", "whitepaper.ch4b_li3": "<b>Términos:</b> pagar con USDT o BNB a un precio bajo fijo; 25% se desbloquea en TGE, el resto viste linealmente en 9 meses ◇.", "whitepaper.ch4b_li4": "<b>Ejecución:</b> al abrir la ventana, las wallets de la lista blanca se conectan en el sitio oficial y suscriben dentro del tope.", "whitepaper.ch4b2_li1": "<b>Plataforma:</b> un launchpad LBP de la clase Fjord Foundry — el precio empieza alto y decae hasta que la demanda lo alcanza, lo que <mark class=\"key\">elimina la ventaja del sniping</mark>; sin lista blanca, sin ventaja de primer bloque.", "whitepaper.ch4b2_li2": "<b>Parámetros:</b> dirección del token verificada tres veces antes de financiar el pool (irreversible); pago en USDT o BNB; ventana de 3–7 días; topes mínimos y máximos por wallet; precio inicial por encima del de preventa.", "whitepaper.ch4b2_li3": "<b>Distribución:</b> el 25% de la asignación de cada wallet es reclamable en TGE, el resto viste linealmente en 9 meses ◇; los fondos van directos al multisig del proyecto.", "whitepaper.ch4b2_li4": "<b>Contabilidad:</b> tras cerrar la ventana, la lista de suscripciones y montos se concilian y publican antes de la distribución.", "whitepaper.ch4b3_note": "Las direcciones se publican en la página de Spark en el momento del despliegue. Antes, cualquier dirección que afirme ser SPARK es fraudulenta.", "whitepaper.ch4b3_p1": "En TGE el tramo de liquidez siembra el pool DEX, emparejado con BNB. Se recomienda emitir SPARK como token BEP-20 en BNB Chain ◇ — alineado con los rieles de pago USDT/BNB de ambas rondas — con la tesorería y gobernanza de Aether desplegadas en la misma BNB Smart Chain<sup><a href=\"#cite-4\">[4]</a></sup>, así las operaciones de reserva se liquidan nativamente sin puente cross-chain<sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch4b4_p1": "La promesa estructural es un <mark class=\"key\">techo de float duro</mark>: el calendario nunca puede desbloquear más del 40% (preventa + IDO + LP); el tramo de incentivos del 10% solo paga contra referidos y activaciones verificados; y la reserva del 50% solo se mueve mediante una propuesta pública y vetable, con la carta limitando liberaciones a <b>≤5% de la reserva al año</b>. Los compradores tempranos saben exactamente cuál es el float máximo.", "whitepaper.ch5_p1": "La reserva del 50% no es una wallet de tesorería — es un <b>objeto constitucional</b>. La custodia está en un multisig 3/5 Safe; cada movimiento requiere una propuesta por el ciclo de 7 etapas de Aether, sobrevive la ventana de veto de los ancianos y se ejecuta por timelock<sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-5\">[5]</a></sup>. El peso en ese proceso es soulbound y se gana — 14 rangos AetherRing que no se pueden comprar ni transferir<sup><a href=\"#cite-4\">[4]</a></sup>.", "whitepaper.ch5_p2": "Los usos de la reserva están limitados por la carta: épocas de subsidio a usuarios para combustible Engine, financiación de relay e infraestructura, subvenciones de ecosistema y — una vez que exista Germ — gestión de liquidez por IA autorizada dentro de límites duros, con líneas rojas que vuelven a votos humanos<sup><a href=\"#cite-6\">[6]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>. La carta también fija un <mark class=\"key\">techo de tasa de liberación de ≤5% de la reserva al año</mark> — una promesa computable, no discrecional: incluso una tesorería capturada no puede drenar la reserva más rápido de un veinteavo al año. El equilibrio es deliberado: <mark class=\"key\">las cámaras y los ciudadanos tienen cada una la mitad del peso de voto</mark>, así ni la institución ni el público pueden gastar la reserva solos<sup><a href=\"#cite-5\">[5]</a></sup>.", "whitepaper.ch7_disc": "<b>Descargo.</b> Este whitepaper describe un proyecto de software de código abierto y su activo de combustible. No es asesoramiento de inversión, no es una oferta de venta de valores ni una promesa de rendimientos. Los parámetros marcados ◇ son valores predeterminados de borrador sujetos a cambios antes del lanzamiento. No hay marketing de «créeme» en este bucle: lee los repositorios.", "whitepaper.ch7_li1": "<b>Riesgo de ejecución:</b> el despliegue de Aether en mainnet, el almacén de carta M11 y el servicio spark-ledger son componentes sin terminar de los que depende la secuencia de TGE<sup><a href=\"#cite-2\">[2]</a></sup><sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch7_li2": "<b>Riesgo cross-chain:</b> mitigado por diseño — SPARK y la gobernanza/tesorería de Aether se despliegan en la misma BNB Smart Chain ◇, así las operaciones de reserva se liquidan nativamente sin dependencia de puentes.", "whitepaper.ch7_li3": "<b>Riesgo de mercado:</b> un LBP descubre el precio con honestidad — lo que significa que puede descubrirlo hacia abajo. El precio bajo fijo de la preventa compensa la confianza temprana pero no garantiza rendimientos.", "whitepaper.ch7_li4": "<b>Riesgo regulatorio:</b> los lanzamientos de tokens enfrentan regulación divergente; pueden aplicarse restricciones por jurisdicción; la revisión de asesoría es una condición previa, no una formalidad.", "whitepaper.ch7_li5": "<b>Riesgo de contratos inteligentes:</b> las auditorías reducen pero nunca eliminan el riesgo; interactúa solo con direcciones publicadas en el sitio oficial.", "whitepaper.fig2_sub": "Float líquido: 17.5% en TGE (2.5% preventa + 5% IDO + 10% LP), subiendo 2.5% al mes conforme visten ambos tramos y llegando a su techo de calendario del 40% en el mes 9. El tramo de incentivos del 10% se liquida por programa; el 50% restante solo se mueve por gobernanza, con tope de carta de ≤5%/año.", "whitepaper.tl_now_d": "Engine v3.64.7 y Vault v3.70.0 publicados — el canal directo Binder IPC y el wallet SPARK de transacciones firmadas en vivo, versiones reforzadas con ofuscación R8 en ambas apps, y el subsidio diario de combustible deduplicado por un hash dispositivo-día no vinculable en el relay; Havix en beta cerrada tras cerrar 15 hallazgos; Aether v3.6 en BSC (remediación de auditoría cerrada), a la espera del despliegue mainnet<sup><a href=\"#cite-1\">[1]</a></sup><sup><a href=\"#cite-3\">[3]</a></sup><sup><a href=\"#cite-4\">[4]</a></sup><sup><a href=\"#cite-6\">[6]</a></sup>. Lista blanca de preventa abierta.", "whitepaper.tl01_d": "Direcciones recolectadas; confirmados precio de preventa, límites de IDO, vesting y parámetros de bloqueo LP; contratos auditados y direcciones publicadas.", "whitepaper.tl02_d": "Las wallets de la lista blanca suscriben con USDT/BNB dentro del tope de $500 al precio bajo fijo.", "whitepaper.tl03_d": "Ronda pública de 3–7 días; el precio se descubre solo; conciliación publicada al cierre.", "whitepaper.tl9_d": "Completado el vesting de preventa e IDO — el float de calendario alcanza su techo del 40%; la gobernanza mainnet de Aether asume el mandato de la reserva en pleno, con liberaciones limitadas por carta a ≤5%/año.", "whitepaper.tltge_d": "La distribución inicial de preventa 25% + IDO 25% llega a las wallets; el tramo de liquidez del 10% siembra el pool DEX; spark-ledger entra en vivo para la liquidación de Engine<sup><a href=\"#cite-2\">[2]</a></sup>.", "whitepaper.tll1_d": "La IA a nivel de nodo se une a la red bajo la carta — el Cerebro llega a cuidar un bucle que ya late<sup><a href=\"#cite-7\">[7]</a></sup>.", "whitepaper.ch4b5_li1": "<b>Seguridad:</b> los contratos de token, preventa y LBP deben tener auditorías de una firma reconocida antes de aceptar fondos; los informes se publican junto con las direcciones.", "whitepaper.ch4b5_li2": "<b>Transparencia:</b> las direcciones y reglas de los contratos de preventa e IDO se anuncian antes de cada ventana; la conciliación de suscripciones se publica antes de la distribución de TGE.", "whitepaper.ch4b5_li3": "<b>Anti-bot:</b> el decaimiento del precio LBP vence el sniping; los topes por wallet ($500 preventa; IDO mín/máx) limitan la concentración; pueden aplicarse límites de slippage dinámico al contrato de preventa ◇.", "whitepaper.ch4b5_li4": "<b>Legal:</b> el lanzamiento está siendo revisado por asesoría para las jurisdicciones implicadas; la participación puede restringirse donde sea necesario. Nada de esto es una oferta de valores."}
});
